// Flashcards dos temas do Estratégia (cronograma de 02/11/2026) sem cartão nas Revisões do VDE. r: 'E'.
// Texto reescrito a partir dos capítulos do Estratégia (nada copiado); b só quando o capítulo cita o dispositivo.
window.FC_VDE = (window.FC_VDE || []).concat([
  { id: "est-iter-criminis-01", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quais são as quatro etapas do iter criminis no crime doloso?", v: "Cogitação, preparação (atos preparatórios), execução e consumação.", b: null },
  { id: "est-iter-criminis-02", d: "Direito Penal", r: "E", t: "Iter criminis", f: "A cogitação e os atos preparatórios são puníveis?", v: "A cogitação nunca é punida, pois não atinge bem jurídico alheio. Os atos preparatórios, em regra, também não, salvo quando a lei os transforma em crime autônomo.", b: null, p: "Exceções: associação criminosa (art. 288, CP) e petrechos para falsificação de moeda (art. 291, CP) punem como crime próprio o que seria mera preparação." },
  { id: "est-iter-criminis-03", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Qual critério a doutrina majoritária usa para definir o início da execução?", v: "O critério objetivo-individual: a execução começa no momento imediatamente anterior à prática do verbo do tipo, quando o agente, conforme seu plano, passa a invadir a esfera do bem jurídico alheio.", b: null },
  { id: "est-iter-criminis-04", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quando há tentativa e qual a consequência na pena?", v: "Quando, iniciada a execução, o crime não se consuma por circunstâncias alheias à vontade do agente. Salvo disposição em contrário, aplica-se a pena do crime consumado reduzida de 1/3 a 2/3.", b: "art. 14, II e parágrafo único, CP", p: "Mandante que contrata executor que desiste antes de iniciar a execução não responde por nada: o fato ficou na preparação." },
  { id: "est-iter-criminis-05", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Qual a diferença entre desistência voluntária e arrependimento eficaz?", v: "Na desistência, o agente abandona a execução ainda em curso; no arrependimento eficaz, ele esgota a execução e depois age para impedir o resultado. Em ambos afasta-se a tentativa e ele responde só pelos atos já praticados.", b: "art. 15, CP", p: "Atirou uma vez, ainda tinha munição e foi embora: é desistência voluntária, responde pela lesão já causada, não por tentativa de homicídio." },
  { id: "est-iter-criminis-06", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quais os requisitos do arrependimento posterior e seu efeito?", v: "Crime sem violência ou grave ameaça à pessoa, reparação do dano ou restituição da coisa por ato voluntário até o recebimento da denúncia ou queixa. Reduz a pena de 1/3 a 2/3 e pressupõe crime consumado.", b: "art. 16, CP", p: "Não se aplica a roubo ou a qualquer crime com violência ou grave ameaça, nem a crime apenas tentado." },
  { id: "est-iter-criminis-07", d: "Direito Penal", r: "E", t: "Iter criminis", f: "O que é crime impossível e qual a consequência?", v: "Ocorre quando a consumação é impossível por ineficácia absoluta do meio ou impropriedade absoluta do objeto (ex.: arma desmuniciada, matar quem já está morto). A tentativa não é punida e o fato é atípico.", b: "art. 17, CP", p: "Para o STJ, loja com vigilância e câmeras não torna o furto crime impossível. Já o flagrante preparado gera crime impossível (Súmula 145 STF)." },
  { id: "est-intervencao-do-estado-na-01", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais são as modalidades de intervenção do Estado na propriedade?", v: "Limitação administrativa, servidão administrativa, ocupação temporária, requisição, tombamento e desapropriação, sendo esta a mais drástica, pois retira a propriedade.", b: null },
  { id: "est-intervencao-do-estado-na-02", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "O que caracteriza a limitação administrativa e ela gera indenização?", v: "É imposição geral e abstrata, baseada no poder de polícia, dirigida a proprietários indeterminados para adequar a propriedade à função social. Em regra é gratuita; só indeniza se reduzir o valor econômico do bem.", b: null, p: "Quem compra o imóvel depois de a limitação já estar imposta não tem direito a indenização." },
  { id: "est-intervencao-do-estado-na-03", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais as características da servidão administrativa?", v: "É ônus real sobre imóvel determinado, para obra ou serviço de utilidade pública (ex.: passagem de linhas de energia). Institui-se por acordo ou sentença, deve ser registrada no Registro de Imóveis e dura enquanto subsistir a necessidade pública.", b: null, p: "Não é direito pessoal nem tem prazo determinado." },
  { id: "est-intervencao-do-estado-na-04", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "A servidão administrativa gera indenização?", v: "Em regra não. Só há indenização se houver dano efetivo à propriedade, e ela nunca pode chegar ao valor total do bem, pois há mera restrição, não perda.", b: "art. 40, DL 3.365/41" },
  { id: "est-intervencao-do-estado-na-05", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "O que é a ocupação temporária e como é indenizada?", v: "Uso transitório de imóvel particular, em necessidade pública normal, para obras ou serviços (ex.: terreno não edificado vizinho à obra para guardar máquinas). Instituída por ato administrativo, é indenizada ao final, por ação própria, se houver prejuízo.", b: "art. 36, DL 3.365/41" },
  { id: "est-intervencao-do-estado-na-06", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Como a requisição se diferencia da ocupação temporária?", v: "A requisição pressupõe iminente perigo e pode recair sobre bens móveis, imóveis e serviços; a indenização é sempre posterior e só se houver dano. A ocupação temporária decorre de necessidade pública comum, sem perigo.", b: null },
  { id: "est-intervencao-do-estado-na-07", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais os pontos principais do tombamento?", v: "Protege o patrimônio histórico e artístico, podendo recair sobre móveis e imóveis. Cabe ao proprietário conservar o bem (salvo se não tiver recursos), só indeniza se houver desvalorização e admite destombamento se desaparecer o motivo.", b: null, p: "O STJ já admitiu que Município tombe bem estadual, porque tombar não transfere a propriedade (diferente da desapropriação)." },
  { id: "est-sociedades-em-conta-de-p-01", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Por que a sociedade em conta de participação não tem personalidade jurídica?", v: "Porque a própria lei não a confere, ao contrário da sociedade em comum, que fica sem personalidade por opção dos sócios de não registrá-la.", b: "art. 993, CC" },
  { id: "est-sociedades-em-conta-de-p-02", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Quem exerce a atividade na sociedade em conta de participação?", v: "Somente o sócio ostensivo, em nome próprio e sob sua exclusiva responsabilidade; os demais apenas participam dos resultados.", b: "art. 991, CC" },
  { id: "est-sociedades-em-conta-de-p-03", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Perante quem responde o sócio participante (oculto)?", v: "Só perante o sócio ostensivo, nos termos do contrato. Perante terceiros, apenas o ostensivo se obriga.", b: "art. 991, parágrafo único, CC", p: "O terceiro que contratou com o ostensivo não pode cobrar o sócio participante." },
  { id: "est-sociedades-em-conta-de-p-04", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "A sociedade em conta de participação tem nome empresarial?", v: "Não. Como não tem personalidade, também não tem nome empresarial; os negócios são feitos em nome do sócio ostensivo.", b: null },
  { id: "est-sociedades-em-conta-de-p-05", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Para que costuma servir a sociedade em conta de participação na prática?", v: "Funciona como instrumento de investimento em negócios específicos, com investidor que não quer aparecer (ex.: investidor-anjo em startup), ficando como sócio participante.", b: null },
  { id: "est-sociedades-limitadas-01", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual a responsabilidade dos sócios na sociedade limitada?", v: "Cada sócio responde até o valor de suas quotas, mas todos respondem solidariamente pela integralização do capital social.", b: "art. 1.052, CC", p: "Se algum sócio não integralizou (remisso), todos respondem perante credores pelo valor faltante." },
  { id: "est-sociedades-limitadas-02", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "A limitada pode ter um único sócio e qual nome empresarial adota?", v: "Sim, pode ser constituída por uma ou mais pessoas. Pode adotar firma ou denominação, sempre com a palavra 'limitada' (ou 'Ltda.') ao final.", b: null, p: "Omitir 'limitada' no nome pode levar à responsabilidade pessoal de quem usou o nome." },
  { id: "est-sociedades-limitadas-03", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Com o que o sócio pode contribuir para o capital da limitada?", v: "Com dinheiro ou bens; não se admite contribuição que consista apenas em prestação de serviços.", b: null },
  { id: "est-sociedades-limitadas-04", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual a regra da cessão de quotas na limitada, no silêncio do contrato?", v: "Entre sócios, a cessão é livre. Para terceiros estranhos, é possível desde que não haja oposição de titulares de mais de 1/4 do capital social.", b: "art. 1.057, CC" },
  { id: "est-sociedades-limitadas-05", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Quais os órgãos da limitada e como deliberam os sócios?", v: "Administração (obrigatória, por sócio ou não sócio) e conselho fiscal (facultativo, com 3 ou mais membros). Com até 10 sócios a deliberação pode ser em reunião; acima de 10, é obrigatória a assembleia.", b: null },
  { id: "est-sociedades-limitadas-06", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual o quórum para designar administrador não sócio na limitada?", v: "No mínimo 2/3 dos sócios enquanto o capital não estiver integralizado; mais da metade do capital social depois de integralizado.", b: null },
  { id: "est-sociedades-limitadas-07", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Que teoria de desconsideração da personalidade jurídica o Código Civil adota e quais os requisitos?", v: "A teoria maior: exige abuso da personalidade, por desvio de finalidade ou confusão patrimonial, decretado pelo juiz a pedido da parte ou do MP. Atinge só sócios ou administradores beneficiados direta ou indiretamente pelo abuso.", b: "art. 50, CC" },
  { id: "est-tratados-internacionais-01", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como a Convenção de Viena de 1969 define tratado?", v: "Acordo internacional escrito entre Estados, regido pelo Direito Internacional, em um ou mais instrumentos conexos, qualquer que seja sua denominação.", b: "art. 2º, 1, a, Convenção de Viena de 1969", p: "A definição da Convenção de 1969 abrange apenas acordos entre Estados, não 'Estados e/ou organizações internacionais'." },
  { id: "est-tratados-internacionais-02", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como se adota o texto de um tratado numa conferência internacional?", v: "Por maioria de 2/3 dos Estados presentes e votantes, salvo se, pela mesma maioria, decidirem outra regra. Fora de conferência, exige-se o consentimento de todos os participantes.", b: "art. 9º, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-03", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como funciona a ratificação de tratado no Brasil?", v: "O Presidente celebra, o Congresso Nacional autoriza e o Presidente ratifica, em ato discricionário, expresso e irretratável. Depois, a promulgação por decreto e a publicação no DOU internalizam o tratado.", b: null, p: "Mesmo com aprovação do Congresso, o Presidente pode deixar de ratificar." },
  { id: "est-tratados-internacionais-04", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O que é reserva e quando ela não é admitida?", v: "Declaração unilateral do Estado ao assinar, ratificar ou aderir, para excluir ou modificar efeitos de certas cláusulas. Não cabe se o tratado a proíbe, se só admite outras reservas ou se ela é incompatível com o objeto e a finalidade do tratado.", b: "art. 19, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-05", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O Estado pode invocar seu direito interno para descumprir tratado?", v: "Não. A parte não pode alegar normas internas para justificar o inadimplemento; a exceção é a violação manifesta de norma interna fundamental sobre competência para celebrar tratados.", b: "arts. 27 e 46, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-06", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O que acontece com tratado que conflita com norma de jus cogens?", v: "É nulo. Jus cogens é norma imperativa aceita pela comunidade internacional, que não admite derrogação e só pode ser modificada por norma posterior da mesma natureza.", b: "art. 53, Convenção de Viena de 1969", p: "A consequência é a nulidade, e não a mera suspensão da execução do tratado." },
  { id: "est-tratados-internacionais-07", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "A denúncia de tratado pelo Brasil precisa de aprovação do Congresso?", v: "Sim. O STF (ADI 1625, 2023) decidiu que a denúncia, assim como a ratificação, depende de aprovação do Congresso Nacional.", b: null, p: "Em tratado bilateral a denúncia extingue o acordo; em multilateral, ele deixa de valer só para quem denunciou." },
  { id: "est-adocao-01", d: "ECA", r: "E", t: "Adoção", f: "Quais as principais características da adoção?", v: "É medida excepcional, personalíssima (vedada por procuração), irrevogável e plena. É constituída por sentença e produz efeitos a partir do trânsito em julgado.", b: null, p: "A adoção internacional é ainda mais excepcional, só depois de esgotada a colocação no Brasil." },
  { id: "est-adocao-02", d: "ECA", r: "E", t: "Adoção", f: "O adotante que morre durante o processo pode ter a adoção deferida?", v: "Sim, se já tiver manifestado de forma inequívoca a vontade de adotar antes da sentença. Nesse caso, os efeitos retroagem à data do óbito.", b: "art. 42, § 6º, ECA", p: "Não depende de anuência dos herdeiros, e o efeito não se conta do trânsito em julgado." },
  { id: "est-adocao-03", d: "ECA", r: "E", t: "Adoção", f: "Quais os requisitos de idade para adotar?", v: "O adotante deve ter pelo menos 18 anos e ser, no mínimo, 16 anos mais velho que o adotado.", b: null },
  { id: "est-adocao-04", d: "ECA", r: "E", t: "Adoção", f: "Quem não pode adotar?", v: "Ascendentes e irmãos do adotando, que integram a família extensa. Tutor ou curador também não pode adotar o pupilo enquanto não prestar contas e quitar o que deve.", b: null },
  { id: "est-adocao-05", d: "ECA", r: "E", t: "Adoção", f: "Quais as regras do consentimento dos pais biológicos?", v: "Só vale se dado após o nascimento, depois de orientação, e prestado ou ratificado perante o juiz. Pode ser retratado até a audiência.", b: null, p: "Consentimento dado durante a gestação não tem valor." },
  { id: "est-adocao-06", d: "ECA", r: "E", t: "Adoção", f: "Quais os prazos do estágio de convivência e do processo de adoção?", v: "Estágio de convivência: até 90 dias, prorrogável por igual período; para adotante residente fora do país, de 30 a 45 dias, prorrogável uma vez. O processo deve terminar em até 120 dias, prorrogáveis por decisão fundamentada.", b: null },
  { id: "est-adocao-07", d: "ECA", r: "E", t: "Adoção", f: "Quando se dispensa a prévia inscrição no cadastro de adoção?", v: "Na adoção unilateral, na feita por parente com vínculo de afinidade e afetividade e na feita por quem já tem a tutela ou guarda legal de criança com mais de 3 anos.", b: null },
  { id: "est-teoria-da-pena-01", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual teoria das funções da pena o Código Penal adota?", v: "A teoria unitária (eclética), que soma retribuição e prevenção: prevenção geral negativa na cominação, prevenção geral positiva e retribuição na dosimetria, prevenção especial na execução.", b: "art. 59, CP" },
  { id: "est-teoria-da-pena-02", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual o limite de cumprimento de pena e o que ocorre com nova condenação por fato posterior?", v: "O limite é 40 anos. Se houver nova condenação por fato posterior, soma-se o saldo restante à nova pena e unifica-se de novo em 40, desprezando o tempo já cumprido.", b: "art. 75, CP", p: "Benefícios como a progressão são calculados sobre a pena total aplicada, não sobre os 40 anos (Súmula 715 STF)." },
  { id: "est-teoria-da-pena-03", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Quando se configura a reincidência e quando ela deixa de existir?", v: "Quando o agente comete novo crime após o trânsito em julgado de condenação anterior, no Brasil ou no exterior. Desaparece se passarem mais de 5 anos entre o fim do cumprimento ou a extinção da pena e o novo crime.", b: "arts. 63 e 64, CP", p: "Crimes militares próprios e crimes políticos não geram reincidência." },
  { id: "est-teoria-da-pena-04", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "A mesma condenação pode servir como reincidência e como maus antecedentes?", v: "Não, seria bis in idem. Mas, havendo duas condenações anteriores, uma pode agravar como reincidência e a outra pesar como maus antecedentes.", b: "Súmula 241 STJ" },
  { id: "est-teoria-da-pena-05", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "A confissão espontânea atenua a pena mesmo que não seja usada pelo juiz?", v: "Sim, em qualquer fase (policial ou judicial), ainda que não fundamente a condenação. A confissão qualificada (com alegação de excludente) também atenua.", b: "Súmula 545 STJ" },
  { id: "est-teoria-da-pena-06", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual a diferença entre as atenuantes do art. 65 e a atenuante genérica do art. 66 do CP?", v: "As do art. 65 são obrigatórias quando presentes. A do art. 66 é inominada: o juiz pode reduzir a pena por circunstância relevante não prevista em lei, e costuma ser ligada à teoria da coculpabilidade.", b: "art. 66, CP" },
  { id: "est-teoria-da-pena-07", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Em que prazo se paga a multa e quem a executa?", v: "Em até 10 dias após o trânsito em julgado, podendo ser parcelada. Se não for paga, é executada perante o juízo da execução penal (pelo MP), como dívida de valor.", b: "arts. 50 e 51, CP", p: "Não cabe habeas corpus contra condenação apenas a multa (Súmula 693 STF)." },
  { id: "est-responsabilidade-civil-d-01", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Qual teoria fundamenta, em regra, a responsabilidade civil do Estado e o que a vítima precisa provar?", v: "A teoria do risco administrativo: responsabilidade objetiva das pessoas de direito público e das privadas prestadoras de serviço público. Basta provar conduta, dano e nexo causal, sem discutir dolo ou culpa do agente.", b: "art. 37, § 6º, CF", p: "Mesmo ato lícito pode gerar dever de indenizar, mas só se o dano for anormal e específico." },
  { id: "est-responsabilidade-civil-d-02", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Qual a diferença entre risco administrativo e risco integral? Dê exemplo de risco integral.", v: "No risco administrativo o Estado pode afastar ou reduzir sua responsabilidade com excludentes (caso fortuito, força maior, culpa exclusiva da vítima ou de terceiro). No risco integral não há excludentes; a doutrina majoritária o aplica ao dano nuclear.", b: "art. 21, XXIII, d, CF" },
  { id: "est-responsabilidade-civil-d-03", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Como fica a responsabilidade do Estado por omissão?", v: "Pela visão tradicional, a omissão genérica gera responsabilidade subjetiva (culpa administrativa: é preciso provar dolo ou culpa). Na omissão específica, quando o Estado está na posição de garante (ex.: pessoa sob sua custódia), o STF aplica responsabilidade objetiva.", b: null },
  { id: "est-responsabilidade-civil-d-04", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "O Estado responde pela morte de detento, inclusive por suicídio?", v: "Em regra sim, objetivamente, por descumprir o dever específico de proteção do preso. Mas, por ser risco administrativo, o Estado pode provar excludente e afastar o dever de indenizar; a mesma lógica vale para alunos sob guarda em escola pública.", b: "art. 5º, XLIX, CF", p: "Nem todo suicídio de preso gera indenização: é preciso que o Estado tenha falhado no dever de proteção." },
  { id: "est-responsabilidade-civil-d-05", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "O Estado responde por crime cometido por preso foragido?", v: "Não, se não houver nexo causal direto entre o momento da fuga e o crime praticado (Tema 362 do STF). O dano causado pelo terceiro precisa ter ligação estreita com a omissão estatal.", b: "art. 37, § 6º, CF" },
  { id: "est-responsabilidade-civil-d-06", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "A vítima pode processar diretamente o servidor que causou o dano?", v: "Não. Pela tese da dupla garantia (STF, repercussão geral), a ação é proposta contra o Estado ou a prestadora de serviço público; o agente é parte ilegítima e só responde em regresso, se tiver agido com dolo ou culpa (responsabilidade subjetiva).", b: "art. 37, § 6º, CF" },
  { id: "est-responsabilidade-civil-d-07", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Concessionária de serviço público responde por furto e roubo ocorridos em suas dependências?", v: "Para o STF, a prestadora responde por furto em suas dependências (falha no dever de vigilância). Para o STJ, a concessionária de rodovia não responde por roubo e sequestro em estabelecimento de apoio ao usuário: roubo armado é fato de terceiro equiparado a força maior.", b: null, p: "A prestadora responde objetivamente tanto perante usuários quanto não usuários do serviço." },
  { id: "est-oferta-e-publicidade-pra-01", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Qual o efeito da oferta ou publicidade suficientemente precisa?", v: "Obriga o fornecedor que a veicula ou dela se aproveita e passa a integrar o contrato que vier a ser celebrado. O fornecedor responde solidariamente pelos atos de prepostos e representantes autônomos.", b: "art. 30, CDC" },
  { id: "est-oferta-e-publicidade-pra-02", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Se o fornecedor se recusar a cumprir a oferta, o que o consumidor pode fazer?", v: "À sua livre escolha: exigir o cumprimento forçado nos termos da oferta, aceitar outro produto ou serviço equivalente, ou rescindir o contrato com devolução do que pagou, corrigido, mais perdas e danos.", b: "art. 35, CDC" },
  { id: "est-oferta-e-publicidade-pra-03", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Diferencie publicidade enganosa de publicidade abusiva.", v: "Enganosa é a total ou parcialmente falsa, capaz de induzir o consumidor em erro sobre o produto ou serviço (natureza, qualidade, preço etc.). Abusiva é a que discrimina, incita violência ou explora medo ou superstição. Ambas são proibidas.", b: "art. 37, CDC", p: "Há publicidade enganosa por omissão quando se deixa de informar dado essencial do produto ou serviço (art. 37, § 3º)." },
  { id: "est-oferta-e-publicidade-pra-04", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Quem tem o ônus de provar a veracidade da informação publicitária?", v: "Quem patrocina a publicidade, não o consumidor.", b: null },
  { id: "est-oferta-e-publicidade-pra-05", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O envio de cartão de crédito sem solicitação do consumidor é permitido?", v: "Não. É prática abusiva, gera dano moral indenizável mesmo sem prejuízo comprovado e sujeita o banco a multa administrativa (que não vai para o consumidor). Quem foi exposto à prática é consumidor por equiparação.", b: "Súmula 532 STJ", p: "O rol de práticas abusivas do CDC é meramente exemplificativo." },
  { id: "est-oferta-e-publicidade-pra-06", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O que deve constar do orçamento prévio e qual sua validade?", v: "Valor da mão de obra, dos materiais e equipamentos, condições de pagamento e datas de início e término do serviço. Vale por 10 dias, contados do recebimento pelo consumidor; executar serviço sem orçamento e autorização expressa é prática abusiva.", b: null },
  { id: "est-oferta-e-publicidade-pra-07", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O banco pode debitar da conta-corrente o pagamento mínimo da fatura do cartão em atraso?", v: "Só se houver cláusula expressa, clara e destacada no contrato autorizando o débito; nesse caso, o STJ entende que a cláusula não é abusiva. Conta-corrente e cartão de crédito são contratos distintos.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-01", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quando e como foi aprovada a Declaração Universal dos Direitos Humanos?", v: "Em 10 de dezembro de 1948, em Paris, com 48 votos a favor, 8 abstenções (entre elas a URSS e países do bloco socialista, Arábia Saudita e África do Sul) e nenhum voto contrário. O Brasil votou a favor.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-02", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Como está estruturada a DUDH e o que diz seu artigo 1º?", v: "Preâmbulo mais 30 artigos com direitos civis e políticos, econômicos, sociais e culturais e cláusulas de deveres. O art. 1º afirma que todos nascem livres e iguais em dignidade e direitos, dotados de razão e consciência, e devem agir com fraternidade.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-03", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quais proibições da DUDH são consideradas absolutas?", v: "A proibição da escravidão e da servidão e a da tortura e de tratamentos cruéis, desumanos ou degradantes (arts. 4º e 5º). São normas de jus cogens, que não admitem derrogação nem em guerra ou emergência.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-04", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Por que existem dois Pactos de 1966 e o que formam junto com a DUDH?", v: "A Guerra Fria levou à separação: direitos civis e políticos (aplicação imediata, PIDCP) e econômicos, sociais e culturais (realização progressiva, PIDESC). Com a DUDH formam a Carta Internacional de Direitos Humanos.", b: null, p: "Apesar da divisão, a leitura atual é de indivisibilidade e interdependência, sem hierarquia entre os direitos." },
  { id: "est-dudh-pidcp-e-pidesc-05", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quais são os Protocolos Facultativos ao PIDCP?", v: "O Primeiro cria o direito de petição individual ao Comitê de Direitos Humanos; o Segundo visa abolir a pena de morte, admitindo reserva só em tempo de guerra para crimes militares gravíssimos. O PIDCP foi incorporado no Brasil pelo Decreto 592/1992.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-06", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quando o PIDCP permite derrogar direitos e quais são inderrogáveis?", v: "Em emergência pública que ameace a existência da nação, proclamada oficialmente, com medidas estritamente necessárias, sem discriminação e com notificação aos demais Estados. São inderrogáveis: vida, proibição de tortura, de escravidão e servidão, de prisão por dívida civil, legalidade e irretroatividade penal, personalidade jurídica e liberdade de pensamento, consciência e religião.", b: null },
  { id: "est-especies-de-erro-essenci-01", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quais as consequências do erro de tipo incriminador?", v: "Sempre exclui o dolo. Se inevitável (escusável), exclui também a culpa e o fato é atípico; se evitável, o agente responde pela forma culposa, se houver previsão legal.", b: "art. 20, CP", p: "Erro sobre a idade da vítima no estupro de vulnerável é erro de tipo: como não existe forma culposa, não há crime." },
  { id: "est-especies-de-erro-essenci-02", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é erro de tipo permissivo (descriminante putativa) e qual sua consequência?", v: "Erro sobre a situação de fato de uma excludente de ilicitude (ex.: legítima defesa putativa). Pela teoria limitada da culpabilidade, se inevitável isenta de pena; se evitável, o agente responde por crime culposo, se previsto.", b: "art. 20, § 1º, CP" },
  { id: "est-especies-de-erro-essenci-03", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é culpa imprópria?", v: "É a punição a título de culpa no erro de tipo permissivo evitável: o agente age com dolo, mas o dolo é afastado e ele responde pela forma culposa.", b: "art. 20, § 1º, CP", p: "É a única hipótese em que se admite tentativa de crime culposo." },
  { id: "est-especies-de-erro-essenci-04", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quais as consequências do erro de proibição?", v: "Recai sobre a consciência da ilicitude (elemento da culpabilidade). Se inevitável, isenta de pena; se evitável, reduz a pena de 1/6 a 1/3. O desconhecimento da lei, em si, é inescusável.", b: "art. 21, CP" },
  { id: "est-especies-de-erro-essenci-05", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Erro sobre a pessoa e erro na execução (aberratio ictus): qual a diferença e a consequência comum?", v: "No erro sobre a pessoa o agente confunde a identidade da vítima; no aberratio ictus ele erra o alvo por falha nos meios de execução. Em ambos responde como se tivesse atingido quem pretendia, considerando as qualidades dessa pessoa.", b: "art. 20, § 3º, e art. 73, CP", p: "Se atingir também a vítima pretendida, aplica-se o concurso formal (art. 70)." },
  { id: "est-especies-de-erro-essenci-06", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é aberratio criminis e quando ela não se aplica?", v: "Por erro na execução, sobrevém resultado diverso do pretendido (ex.: quer danificar coisa e mata alguém): responde só pelo resultado culposo, se previsto. Não se aplica no caso inverso (mira pessoa e atinge coisa), pois não há dano culposo: responde pela tentativa contra a pessoa.", b: "art. 74, CP" },
  { id: "est-especies-de-erro-essenci-07", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quem responde quando o erro é provocado por terceiro?", v: "Responde pelo crime o terceiro que determinou o erro; quem agiu enganado, sem culpa, não responde.", b: "art. 20, § 2º, CP" },
  { id: "est-ato-infracional-e-medida-01", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "O que é ato infracional e que medidas cabem para criança e para adolescente?", v: "É a conduta descrita como crime ou contravenção penal praticada por criança ou adolescente. À criança só se aplicam medidas de proteção; ao adolescente, medidas socioeducativas, que podem ser cumuladas com medidas de proteção.", b: null, p: "Considera-se praticado o ato no momento da ação ou omissão (teoria da atividade), ainda que o resultado venha depois." },
  { id: "est-ato-infracional-e-medida-02", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Quais os requisitos e o prazo da internação provisória?", v: "Decisão judicial fundamentada, com indícios de autoria e materialidade, pelo prazo máximo e improrrogável de 45 dias.", b: null, p: "Não pode ser decretada só com base na gravidade abstrata do ato." },
  { id: "est-ato-infracional-e-medida-03", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Em quais hipóteses cabe a medida de internação?", v: "Só em três: ato infracional com grave ameaça ou violência a pessoa; reiteração em outras infrações graves; ou descumprimento reiterado e injustificável de medida anterior. No último caso, a internação-sanção dura no máximo 3 meses.", b: "art. 122, ECA" },
  { id: "est-ato-infracional-e-medida-04", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "O que se exige para aplicar a advertência?", v: "Basta prova da materialidade e indícios de autoria; não é necessária prova plena da autoria. É a medida mais branda, uma admoestação verbal feita pelo juiz.", b: null, p: "Na remissão nem sequer se exige prova de autoria e materialidade." },
  { id: "est-ato-infracional-e-medida-05", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Quais os limites da prestação de serviços à comunidade?", v: "Tarefas gratuitas de interesse geral por no máximo 6 meses e até 8 horas semanais, inclusive em sábados, domingos e feriados, sem prejudicar a escola ou o trabalho.", b: null },
  { id: "est-ato-infracional-e-medida-06", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Qual a duração da liberdade assistida e até que idade as medidas podem ser cumpridas?", v: "A liberdade assistida dura no mínimo 6 meses; sem máximo na lei, o STJ aplica o teto de 3 anos da internação. Internação, semiliberdade e liberdade assistida podem ser cumpridas até os 21 anos.", b: null },
  { id: "est-ato-infracional-e-medida-07", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Como funciona a remissão no ECA?", v: "É perdão ou abrandamento que pode partir do MP (antes do processo, como exclusão, homologada pelo juiz) ou do juiz (no curso do processo, como suspensão ou extinção). Medida aplicada junto com a remissão exige concordância do adolescente e do defensor.", b: null },
  { id: "est-sistema-juridico-01", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais as principais diferenças entre direito e moral?", v: "O direito é heterônomo, bilateral (cria relação de direitos e deveres) e tem sanção externa e institucionalizada, com uso legítimo da força. A moral é autônoma, unilateral e sua sanção é interna ou social, sem organização institucional.", b: null, p: "A norma moral é só imperativa; a jurídica é imperativo-atributiva, pois dá a alguém o poder de exigir seu cumprimento." },
  { id: "est-sistema-juridico-02", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Qual a diferença entre o princípio da causalidade e o da imputação?", v: "As ciências naturais operam por causalidade (se A, então B: chove, então molha). A ciência jurídica atua no dever-ser pela imputação (se A, então deve ser B: quem rouba deve ser punido).", b: null },
  { id: "est-sistema-juridico-03", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "O que é lacuna ideológica e o que é lacuna ontológica?", v: "Ideológica (axiológica): existe norma, mas falta uma solução justa ou satisfatória para o caso. Ontológica: existe norma, mas ela perdeu eficácia social por dissociação com a realidade.", b: null, p: "Lacuna ideológica não é ausência de lei; a ausência de norma é a lacuna normativa." },
  { id: "est-sistema-juridico-04", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais os critérios para resolver antinomias e qual prevalece?", v: "Hierárquico (norma superior), cronológico (norma posterior) e especialidade (norma especial). O hierárquico prevalece sobre todos e a especialidade sobre o cronológico.", b: null, p: "Só há antinomia real se as normas forem absolutamente incompatíveis; se a interpretação as conciliar, os critérios não entram." },
  { id: "est-sistema-juridico-05", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Diferencie fonte formal de fonte material do direito.", v: "Fonte formal é a forma de manifestação do direito (lei, costumes, princípios gerais). Fonte material são os fatores políticos, econômicos e ideológicos que condicionam o conteúdo das normas.", b: null },
  { id: "est-sistema-juridico-06", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais os requisitos para um comportamento ser costume jurídico?", v: "Objetivo: prática constante, uniforme e reiterada no tempo. Subjetivo: crença na obrigatoriedade da conduta (opinio necessitatis).", b: null },
  { id: "est-sistema-juridico-07", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Tecnicamente, o que é jurisprudência?", v: "Conjunto de decisões judiciais reiteradas, constantes e harmônicas sobre casos semelhantes, formando orientação geral. Uma decisão isolada não é jurisprudência.", b: null },
  { id: "est-partes-e-procuradores-tu-01", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "O que é jus postulandi e onde ele não se aplica?", v: "É a possibilidade de empregado e empregador reclamarem pessoalmente, sem advogado, até o final. Limita-se às Varas e aos TRTs: não alcança ação rescisória, ação cautelar, mandado de segurança e recursos de competência do TST.", b: "art. 791, CLT; Súmula 425 TST" },
  { id: "est-partes-e-procuradores-tu-02", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Quem ajuíza a reclamação trabalhista do menor de 18 anos?", v: "Seus representantes legais; na falta deles, a Procuradoria da Justiça do Trabalho, o sindicato, o MP estadual ou curador nomeado em juízo.", b: "art. 793, CLT", p: "A ordem é sucessiva: só se passa ao próximo na falta do anterior." },
  { id: "est-partes-e-procuradores-tu-03", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Como o empregador e o empregado podem ser representados na audiência?", v: "O empregador pode ser substituído por gerente ou preposto que conheça os fatos, cujas declarações o obrigam. O empregado, por doença ou outro motivo poderoso comprovado, pode ser representado por colega da mesma profissão ou pelo sindicato.", b: "art. 843, §§ 1º e 2º, CLT", p: "O preposto não precisa ser empregado." },
  { id: "est-partes-e-procuradores-tu-04", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "O que é mandato tácito e quais seus limites?", v: "Constituição de advogado por simples registro em ata de audiência, a pedido verbal do advogado e com anuência da parte. Dá apenas poderes gerais para o foro: não permite atos que exigem poderes especiais (transigir, desistir, receber, dar quitação etc.).", b: "art. 791, § 3º, CLT", p: "É inválido o substabelecimento feito por advogado com mandato tácito (OJ 200 SDI-1)." },
  { id: "est-partes-e-procuradores-tu-05", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Recurso assinado por advogado sem procuração nos autos é conhecido?", v: "Não, salvo mandato tácito. Excepcionalmente, o advogado pode exibir a procuração em 5 dias após a interposição, sem intimação, prorrogáveis por igual período. Se a procuração já está nos autos mas tem defeito, o relator intima para sanar em 5 dias.", b: "Súmula 383 TST" },
  { id: "est-partes-e-procuradores-tu-06", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Procuradores de entes públicos precisam juntar procuração?", v: "Não. União, Estados, DF, Municípios, autarquias e fundações públicas, representados por seus procuradores, dispensam mandato e prova de nomeação, mas o signatário deve ao menos declarar que exerce o cargo de procurador.", b: "Súmula 436 TST", p: "Indicar só o número de inscrição na OAB não basta." },
  { id: "est-partes-e-procuradores-tu-07", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Litisconsortes com advogados diferentes têm prazo em dobro no processo do trabalho?", v: "Não. O TST considera o prazo em dobro do CPC incompatível com a celeridade do processo do trabalho.", b: "OJ 310 SDI-1 TST" },
  { id: "est-licitacoes-01", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Empresas públicas e sociedades de economia mista licitam pela Lei 14.133/2021?", v: "Não. Estatais e suas subsidiárias seguem a Lei 13.303/2016; a Lei 14.133/2021 vale para a administração direta, autárquica e fundacional de todos os entes.", b: "art. 1º, § 1º, Lei 14.133/2021", p: "A exceção do art. 178 (crimes) é a única parte da nova lei que alcança as estatais." },
  { id: "est-licitacoes-02", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Contratar cantor consagrado pela crítica ou pelo público, via empresário exclusivo, exige licitação?", v: "Não. É inexigibilidade, porque a competição é inviável; não se exige comparar orçamentos de outros artistas.", b: "art. 74, II, Lei 14.133/2021", p: "Não é dispensa (que depende de hipótese legal com competição possível), e o valor do cachê não muda a natureza da contratação." },
  { id: "est-licitacoes-03", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Na Lei 14.133/2021, compra ou locação de imóvel cujas instalações e localização tornem necessária sua escolha é dispensa ou inexigibilidade?", v: "Inexigibilidade. Na lei antiga era dispensa; a nova lei acolheu a visão doutrinária de que não há competição possível.", b: null },
  { id: "est-licitacoes-04", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Qual a ordem das fases da licitação na Lei 14.133/2021?", v: "Preparatória, divulgação do edital, propostas e lances, julgamento, habilitação, recursal e homologação. Em regra, o julgamento vem antes da habilitação.", b: "art. 17, Lei 14.133/2021" },
  { id: "est-licitacoes-05", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Como funciona o recurso contra o julgamento das propostas?", v: "A intenção de recorrer deve ser manifestada logo, mas as razões (3 dias úteis) só correm da intimação ou da ata de habilitação/inabilitação, pois os recursos são apreciados numa fase única.", b: "art. 165, I e § 1º, Lei 14.133/2021", p: "Não há efeito suspensivo automático nem 'pedido de reconsideração' como via própria contra o julgamento." },
  { id: "est-licitacoes-06", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Qual a vigência da ata de registro de preços e ela obriga a Administração a contratar?", v: "Vigora por 1 ano, prorrogável por igual período se o preço continuar vantajoso. Gera compromisso de fornecimento para o fornecedor, mas não obriga a Administração a contratar.", b: "arts. 83 e 84, Lei 14.133/2021", p: "Registro de preços não é modalidade de licitação: é procedimento auxiliar, feito por pregão, concorrência ou contratação direta." },
  { id: "est-licitacoes-07", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Quem responde por contratação direta indevida feita com dolo, fraude ou erro grosseiro?", v: "O contratado e o agente público responsável respondem solidariamente pelo dano ao erário, sem prejuízo de outras sanções.", b: "art. 73, Lei 14.133/2021" },
  { id: "est-orcamento-publico-leis-o-01", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Quem tem a iniciativa e qual a espécie normativa do PPA, da LDO e da LOA?", v: "Iniciativa privativa do Chefe do Executivo, sem substituição nem em caso de omissão; aprovação por lei ordinária do Legislativo, por maioria simples.", b: "art. 165, CF", p: "Medida provisória não pode aprovar lei orçamentária, e lei complementar não é exigida." },
  { id: "est-orcamento-publico-leis-o-02", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Investimento cuja execução ultrapasse um exercício pode começar sem estar no PPA?", v: "Não. Exige prévia inclusão no plano plurianual ou lei que autorize a inclusão, sob pena de crime de responsabilidade.", b: "art. 167, § 1º, CF" },
  { id: "est-orcamento-publico-leis-o-03", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Quais os prazos de envio e devolução do projeto de LDO, enquanto não vem a lei complementar?", v: "Envio até 15 de abril (8 meses e meio antes do fim do exercício) e devolução para sanção até o fim do primeiro período da sessão legislativa (17 de julho).", b: "art. 35, § 2º, II, ADCT", p: "A sessão legislativa não é interrompida sem a aprovação do projeto de LDO (art. 57, § 2º, CF)." },
  { id: "est-orcamento-publico-leis-o-04", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "O que diz o princípio da exclusividade da LOA e quais suas exceções?", v: "A LOA não pode conter matéria estranha à previsão de receita e fixação de despesa; pode, porém, autorizar abertura de créditos suplementares e contratação de operações de crédito, inclusive por antecipação de receita.", b: "art. 165, § 8º, CF" },
  { id: "est-orcamento-publico-leis-o-05", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Diferencie crédito suplementar, especial e extraordinário.", v: "Suplementar reforça dotação já existente; especial cria dotação para despesa não prevista; extraordinário atende despesa imprevisível e urgente (guerra, comoção interna ou calamidade pública).", b: "art. 41, Lei 4.320/1964", p: "Só o suplementar pode ser autorizado previamente na própria LOA; o especial exige sempre lei específica." },
  { id: "est-orcamento-publico-leis-o-06", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Como é aberto o crédito extraordinário e quando créditos especiais e extraordinários vigem no ano seguinte?", v: "O extraordinário pode ser aberto por medida provisória na União (decreto nos demais entes). Especiais e extraordinários autorizados nos últimos 4 meses do exercício podem ser reabertos, nos limites do saldo, no exercício seguinte.", b: "art. 167, §§ 2º e 3º, CF" },
  { id: "est-orcamento-publico-leis-o-07", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Se o Executivo não envia o projeto de LOA no prazo, o que o Legislativo faz?", v: "Não pode iniciar o projeto nem receber propostas parciais diretamente dos outros Poderes; considera como proposta a lei de orçamento vigente.", b: "art. 32, Lei 4.320/1964" },
  { id: "est-eia-rima-licenciamento-e-01", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quais são as três licenças do licenciamento trifásico e o que cada uma autoriza?", v: "Licença prévia: aprova localização e concepção e atesta a viabilidade ambiental; licença de instalação: autoriza a implantação conforme os projetos aprovados; licença de operação: autoriza o funcionamento após verificar o cumprimento das anteriores.", b: "art. 8º, Resolução Conama 237/1997" },
  { id: "est-eia-rima-licenciamento-e-02", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Licença ambiental válida pode ser modificada, suspensa ou cancelada?", v: "Sim, por decisão motivada, em caso de violação de condicionantes ou normas legais, omissão ou falsa informação relevante, ou superveniência de graves riscos ambientais e de saúde.", b: "art. 19, Resolução Conama 237/1997", p: "Lei nova mais protetiva não anula automaticamente a licença; o órgão precisa decidir de forma motivada." },
  { id: "est-eia-rima-licenciamento-e-03", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quando o EIA/RIMA é obrigatório e qual a diferença entre EIA e RIMA?", v: "Para obra ou atividade potencialmente causadora de significativa degradação ambiental. O EIA é o estudo técnico completo; o RIMA é sua síntese em linguagem acessível ao público — não existe RIMA sem EIA.", b: "art. 225, § 1º, IV, CF" },
  { id: "est-eia-rima-licenciamento-e-04", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quem pode pedir audiência pública no EIA/RIMA e o que acontece se ela não for feita?", v: "Órgão ambiental, Ministério Público, entidade civil ou 50 ou mais cidadãos, em prazo mínimo de 45 dias do edital. Se pedida e não realizada, a licença é inválida.", b: "art. 2º, Resolução Conama 9/1987", p: "O órgão não fica vinculado ao que se delibera na audiência, mas deve considerar o material produzido." },
  { id: "est-eia-rima-licenciamento-e-05", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quem elabora e custeia o estudo de impacto ambiental?", v: "Profissionais legalmente habilitados, às custas do empreendedor; ao órgão licenciador cabe apenas analisá-lo.", b: "art. 11, Resolução Conama 237/1997" },
  { id: "est-eia-rima-licenciamento-e-06", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "O que ocorre se o órgão licenciador perde o prazo sem emitir a licença?", v: "Não há licença tácita nem autorização para a atividade; instaura-se a competência supletiva de outro ente (ex.: a União no lugar do Estado).", b: "art. 14, § 3º, LC 140/2011", p: "Não confundir com atuação subsidiária, que é apoio pedido pelo próprio ente originalmente competente." },
  { id: "est-eia-rima-licenciamento-e-07", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Outro ente pode autuar empreendimento licenciado por um Estado?", v: "Sim, a fiscalização é atribuição comum, mas, havendo autos dos dois, prevalece o lavrado pelo órgão que licenciou.", b: "art. 17, LC 140/2011" },
  { id: "est-falencia-01", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual o juízo competente para decretar a falência?", v: "O do local do principal estabelecimento do devedor (ou da filial de empresa com sede fora do Brasil), entendido como o local de maior volume de negócios.", b: "art. 3º, Lei 11.101/2005", p: "Não é o juízo da sede estatutária nem de qualquer filial." },
  { id: "est-falencia-02", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quem pode requerer a falência do devedor?", v: "O próprio devedor (autofalência), o cônjuge sobrevivente, herdeiro ou inventariante, o sócio ou acionista e qualquer credor.", b: "art. 97, Lei 11.101/2005", p: "Credor domiciliado no exterior deve prestar caução; credor empresário precisa estar regularmente registrado." },
  { id: "est-falencia-03", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quais entidades não se sujeitam à Lei de Falências?", v: "Empresas públicas, sociedades de economia mista, instituições financeiras, cooperativas de crédito, consórcios, previdência complementar, operadoras de plano de saúde, seguradoras e sociedades de capitalização.", b: "art. 2º, Lei 11.101/2005" },
  { id: "est-falencia-04", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quais as hipóteses de insolvência que autorizam a falência?", v: "Impontualidade sem relevante razão em títulos executivos protestados acima de 40 salários mínimos; execução frustrada (não paga, não deposita nem nomeia bens), sem valor mínimo; ou prática de atos de falência.", b: "art. 94, Lei 11.101/2005" },
  { id: "est-falencia-05", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual o prazo de defesa do devedor e o que é o depósito elisivo?", v: "10 dias para contestar. Nos pedidos por impontualidade ou execução frustrada, pode depositar o total do crédito com correção, juros e honorários, e a falência não será decretada.", b: "art. 98, Lei 11.101/2005", p: "O depósito não apenas suspende o processo: impede a decretação da quebra." },
  { id: "est-falencia-06", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual recurso cabe contra a decisão que decreta a falência e contra a que a julga improcedente?", v: "Da decretação cabe agravo; da sentença de improcedência cabe apelação.", b: "art. 100, Lei 11.101/2005" },
  { id: "est-falencia-07", d: "Direito Empresarial", r: "E", t: "Falência", f: "Tributo com fato gerador posterior à decretação da falência prefere ao crédito com garantia real?", v: "Sim. É crédito extraconcursal, pago antes dos concursais, entre os quais está o crédito com garantia real.", b: "arts. 83 e 84, Lei 11.101/2005", p: "Crédito trabalhista concursal é limitado a 150 salários mínimos por credor; o trabalhista surgido após a falência é extraconcursal e não tem esse teto." },
  { id: "est-responsabilidade-do-forn-01", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Qual a diferença entre fato e vício do produto ou serviço?", v: "Fato é o acidente de consumo causado por defeito, que atinge a segurança do consumidor; vício é a inadequação de qualidade ou quantidade que torna o produto impróprio ou lhe reduz o valor, sem acidente.", b: null },
  { id: "est-responsabilidade-do-forn-02", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Como responde o fabricante pelo fato do produto e quando se exime?", v: "Responde objetivamente, sem culpa. Só se exime provando que não colocou o produto no mercado, que o defeito não existe ou culpa exclusiva do consumidor ou de terceiro.", b: "art. 12, caput e § 3º, CDC", p: "Produto que oferece a segurança que dele se espera (ex.: airbag que não abre em colisão traseira) não é defeituoso." },
  { id: "est-responsabilidade-do-forn-03", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Quando o comerciante responde pelo fato do produto?", v: "Só de forma subsidiária: quando fabricante, produtor, construtor ou importador não puderem ser identificados, quando o produto vier sem identificação clara deles ou quando não conservar bem produtos perecíveis.", b: "art. 13, CDC", p: "No fato do serviço não há essa exceção: todos os fornecedores da cadeia respondem solidariamente." },
  { id: "est-responsabilidade-do-forn-04", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Como respondem os profissionais liberais pelo fato do serviço?", v: "Mediante verificação de culpa (responsabilidade subjetiva), exceção à regra objetiva do CDC.", b: null },
  { id: "est-responsabilidade-do-forn-05", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "No vício de qualidade do produto, qual o prazo do fornecedor e quais as opções do consumidor?", v: "O fornecedor tem 30 dias para sanar. Não sanado, o consumidor escolhe: substituição, restituição atualizada da quantia (com perdas e danos) ou abatimento do preço.", b: "art. 18, § 1º, CDC", p: "O consumidor pode exigir as opções de imediato se o produto for essencial ou se a troca de partes comprometer qualidade ou valor (§ 3º)." },
  { id: "est-responsabilidade-do-forn-06", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "No vício de quantidade, o consumidor precisa aguardar prazo para escolher a solução?", v: "Não. Pode escolher de imediato entre abatimento do preço, complementação do peso ou medida, substituição do produto ou restituição da quantia paga.", b: "art. 19, CDC", p: "A escolha é do consumidor, não do fornecedor ou de seu preposto." },
  { id: "est-responsabilidade-do-forn-07", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "A inversão do ônus da prova é automática no CDC?", v: "Não. Fica a critério do juiz quando a alegação for verossímil ou o consumidor for hipossuficiente, podendo ser negada.", b: "art. 6º, VIII, CDC" },
  { id: "est-justica-eleitoral-e-inel-01", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "A Justiça Eleitoral tem magistratura própria? Por quanto tempo servem seus juízes?", v: "Não; seus membros vêm de outros ramos do Judiciário e da advocacia. Servem por 2 anos, com no máximo uma recondução (dois biênios consecutivos).", b: null, p: "Os advogados que integram tribunais eleitorais podem continuar advogando (ADI 1.127)." },
  { id: "est-justica-eleitoral-e-inel-02", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Qual a composição mínima do TSE?", v: "7 membros: 3 ministros do STF e 2 do STJ, eleitos por voto secreto, e 2 advogados nomeados pelo Presidente da República a partir de lista de 6 indicada pelo STF.", b: "art. 119, CF", p: "Não há sabatina no Senado nem vaga para o Ministério Público; presidente e vice são do STF e o corregedor é do STJ." },
  { id: "est-justica-eleitoral-e-inel-03", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "O juiz eleitoral pode, de ofício, instaurar procedimento para multar propaganda irregular?", v: "Não. Apesar do poder de polícia, a multa por propaganda irregular depende de provocação.", b: "Súmula 18 TSE" },
  { id: "est-justica-eleitoral-e-inel-04", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Chefe do Executivo precisa se afastar do cargo para disputar a reeleição?", v: "Não. A renúncia até 6 meses antes do pleito só é exigida para concorrer a outros cargos.", b: "art. 14, § 6º, CF" },
  { id: "est-justica-eleitoral-e-inel-05", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Quem é atingido pela inelegibilidade reflexa e qual a exceção?", v: "Cônjuge e parentes até o 2º grau ou por adoção do chefe do Executivo (ou de quem o substituiu nos 6 meses anteriores), no território de sua jurisdição; não se aplica a quem já é titular de mandato e busca a reeleição.", b: "art. 14, § 7º, CF", p: "A dissolução do casamento no curso do mandato não afasta a inelegibilidade (Súmula Vinculante 18)." },
  { id: "est-justica-eleitoral-e-inel-06", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Inelegibilidade constitucional não impugnada no registro pode ser discutida após a eleição?", v: "Sim, por recurso contra a expedição de diploma, cabível para inelegibilidade constitucional ou superveniente e falta de condição de elegibilidade, em 3 dias após o último dia fixado para a diplomação.", b: "art. 262, Código Eleitoral", p: "Não cabe AIME, que se funda em abuso do poder econômico, corrupção ou fraude." },
  { id: "est-justica-eleitoral-e-inel-07", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Na AIJE, o que se exige para configurar o abuso de poder?", v: "Apenas a gravidade das circunstâncias do fato, não a potencialidade de alterar o resultado da eleição. A procedência gera inelegibilidade por 8 anos e cassação do registro ou diploma.", b: "art. 22, XIV e XVI, LC 64/1990" },
  { id: "est-hermeneutica-01", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que defendia a Escola da Exegese?", v: "Ligada ao Código Napoleônico, via o ordenamento como completo, sem lacunas reais, e reduzia o intérprete a declarar a letra da lei segundo a vontade de um legislador tido como infalível.", b: null },
  { id: "est-hermeneutica-02", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Qual a proposta da escola da livre pesquisa científica de François Gény?", v: "Admite lacunas inevitáveis e atribui ao intérprete integrá-las com liberdade entre as fontes, valorizando o costume e distinguindo o 'dado' (realidade) do 'construído' (técnica).", b: null },
  { id: "est-hermeneutica-03", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Norma clara dispensa interpretação?", v: "Não. A máxima 'interpretatio cessat in claris' é rejeitada: clareza é relativa a quem lê e o tempo altera o sentido das normas, de modo que todo texto exige interpretação.", b: null },
  { id: "est-hermeneutica-04", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que é interpretação autêntica e como se compara à doutrinária?", v: "Autêntica é a feita pelo próprio legislador (ex.: a lei que define pertenças) e é obrigatória; a doutrinária, privada, não vincula e vale pela força de persuasão.", b: null },
  { id: "est-hermeneutica-05", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Qual a diferença entre interpretação histórica e sociológica?", v: "A histórica busca o sentido na realidade social da época em que a norma foi editada; a sociológica considera a realidade social atual, do momento da interpretação.", b: null },
  { id: "est-hermeneutica-06", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que é interpretação teleológica?", v: "A que busca a finalidade da norma, orientando o juiz a atender aos fins sociais da lei e às exigências do bem comum.", b: "art. 5º, LINDB" },
  { id: "est-hermeneutica-07", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Diferencie interpretação extensiva, declaratória e restritiva.", v: "Extensiva amplia o alcance porque a lei disse menos do que queria; declaratória reconhece que texto e sentido coincidem; restritiva reduz o alcance porque a lei disse mais do que queria.", b: null, p: "A modificativa vai além da extensiva: adapta a norma a situações não previstas (atualizadora) ou para resolver antinomias (corretiva)." },
  { id: "est-convencao-americana-sobr-01", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Quando o Brasil aderiu ao Pacto de San José e com que ressalva?", v: "O Pacto é de 1969, mas o Brasil só o incorporou em 1992, já fora da ditadura. Fez reserva às visitas e investigações in loco da Comissão Interamericana, que dependem de autorização expressa do governo.", b: "Decreto 678/1992" },
  { id: "est-convencao-americana-sobr-02", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Que limites a Convenção Americana impõe à pena de morte?", v: "Só cabe para os delitos mais graves, não pode voltar onde já foi abolida e não se aplica a menores de 18 anos, maiores de 70 nem a gestantes. A vida é protegida, em geral, desde a concepção.", b: "art. 4 CADH" },
  { id: "est-convencao-americana-sobr-03", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "O que a Convenção exige do sistema prisional?", v: "Tratamento digno do preso, vedação de tortura e de tratamento cruel, separação entre processados e condenados e pena voltada à reforma e readaptação social. Superlotação e más condições carcerárias violam o Pacto.", b: "art. 5 CADH" },
  { id: "est-convencao-americana-sobr-04", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Quais trabalhos não contam como trabalho forçado proibido pela Convenção?", v: "O trabalho do preso em condições normais, o serviço militar, os serviços exigidos em calamidades e as obrigações cívicas comuns. Escravidão, servidão e tráfico de pessoas são vedados.", b: "art. 6 CADH" },
  { id: "est-convencao-americana-sobr-05", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Cite garantias do acusado no processo penal previstas no Pacto de San José.", v: "Presunção de inocência, intérprete gratuito, defensor público se não puder pagar, direito de não se autoincriminar, duplo grau de jurisdição e proibição de novo processo pelos mesmos fatos após absolvição definitiva.", b: "art. 8 CADH" },
  { id: "est-convencao-americana-sobr-06", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Onde estão os direitos econômicos, sociais e culturais no sistema interamericano?", v: "O Pacto trata sobretudo de direitos civis e políticos; os sociais foram detalhados pelo Protocolo de San Salvador (1988). O próprio Pacto já previa o compromisso de efetivação progressiva desses direitos.", b: "art. 26 CADH" },
  { id: "est-convencao-americana-sobr-07", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "O rol de motivos de discriminação vedados pela Convenção é taxativo?", v: "Não. A cláusula 'qualquer outra condição social' torna a lista exemplificativa, alcançando orientação sexual, identidade de gênero e deficiência.", b: "art. 24 CADH" },
  { id: "est-contribuicao-previdencia-01", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Qual a base de cálculo da contribuição dos segurados e qual a exceção?", v: "Em regra é o salário de contribuição, que respeita piso e teto (diferente da remuneração, base da contribuição da empresa). O segurado especial contribui sobre a receita bruta da comercialização da produção rural.", b: null },
  { id: "est-contribuicao-previdencia-02", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Qual o limite mínimo do salário de contribuição do contribuinte individual e do facultativo?", v: "O salário-mínimo mensal, independentemente de quantos dias trabalhou. Para empregado, doméstico e avulso, o piso é o da categoria ou o salário-mínimo proporcional ao tempo trabalhado.", b: null, p: "Para CI e facultativo não há proporcionalidade por dias: o mínimo é sempre o salário-mínimo mensal." },
  { id: "est-contribuicao-previdencia-03", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Incide contribuição previdenciária sobre o salário-maternidade?", v: "O STF declarou inconstitucional a contribuição a cargo do empregador sobre o salário-maternidade. Para Receita e PGFN, a contribuição do segurado sobre essa parcela continua devida.", b: "RE 576.967 STF", p: "A decisão afastou só a cota patronal, não a do segurado." },
  { id: "est-contribuicao-previdencia-04", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "O terço de férias integra a base da contribuição?", v: "Sobre o terço das férias gozadas incide (tese do STF, Tema 985). Férias indenizadas e seu terço, inclusive a dobra, ficam fora por previsão expressa da Lei 8.212/91.", b: "art. 28, § 9º, 'd', Lei 8.212/91" },
  { id: "est-contribuicao-previdencia-05", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Incide contribuição sobre o aviso prévio indenizado e os 15 primeiros dias de afastamento por doença?", v: "Não. O STJ afastou a incidência sobre ambos, e a PGFN dispensa contestar e recorrer no caso do aviso prévio indenizado. O aviso prévio trabalhado, porém, integra a base.", b: "REsp 1.230.957/RS STJ" },
  { id: "est-contribuicao-previdencia-06", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Quando a ajuda de custo por mudança de local de trabalho fica fora do salário de contribuição?", v: "Só quando paga em parcela única e exclusivamente pela mudança de local de trabalho. Paga em duas ou mais parcelas, todas sofrem incidência.", b: null, p: "Parcelamento da ajuda de custo faz incidir contribuição sobre todas as parcelas." },
  { id: "est-contribuicao-previdencia-07", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "O 13º salário sofre contribuição previdenciária?", v: "Sim, integra o salário de contribuição. Porém não entra no cálculo do salário de benefício.", b: "Súmula 688 STF" },
  { id: "est-responsabilidade-ambient-01", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Qual a natureza da responsabilidade civil por dano ambiental?", v: "Objetiva, independente de culpa, fundada na teoria do risco integral: basta o nexo causal e não se admitem excludentes como caso fortuito ou força maior.", b: null },
  { id: "est-responsabilidade-ambient-02", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "O comprador de imóvel degradado responde pelo dano causado pelo dono anterior?", v: "Sim. A obrigação ambiental é propter rem e pode ser cobrada do proprietário ou possuidor atual e/ou dos anteriores, à escolha do credor.", b: "Súmula 623 STJ" },
  { id: "est-responsabilidade-ambient-03", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Como responde o Poder Público que se omite na fiscalização ambiental?", v: "De forma solidária, mas com execução subsidiária: cobra-se primeiro o degradador direto.", b: "Súmula 652 STJ" },
  { id: "est-responsabilidade-ambient-04", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "A pretensão de reparar dano ambiental prescreve? E a punição administrativa?", v: "A reparação do dano ambiental difuso é imprescritível (STF e STJ). Já a apuração administrativa prescreve em 5 anos da prática ou da cessação da infração permanente, com prescrição intercorrente se o processo ficar parado mais de 3 anos.", b: null, p: "Se a infração também for crime, a prescrição administrativa segue o prazo da lei penal; e a prescrição da multa não afasta o dever de reparar." },
  { id: "est-responsabilidade-ambient-05", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Quais os requisitos para responsabilizar penalmente a pessoa jurídica por crime ambiental?", v: "A infração deve decorrer de decisão do representante legal ou contratual ou do órgão colegiado, no interesse ou benefício da entidade. Não se exige mais a dupla imputação com a pessoa física.", b: "art. 3º, Lei 9.605/1998" },
  { id: "est-responsabilidade-ambient-06", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Quais os limites da prestação pecuniária na Lei de Crimes Ambientais?", v: "Entre 1 e 360 salários-mínimos, paga à vítima ou a entidade com fim social; o valor é abatido de eventual reparação civil.", b: "art. 12, Lei 9.605/1998" },
  { id: "est-responsabilidade-ambient-07", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Como a reincidência agrava a multa administrativa ambiental?", v: "Nova infração em até 5 anos da decisão administrativa definitiva anterior: multa em triplo se for a mesma infração, em dobro se for infração diferente.", b: "art. 11, Decreto 6.514/2008" },
  { id: "est-conflito-de-leis-no-espa-01", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege personalidade, nome, capacidade e direitos de família?", v: "A lei do país de domicílio da pessoa. Se o casamento for celebrado no Brasil, impedimentos dirimentes e formalidades seguem a lei brasileira.", b: "art. 7º LINDB" },
  { id: "est-conflito-de-leis-no-espa-02", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege o regime de bens se os nubentes têm domicílios diferentes?", v: "A do primeiro domicílio conjugal, que também rege a invalidade do casamento. O local da celebração não decide.", b: "art. 7º, §§ 3º e 4º, LINDB" },
  { id: "est-conflito-de-leis-no-espa-03", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Qual a lei aplicável aos bens?", v: "A do país onde estão situados (lex rei sitae). Para móveis que o proprietário traz consigo ou destinados a transporte, aplica-se a lei do domicílio do proprietário.", b: "art. 8º LINDB" },
  { id: "est-conflito-de-leis-no-espa-04", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege as obrigações contratuais com elemento estrangeiro?", v: "A do país onde se constituíram; o contrato considera-se constituído no lugar em que reside o proponente.", b: "art. 9º LINDB" },
  { id: "est-conflito-de-leis-no-espa-05", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Qual a lei da sucessão e qual a regra de proteção aos brasileiros?", v: "Vale a lei do último domicílio do falecido ou desaparecido, qualquer que seja o bem. Bens de estrangeiro no Brasil seguem a lei brasileira em favor do cônjuge ou filhos brasileiros se ela lhes for mais favorável; a capacidade para suceder segue o domicílio do herdeiro.", b: "art. 10 LINDB" },
  { id: "est-conflito-de-leis-no-espa-06", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Quando a competência da Justiça brasileira é concorrente e quando é exclusiva?", v: "Concorrente quando o réu tem domicílio no Brasil ou a obrigação deve ser cumprida aqui. Exclusiva nas ações sobre imóveis situados no Brasil e no inventário e partilha de bens aqui situados.", b: "art. 12 LINDB; arts. 21 e 23 CPC", p: "Ação proposta no exterior não gera litispendência; e cláusula de foro exclusivo estrangeiro só afasta a jurisdição brasileira se o réu a alegar na contestação (art. 25 CPC)." },
  { id: "est-conflito-de-leis-no-espa-07", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Quem homologa sentença estrangeira no Brasil?", v: "O STJ, desde 2004. Também é preciso juiz competente, citação ou revelia regular, trânsito em julgado e tradução por intérprete autorizado.", b: "art. 15 LINDB", p: "O texto da LINDB ainda diz STF, mas a competência é do STJ." },
  { id: "est-dependentes-do-rgps-01", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quais são as três classes de dependentes do RGPS?", v: "Classe I: cônjuge, companheiro(a) e filho não emancipado menor de 21 anos, inválido ou com deficiência intelectual, mental ou grave. Classe II: pais. Classe III: irmão nas mesmas condições do filho. Têm direito só à pensão por morte e ao auxílio-reclusão.", b: "art. 16, Lei 8.213/91" },
  { id: "est-dependentes-do-rgps-02", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Como concorrem os dependentes entre classes e dentro da mesma classe?", v: "Existindo dependente de uma classe, os das classes seguintes ficam excluídos. Dentro da mesma classe, o benefício é dividido em cotas iguais.", b: null },
  { id: "est-dependentes-do-rgps-03", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quem precisa comprovar dependência econômica?", v: "Pais e irmãos. Na classe I a dependência é presumida, salvo para os equiparados a filho (enteado e menor tutelado), que dependem de declaração do segurado e de prova da dependência.", b: null },
  { id: "est-dependentes-do-rgps-04", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Filho de 22 anos universitário é dependente previdenciário?", v: "Não. Depois dos 21 o filho só segue dependente se inválido ou com deficiência intelectual, mental ou grave; a maioridade civil aos 18 também não altera o limite de 21.", b: null, p: "Não confundir com a dependência para Imposto de Renda, que alcança universitário até 24 anos." },
  { id: "est-dependentes-do-rgps-05", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "A ex-esposa que renunciou aos alimentos pode receber pensão por morte?", v: "Sim, se comprovar necessidade econômica superveniente. Quem recebia alimentos concorre em igualdade com a classe I; se os alimentos eram temporários, a pensão dura o prazo restante.", b: "Súmula 336 STJ" },
  { id: "est-dependentes-do-rgps-06", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Como se prova união estável ou dependência econômica perante o INSS?", v: "Com início de prova material contemporânea, produzida até 24 meses antes do óbito ou da prisão do segurado. Prova só testemunhal não basta, salvo força maior ou caso fortuito.", b: null },
  { id: "est-dependentes-do-rgps-07", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quem perde definitivamente a condição de dependente?", v: "O condenado com trânsito em julgado como autor, coautor ou partícipe de homicídio doloso, consumado ou tentado, contra o segurado. Ficam ressalvados os absolutamente incapazes e os inimputáveis.", b: null },
  { id: "est-despesa-publica-precator-01", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais as fases da despesa pública e qual é obrigatória antes de qualquer gasto?", v: "Empenho, liquidação e pagamento. Nenhuma despesa pode ser feita sem prévio empenho, que reserva a dotação; a nota de empenho, porém, pode ser dispensada em casos especiais.", b: "art. 60, Lei 4.320/64" },
  { id: "est-despesa-publica-precator-02", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Diferencie restos a pagar processados e não processados.", v: "São despesas empenhadas e não pagas até 31/12. Processados já foram liquidados (credor tem direito líquido e certo); não processados ainda não foram liquidados.", b: "art. 36, Lei 4.320/64" },
  { id: "est-despesa-publica-precator-03", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "No regime geral, quando deve ser pago o precatório e há juros de mora nesse prazo?", v: "Apresentado até 1º de fevereiro, entra no orçamento do ano seguinte e deve ser pago até o fim desse exercício, com atualização monetária. Dentro desse prazo não correm juros de mora.", b: "art. 100, § 5º, CF" },
  { id: "est-despesa-publica-precator-04", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais os tetos de RPV quando o ente não edita lei própria?", v: "60 salários-mínimos na União (Lei 10.259/01), 40 para Estados e DF e 30 para Municípios. A lei local não pode fixar valor abaixo do maior benefício do RGPS.", b: "art. 87 ADCT" },
  { id: "est-despesa-publica-precator-05", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "O credor pode fracionar a execução para receber parte por RPV?", v: "Não; é vedado repartir o crédito para receber parte por RPV e o resto por precatório. Mas ele pode renunciar ao excedente e receber tudo por RPV.", b: "art. 100, § 8º, CF; art. 87, parágrafo único, ADCT" },
  { id: "est-despesa-publica-precator-06", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Como funciona a superpreferência dos precatórios alimentares?", v: "Titulares com 60 anos ou mais, doença grave ou deficiência recebem antes até o triplo do valor de RPV (no regime geral); o saldo segue na fila dos alimentares, que passam à frente dos comuns.", b: "art. 100, § 2º, CF", p: "A superpreferência não passa à frente das RPVs nem garante o pagamento integral de uma vez." },
  { id: "est-despesa-publica-precator-07", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais as regras da cessão de precatório?", v: "Pode ser total ou parcial e não depende de concordância do devedor, mas só produz efeitos após comunicação ao tribunal de origem e ao ente devedor. A cessão não muda a natureza do crédito: cessionário idoso não torna preferencial um precatório comum.", b: "art. 100, § 13, CF" },
  { id: "est-lei-das-eleicoes-e-acoes-01", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e quem pode propor a AIRC?", v: "5 dias contados da publicação do edital de registro (prazo decadencial). Legitimados: candidato, partido, coligação e Ministério Público Eleitoral.", b: "Súmula 49 TSE" },
  { id: "est-lei-das-eleicoes-e-acoes-02", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Para que serve a AIJE, até quando cabe e quais as sanções?", v: "Apura abuso de poder econômico ou político e pode ser proposta até a diplomação. Gera inelegibilidade, cassação do registro ou do diploma e multa.", b: "art. 22, LC 64/90" },
  { id: "est-lei-das-eleicoes-e-acoes-03", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e os fundamentos da AIME?", v: "15 dias contados da diplomação, por abuso de poder econômico, corrupção ou fraude. Tramita em segredo de justiça e pode levar à perda do mandato.", b: "art. 14, §§ 10 e 11, CF", p: "Não serve para conduta vedada isolada; abuso político só se entrelaçado com abuso econômico." },
  { id: "est-lei-das-eleicoes-e-acoes-04", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Candidato que dá bem ao eleitor em troca do voto: qual a ação e até quando?", v: "Representação por captação ilícita de sufrágio, cabível do registro até a diplomação. Gera multa e cassação do registro ou diploma; um único voto comprado basta e não se exige pedido explícito de voto.", b: "art. 41-A, Lei 9.504/97", p: "Segundo o TSE, só o candidato figura no polo passivo." },
  { id: "est-lei-das-eleicoes-e-acoes-05", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e quem pode propor a representação por arrecadação e gastos ilícitos de campanha?", v: "15 dias contados da diplomação, por partido, coligação ou Ministério Público. Leva à negação ou cassação do diploma.", b: "art. 30-A, Lei 9.504/97", p: "O candidato não tem legitimidade ativa para essa representação." },
  { id: "est-lei-das-eleicoes-e-acoes-06", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Em que hipóteses e em que prazo cabe o RCED?", v: "Apenas por inelegibilidade superveniente, inelegibilidade constitucional ou falta de condição de elegibilidade, em 3 dias após a diplomação, com prova pré-constituída.", b: "art. 262, Código Eleitoral" },
  { id: "est-lei-das-eleicoes-e-acoes-07", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Como funciona a representação genérica por descumprimento da Lei das Eleições?", v: "Rito célere: defesa em 48 horas e decisão em 24 horas. Sanção ao candidato não atinge o partido beneficiado, salvo se provada a participação dele.", b: "art. 96, Lei 9.504/97" },
  // Ética Profissional · Princípios
  { id: "est-principios-01", d: "Ética Profissional", r: "E", t: "Princípios", f: "Quais são os princípios que orientam a atividade do advogado?", v: "Pessoalidade, confiabilidade (confiança recíproca), sigilo profissional, não mercantilização e exclusividade.", b: null },
  { id: "est-principios-02", d: "Ética Profissional", r: "E", t: "Princípios", f: "Pelo princípio da pessoalidade, a consultoria jurídica precisa de mandato ou contrato de honorários? Pode ser verbal?", v: "Não precisa de procuração nem de contrato de honorários formalizado. Pode ser prestada de forma verbal ou escrita, conforme combinarem advogado e cliente.", b: null },
  { id: "est-principios-03", d: "Ética Profissional", r: "E", t: "Princípios", f: "A consultoria jurídica prestada só por meio virtual é admitida?", v: "Em regra, a consultoria exclusivamente virtual não combina com a pessoalidade. Os meios digitais podem, porém, servir de ferramenta de comunicação e atendimento, respeitadas as normas éticas.", b: null },
  { id: "est-principios-04", d: "Ética Profissional", r: "E", t: "Princípios", f: "Rompida a confiança com o cliente, o advogado pode abandonar a causa de imediato?", v: "Não. Ele deve renunciar e continua representando o cliente nos 10 dias seguintes à notificação da renúncia, salvo se for substituído antes.", b: "art. 10 do CED", p: "A quebra da confiança justifica a renúncia, não o abandono imediato do processo." },
  { id: "est-principios-05", d: "Ética Profissional", r: "E", t: "Princípios", f: "O sigilo profissional depende de pedido do cliente?", v: "Não. O sigilo é de ordem pública e existe independentemente de o cliente pedir reserva; as comunicações entre advogado e cliente presumem-se confidenciais.", b: null },
  { id: "est-principios-06", d: "Ética Profissional", r: "E", t: "Princípios", f: "O dever de sigilo vale quando o advogado atua contra ex-cliente ou ex-empregador?", v: "Sim. O sigilo deve ser mantido mesmo quando o advogado postula em nome de terceiros contra ex-cliente ou ex-empregador, em juízo ou fora dele.", b: null },
  { id: "est-principios-07", d: "Ética Profissional", r: "E", t: "Princípios", f: "Quais as consequências de o advogado violar o sigilo profissional?", v: "Na esfera disciplinar, infração punida com censura. Na esfera penal, crime de violação de segredo profissional, com detenção de 3 meses a 1 ano ou multa.", b: "art. 34, VII, c/c art. 36 do EAOAB; art. 154 do CP" },
  { id: "est-principios-08", d: "Ética Profissional", r: "E", t: "Princípios", f: "O advogado pode se recusar a depor sobre fatos que conheceu pela profissão mesmo se o cliente autorizar a revelação?", v: "Sim. Recusar-se a depor é direito do advogado, ainda que o cliente autorize ou peça; ele não é obrigado a depor em processo judicial, administrativo ou arbitral.", b: null, p: "A autorização ou o pedido do cliente não obriga o advogado a depor." },
  { id: "est-principios-09", d: "Ética Profissional", r: "E", t: "Princípios", f: "O que o princípio da não mercantilização permite quanto à divulgação do trabalho do advogado?", v: "A advocacia não pode ter finalidade puramente comercial, mas o advogado pode divulgar seu trabalho com publicidade discreta, moderada e de caráter só informativo.", b: null },
  { id: "est-principios-10", d: "Ética Profissional", r: "E", t: "Princípios", f: "O que proíbe o princípio da exclusividade e quais exceções trouxe o Provimento 205/2021?", v: "Proíbe divulgar a advocacia junto com outra atividade ou indicar vínculo entre elas, mesmo exercidas pela mesma pessoa; o descumprimento gera censura. São permitidos o vínculo com o magistério e o exercício em espaço compartilhado (coworking), com placa indicativa do escritório.", b: "Provimento n.º 205/2021", p: "A exclusividade não impede o advogado de exercer outra profissão; veda apenas a divulgação conjunta." },
  // Direito Constitucional · Direitos individuais e coletivos
  { id: "est-direitos-individuais-e-coletivos-01", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Estrangeiro não residente que esteja de passagem pelo Brasil é titular dos direitos fundamentais do art. 5º?", v: "Sim. Embora o caput fale em estrangeiros residentes, o STF e a doutrina entendem que basta estar em território nacional para ter a proteção dos direitos fundamentais, seja residente ou não.", b: "Art. 5º, caput, CF", p: "A literalidade do caput menciona só estrangeiros residentes; a banca pode explorar essa leitura restritiva." },
  { id: "est-direitos-individuais-e-coletivos-02", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Ações afirmativas, como cotas raciais em universidades, violam o princípio da igualdade?", v: "Não. Para o STF, elas dão efetividade à igualdade material, corrigindo distorções que a aplicação apenas formal da igualdade produziria.", b: "Art. 5º, I, CF" },
  { id: "est-direitos-individuais-e-coletivos-03", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "O que acontece com quem invoca escusa de consciência para não cumprir obrigação legal a todos imposta e também se recusa a cumprir a prestação alternativa?", v: "A escusa sozinha não gera perda de direitos, mas a dupla recusa (obrigação legal e prestação alternativa fixada em lei) leva à perda dos direitos políticos.", b: "Art. 5º, VIII, e art. 15, IV, CF" },
  { id: "est-direitos-individuais-e-coletivos-04", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Quando se pode entrar na casa sem consentimento do morador, e o que o conceito de casa abrange?", v: "Em flagrante delito, desastre ou para prestar socorro (a qualquer hora) e, apenas durante o dia, por determinação judicial. Casa abrange qualquer compartimento habitado, aposento ocupado de habitação coletiva e compartimento privado não aberto ao público onde se exerce profissão.", b: "Art. 5º, XI, CF", p: "Ordem judicial só autoriza o ingresso durante o dia." },
  { id: "est-direitos-individuais-e-coletivos-05", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Quebra de sigilo telefônico e interceptação telefônica: quem pode determinar cada uma?", v: "A quebra de sigilo (acesso aos registros das ligações) pode ser feita pelo Judiciário e também por CPI. A interceptação (captação do conteúdo da conversa) exige ordem judicial, para investigação criminal ou instrução processual penal.", b: "Art. 5º, XII, CF", p: "CPI pode quebrar o sigilo dos dados telefônicos, mas não determinar interceptação." },
  { id: "est-direitos-individuais-e-coletivos-06", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "O direito de reunião depende de autorização? E o aviso prévio é condição?", v: "Independe de autorização; exige-se apenas prévio aviso à autoridade e que não se frustre reunião anteriormente marcada no mesmo local. Para o STF, o aviso não condiciona o exercício do direito: basta notificação efetiva, e anúncio público já supre.", b: "Art. 5º, XVI, CF" },
  { id: "est-direitos-individuais-e-coletivos-07", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Associação: o que é preciso para dissolvê-la compulsoriamente e para suspender suas atividades?", v: "Dissolução compulsória exige decisão judicial transitada em julgado; para suspender as atividades basta decisão judicial, sem trânsito. A criação independe de autorização estatal e ninguém é obrigado a associar-se ou permanecer associado.", b: "Art. 5º, XX, CF", p: "Não confundir: trânsito em julgado só é exigido para a dissolução." },
  { id: "est-direitos-individuais-e-coletivos-08", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Quais são as exceções à regra de que o acesso ao Judiciário independe de esgotar a via administrativa?", v: "Habeas data (exige negativa ou omissão administrativa), controvérsias sobre disciplina e competições desportivas (esgotar a justiça desportiva) e reclamação ao STF contra ato ou omissão da Administração que descumpre súmula vinculante (esgotar as vias administrativas).", b: "Art. 5º, XXXV; art. 217, § 1º; art. 103-A, § 3º, CF; art. 7º, § 1º, Lei 11.417/2006" },
  { id: "est-direitos-individuais-e-coletivos-09", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Brasileiro pode ser extraditado?", v: "O nato nunca. O naturalizado só por crime comum praticado antes da naturalização ou por comprovado envolvimento em tráfico ilícito de entorpecentes, na forma da lei.", b: "Art. 5º, LI, CF" },
  { id: "est-direitos-individuais-e-coletivos-10", d: "Direito Constitucional", r: "E", t: "Direitos individuais e coletivos", f: "Qual o status de um tratado de direitos humanos conforme o rito de aprovação?", v: "Aprovado em cada Casa, em dois turnos, por três quintos, equivale a emenda constitucional. Sem esse rito, tem status supralegal: abaixo da Constituição e acima das leis.", b: "Art. 5º, § 3º, CF" },
  // Direito Civil · Teoria geral: pessoas
  { id: "est-teoria-geral-pessoas-01", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Qual a diferença entre personalidade e capacidade?", v: "Personalidade é a aptidão de ser titular de direitos e deveres; é inata ao ser humano e não admite graus. Capacidade é a medida da personalidade e admite graduação: capacidade de direito (todos têm) e capacidade de fato (de exercício).", b: null },
  { id: "est-teoria-geral-pessoas-02", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Quem é absolutamente incapaz no Código Civil atual?", v: "Somente os menores de 16 anos, sem exceção. Eles atuam por meio de representação.", b: "art. 3º do CC", p: "Nenhuma outra hipótese (nem deficiência ou enfermidade) gera incapacidade absoluta." },
  { id: "est-teoria-geral-pessoas-03", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Quem é relativamente incapaz e como atua na vida civil?", v: "Os maiores de 16 e menores de 18 anos, os ébrios habituais, os viciados em tóxicos, os que por causa transitória ou permanente não podem exprimir vontade e os pródigos. Atuam com assistência.", b: null },
  { id: "est-teoria-geral-pessoas-04", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "A pessoa com deficiência é incapaz? A curatela afeta o direito de casar?", v: "Não: a pessoa com deficiência é plenamente capaz e só excepcionalmente fica sob curatela. A deficiência e a curatela não afetam o direito de casar, constituir união estável, exercer direitos reprodutivos, adotar ou ter guarda e tutela.", b: null, p: "Pessoa com deficiência não é absoluta nem relativamente incapaz." },
  { id: "est-teoria-geral-pessoas-05", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Quando se presume a morte sem decretação de ausência?", v: "Quando for extremamente provável a morte de quem estava em perigo de vida e quando o desaparecido em campanha ou feito prisioneiro não for encontrado até 2 anos após o fim da guerra.", b: null },
  { id: "est-teoria-geral-pessoas-06", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Quando a sucessão provisória do ausente se converte em definitiva?", v: "Dez anos depois da abertura da sucessão provisória, ou quando o ausente tiver mais de 80 anos e já se passaram 5 anos das últimas notícias dele. É nesse momento que se presume a morte do ausente.", b: null },
  { id: "est-teoria-geral-pessoas-07", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "O que ocorre se o ausente regressa após a sucessão definitiva?", v: "Se voltar nos 10 anos seguintes, recebe os bens no estado em que estiverem. Passado esse prazo, não pode reclamar mais nada, ainda que retorne.", b: null },
  { id: "est-teoria-geral-pessoas-08", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "O que é comoriência?", v: "É a presunção de que pessoas reciprocamente herdeiras morreram ao mesmo tempo, quando não se pode apurar quem morreu primeiro.", b: null },
  { id: "est-teoria-geral-pessoas-09", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Qual o domicílio necessário do incapaz, do servidor público, do militar, do marítimo e do preso?", v: "Incapaz: o do representante ou assistente. Servidor: onde exerce permanentemente as funções. Militar: onde serve (Marinha ou Aeronáutica: sede do comando a que se subordina). Marítimo: onde o navio está matriculado. Preso: onde cumpre a sentença.", b: null },
  { id: "est-teoria-geral-pessoas-10", d: "Direito Civil", r: "E", t: "Teoria geral: pessoas", f: "Que teoria de desconsideração da personalidade jurídica o Código Civil adota e qual a diferença para a Teoria Menor?", v: "O CC adota a Teoria Maior, que exige abuso (desvio de finalidade ou confusão patrimonial). A Teoria Menor, do CDC, do Direito do Trabalho e do Tributário, dispensa esses requisitos e basta o inadimplemento.", b: null },
  // Direito Processual Civil · Partes e procuradores
  { id: "est-partes-e-procuradores-01", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Quais são as três espécies de capacidade estudadas em partes e procuradores?", v: "Capacidade de ser parte (ligada à capacidade civil), capacidade de estar em juízo (exercer pessoalmente os atos do processo) e capacidade postulatória (praticar atos técnicos, em regra pelo advogado inscrito na OAB).", b: null },
  { id: "est-partes-e-procuradores-02", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Em que hipóteses o CPC manda nomear curador especial?", v: "Ao incapaz sem representante ou cujos interesses colidam com os do representante, e ao réu preso revel e ao réu revel citado por edital ou por hora certa. A função é exercida pela Defensoria Pública.", b: null },
  { id: "est-partes-e-procuradores-03", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Quem representa em juízo o espólio, a massa falida, a herança jacente e o condomínio?", v: "Espólio: inventariante. Massa falida: administrador judicial. Herança jacente ou vacante: curador. Condomínio: administrador ou síndico.", b: null, p: "Se o inventariante for dativo, os sucessores do falecido devem ser intimados no processo em que o espólio for parte." },
  { id: "est-partes-e-procuradores-04", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Quais as consequências de não sanar a incapacidade processual ou a irregularidade de representação na instância originária?", v: "Se a providência cabia ao autor, o processo é extinto sem resolução do mérito; se cabia ao réu, ele é considerado revel; se cabia ao terceiro, ele pode ser excluído ou considerado revel.", b: null, p: "Na fase recursal: o recurso não é conhecido se o vício for do recorrente, e as contrarrazões são desentranhadas se for do recorrido." },
  { id: "est-partes-e-procuradores-05", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Quando os cônjuges precisam litigar juntos ou ser ambos citados?", v: "Em ação sobre direito real imobiliário, salvo no regime de separação total de bens. Também devem ser ambos citados em ação sobre fato que envolva os dois, dívida contraída por um em favor da família e ônus sobre imóvel de um ou de ambos.", b: null, p: "Nas possessórias, a participação do cônjuge só é indispensável em caso de composse ou de ato praticado por ambos." },
  { id: "est-partes-e-procuradores-06", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Qual a diferença entre ato atentatório à dignidade da justiça e litigância de má-fé quanto à multa?", v: "O ato atentatório ofende o Judiciário: multa de até 20% do valor da causa, revertida ao fundo de modernização do Judiciário. A má-fé lesa a parte contrária: multa de 1% a 10% do valor da causa, revertida à parte prejudicada.", b: null, p: "Sendo irrisório ou inestimável o valor da causa, a multa pode chegar a até 10 salários-mínimos nos dois casos." },
  { id: "est-partes-e-procuradores-07", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Como ficam as despesas quando ambas as partes são vencedoras e vencidas?", v: "Distribuem-se proporcionalmente, salvo sucumbência mínima de uma delas: aí a parte que perdeu quase todo o pedido arca com a integralidade das despesas.", b: null },
  { id: "est-partes-e-procuradores-08", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Quem adianta os honorários do perito?", v: "A parte que requereu a perícia; se ela for determinada de ofício pelo juiz ou requerida por ambas as partes, o custo é rateado. O assistente técnico é adiantado por quem o indicou.", b: null },
  { id: "est-partes-e-procuradores-09", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "Em que faixa são fixados os honorários de sucumbência e o que ocorre em grau recursal?", v: "Entre 10% e 20% do valor da condenação, do proveito econômico ou do valor da causa, considerando zelo, lugar, natureza da causa e trabalho realizado. No recurso, o tribunal majora os honorários respeitando os limites máximos.", b: null, p: "Se o réu reconhecer a procedência do pedido e cumprir a prestação, os honorários caem pela metade." },
  { id: "est-partes-e-procuradores-10", d: "Direito Processual Civil", r: "E", t: "Partes e procuradores", f: "O recurso de beneficiário da gratuidade da justiça dispensa preparo sempre?", v: "Não. Se o recurso tratar exclusivamente de honorários advocatícios, exige-se preparo, salvo se o próprio advogado também for beneficiário da gratuidade. O benefício é pessoal e não se estende a litisconsorte ou sucessor.", b: null },
  // Ética Profissional · Direitos do advogado
  { id: "est-direitos-do-advogado-01", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "A inviolabilidade do escritório e das comunicações do advogado é absoluta?", v: "Não. Ela protege escritório, instrumentos de trabalho e comunicações ligadas à advocacia, mas pode ser afastada excepcionalmente, com os requisitos legais. A medida não pode se basear só em declarações de colaborador sem confirmação por outras provas.", b: "Art. 7º do EAOAB", p: "Delação sem outros elementos de prova não basta para a busca no escritório." },
  { id: "est-direitos-do-advogado-02", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Na busca e apreensão em escritório, os documentos dos clientes do advogado podem ser apreendidos?", v: "Em regra continuam protegidos. A proteção cai quando o cliente também é investigado como coautor ou partícipe do mesmo crime que motivou a quebra da inviolabilidade.", b: "Art. 7º do EAOAB" },
  { id: "est-direitos-do-advogado-03", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Qual o papel do representante da OAB na busca e apreensão em escritório e qual a antecedência para a análise dos documentos?", v: "Ele acompanha o cumprimento, zela pelo objeto da investigação e impede que material alheio a ela seja analisado ou apreendido. A seccional deve ser avisada com pelo menos 24 horas de antecedência sobre data, hora e local da análise, salvo urgência fundamentada pelo juiz.", b: "Art. 7º do EAOAB" },
  { id: "est-direitos-do-advogado-04", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Advogado preso em flagrante por motivo ligado ao exercício da advocacia: qual a consequência de não haver representante da OAB na lavratura do auto?", v: "O auto de prisão em flagrante é nulo. Nos demais casos, exige-se só a comunicação expressa à seccional. Para o STF, não há nulidade se a OAB, comunicada, não manda representante a tempo.", b: "Art. 7º do EAOAB", p: "Se a OAB foi avisada e não compareceu a tempo, o auto vale." },
  { id: "est-direitos-do-advogado-05", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "O advogado pode examinar autos de investigação sem procuração? E se a autoridade negar?", v: "Sim: autos de flagrante e de investigações de qualquer natureza, findos ou em andamento, podendo copiar peças, em meio físico ou digital. Se negado, a autoridade pode responder por abuso de autoridade e o advogado pode pedir ao juiz que garanta o acesso.", b: "Art. 7º do EAOAB; Súmula Vinculante 14" },
  { id: "est-direitos-do-advogado-06", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Quem pode pedir o desagravo público e ele depende da concordância do advogado ofendido?", v: "Pode ser instaurado de ofício, a pedido do ofendido ou de qualquer pessoa, e não depende da concordância do ofendido. Em caso de urgência e notoriedade, pode ser concedido de imediato, ad referendum do órgão competente.", b: "Art. 7º do EAOAB" },
  { id: "est-direitos-do-advogado-07", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Quais os prazos do procedimento de desagravo?", v: "O relator pode pedir informações ao ofensor em 15 dias (não é condição para conceder); a decisão sai em no máximo 60 dias; acolhido, a sessão ocorre em até 30 dias, de preferência no local da ofensa ou onde está o ofensor. O desagravo não impede a responsabilização do ofensor.", b: null },
  { id: "est-direitos-do-advogado-08", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Quando o advogado pode se retirar do recinto enquanto aguarda o pregão?", v: "Quando o atraso passar de 30 minutos, a autoridade que presidirá o ato não estiver presente e houver comunicação protocolizada ao juízo antes da retirada.", b: "Art. 7º do EAOAB", p: "Os três requisitos são cumulativos." },
  { id: "est-direitos-do-advogado-09", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Interrogatório de cliente investigado feito sem a assistência do advogado: qual a consequência?", v: "Nulidade absoluta do interrogatório ou depoimento e de todos os elementos dele derivados, direta ou indiretamente. O advogado pode ainda apresentar razões e quesitos durante a apuração.", b: "Art. 7º do EAOAB" },
  { id: "est-direitos-do-advogado-10", d: "Ética Profissional", r: "E", t: "Direitos do advogado", f: "Advogada que deu à luz ou adotou e é a única patrona da causa tem direito à suspensão de prazos? Em que condições?", v: "Sim, por 30 dias contados do parto ou da concessão da adoção, desde que notifique o cliente por escrito.", b: null },
  // Direito do Trabalho · Relações empregatícias especiais
  { id: "est-relacoes-empregaticias-especiais-01", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Como se define o empregador rural para fins de enquadramento do empregado rural?", v: "É a pessoa física ou jurídica que explora atividade agroeconômica (agrícola, pecuária ou agroindustrial, incluído o turismo rural acessório), com ou sem propriedade da terra, com auxílio de empregados. O enquadramento parte da atividade preponderante do empregador.", b: "Art. 3º, Lei nº 5.889/73", p: "O TST, após cancelar a OJ 419 da SBDI-1, às vezes analisa também as funções do empregado (sobretudo em agroindústrias), mas a atividade preponderante do empregador continua sendo o critério principal." },
  { id: "est-relacoes-empregaticias-especiais-02", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Qual a diferença entre propriedade rural e prédio rústico?", v: "Propriedade rural é a situada na zona rural; prédio rústico é o imóvel destinado à exploração agrícola, ainda que esteja em área urbana. Em ambos pode haver empregado rural.", b: "Art. 2º, Lei nº 5.889/73" },
  { id: "est-relacoes-empregaticias-especiais-03", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Qual é o horário noturno do empregado rural e como se calcula a hora noturna?", v: "Na lavoura, das 21h às 5h; na pecuária, das 20h às 4h. A hora noturna rural tem 60 minutos (sem hora reduzida) e o adicional é de 25%.", b: "Art. 7º, Lei nº 5.889/73", p: "Não se aplica ao rural a hora ficta reduzida nem o adicional de 20% do trabalhador urbano." },
  { id: "est-relacoes-empregaticias-especiais-04", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Como fica a redução da jornada no aviso prévio dado pelo empregador ao trabalhador rural?", v: "O rural tem direito a um dia de folga por semana durante o aviso. O urbano, por sua vez, reduz duas horas diárias ou falta sete dias corridos.", b: "Art. 15, Lei nº 5.889/73; art. 488, CLT" },
  { id: "est-relacoes-empregaticias-especiais-05", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Qual a regra do intervalo intrajornada do empregado rural?", v: "Em jornada contínua acima de 6 horas é obrigatório intervalo para repouso ou alimentação, segundo os usos e costumes da região, não computado na jornada. Entre duas jornadas, o descanso mínimo é de 11 horas consecutivas.", b: "Art. 5º, Lei nº 5.889/73" },
  { id: "est-relacoes-empregaticias-especiais-06", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Quais requisitos caracterizam o empregado doméstico?", v: "Trabalho contínuo, subordinado, oneroso e pessoal, sem finalidade lucrativa, prestado a pessoa ou família, no âmbito residencial, por mais de 2 dias por semana.", b: "Art. 1º, LC nº 150/2015", p: "No lugar da não eventualidade, o doméstico exige continuidade: até 2 dias por semana para a mesma família é diarista, não empregado." },
  { id: "est-relacoes-empregaticias-especiais-07", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Quais são os limites do regime de tempo parcial do empregado doméstico?", v: "Até 25 horas semanais, admitida até 1 hora extra por dia, respeitado o teto de 6 horas diárias.", b: null },
  { id: "est-relacoes-empregaticias-especiais-08", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Como funciona o intervalo intrajornada do doméstico e como pode ser reduzido ou fracionado?", v: "Mínimo de 1 e máximo de 2 horas; pode ser reduzido a 30 minutos por acordo escrito prévio entre empregado e empregador. Se o empregado mora no local, pode ser dividido em 2 períodos de no mínimo 1 hora cada, até 4 horas por dia.", b: "Art. 13, caput e § 1º, LC nº 150/2015", p: "Para o doméstico basta acordo individual escrito; para o urbano a redução a 30 minutos exige negociação coletiva (art. 611-A, III, CLT)." },
  { id: "est-relacoes-empregaticias-especiais-09", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Qual a idade mínima para o trabalho doméstico e como as férias do doméstico podem ser fracionadas?", v: "É vedado contratar menor de 18 anos como doméstico, sem exceção de aprendiz. As férias podem ser fracionadas, a critério do empregador, em até 2 períodos, um deles com no mínimo 14 dias corridos.", b: "Art. 1º, parágrafo único, e art. 17, § 2º, LC nº 150/2015", p: "Para os empregados em geral a CLT permite até 3 períodos (art. 134, § 1º)." },
  { id: "est-relacoes-empregaticias-especiais-10", d: "Direito do Trabalho", r: "E", t: "Relações empregatícias especiais", f: "Como funciona a indenização compensatória do FGTS do doméstico?", v: "Além dos 8% de FGTS, o empregador deposita mensalmente 3,2% da remuneração. Na dispensa sem justa causa ou rescisão indireta o empregado saca esse valor; na justa causa, pedido de demissão, fim do prazo ou falecimento, quem saca é o empregador; na culpa recíproca, metade para cada um.", b: "Art. 22 e art. 34, IV, LC nº 150/2015" },
  // Direito Processual Penal · Jurisdição e competência
  { id: "est-jurisdicao-e-competencia-01", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Crime que atinge bens ou interesses de sociedade de economia mista federal (ex.: Banco do Brasil) é julgado pela Justiça Federal?", v: "Não. A Justiça Federal julga crimes contra bens, serviços ou interesses da União, suas autarquias e empresas públicas; sociedade de economia mista fica com a Justiça Estadual.", b: "Art. 109, IV, CF; Súmula 556 do STF", p: "Empresa pública atrai a Justiça Federal; sociedade de economia mista, não." },
  { id: "est-jurisdicao-e-competencia-02", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "O que é o incidente de deslocamento de competência e quem pode suscitá-lo?", v: "Em grave violação de direitos humanos, o Procurador-Geral da República pode pedir ao STJ, em qualquer fase do inquérito ou processo, que o caso passe à Justiça Federal, para assegurar o cumprimento de tratados de direitos humanos.", b: "Art. 109, § 5º, CF" },
  { id: "est-jurisdicao-e-competencia-03", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Crime comum em que um indígena é autor ou vítima vai para a Justiça Federal?", v: "Não. A Justiça Federal julga a disputa sobre direitos indígenas; quando o indígena figura individualmente como autor ou vítima de crime comum, a competência é da Justiça Estadual.", b: "Súmula 140 do STJ" },
  { id: "est-jurisdicao-e-competencia-04", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Contrabando e descaminho exigem indícios de transnacionalidade para serem da Justiça Federal? Qual juízo é o competente?", v: "Não exigem: são da Justiça Federal mesmo sem indício de transnacionalidade. A competência se define pela prevenção do juízo federal do lugar da apreensão dos bens.", b: "Súmula 151 do STJ" },
  { id: "est-jurisdicao-e-competencia-05", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "O foro por prerrogativa de função alcança crimes praticados antes do cargo? E se o agente deixa o cargo no fim do processo?", v: "Só alcança crimes cometidos durante o exercício do cargo e relacionados às funções. Depois de encerrada a instrução, com a intimação para alegações finais, a competência não muda mais se o agente deixar o cargo.", b: null },
  { id: "est-jurisdicao-e-competencia-06", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Autoridade com foro previsto só na Constituição estadual comete homicídio doloso: quem julga?", v: "O Tribunal do Júri. A competência constitucional do Júri prevalece sobre foro estabelecido exclusivamente pela Constituição estadual; se o foro estiver na CF, prevalece o foro.", b: "Súmula 721 do STF; Súmula Vinculante 45" },
  { id: "est-jurisdicao-e-competencia-07", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Latrocínio, genocídio e lesão corporal seguida de morte vão a Júri?", v: "Não. Latrocínio é crime patrimonial, julgado pelo juiz singular; genocídio e terrorismo protegem a vida só de forma secundária; e a lesão seguida de morte é preterdolosa, sem dolo quanto à morte.", b: "Súmula 603 do STF" },
  { id: "est-jurisdicao-e-competencia-08", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Agente com foro no STF é denunciado junto com corréu sem foro: a reunião dos processos viola o juiz natural?", v: "Não. A atração do processo do corréu ao foro por prerrogativa de um dos denunciados, por conexão ou continência, não ofende juiz natural, ampla defesa nem devido processo legal.", b: "Súmula 704 do STF" },
  { id: "est-jurisdicao-e-competencia-09", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Qual a regra de competência territorial quando conduta e resultado ocorrem no Brasil, em lugares diferentes, e qual a exceção da jurisprudência no homicídio?", v: "Pela lei, vale o lugar da consumação (teoria do resultado) ou, na tentativa, do último ato de execução. No homicídio com morte em outro local, a jurisprudência majoritária fixa o foro da ação ou omissão, pela facilidade da prova.", b: "Art. 70 do CPP", p: "A posição jurisprudencial sobre o homicídio contraria a letra do art. 70." },
  { id: "est-jurisdicao-e-competencia-10", d: "Direito Processual Penal", r: "E", t: "Jurisdição e competência", f: "Crimes conexos de competência federal e estadual são julgados onde?", v: "Unificados na Justiça Federal, sem aplicar a regra do art. 78, II, a, do CPP.", b: "Súmula 122 do STJ" },
  // Direito Administrativo · Desapropriação
  { id: "est-desapropriacao-01", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Qual o prazo para propor a ação depois do decreto expropriatório, conforme o fundamento?", v: "Utilidade ou necessidade pública: 5 anos; se caducar, o mesmo bem só pode ser declarado de novo após 1 ano. Interesse social: 2 anos para efetivar a desapropriação e iniciar o aproveitamento do bem.", b: "Art. 3º da Lei 4.132/62", p: "A simples declaração não transfere o bem nem dá direito a indenização ao proprietário." },
  { id: "est-desapropriacao-02", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Quem pode promover a desapropriação (executar) além dos entes públicos, e quem pode desapropriar bens de outro ente federativo?", v: "Concessionários (inclusive de PPP), permissionários, autorizatários, arrendatários, entidades com funções delegadas e o contratado para obras sob empreitada global, integral ou contratação integrada, com autorização em lei ou contrato. Ente maior desapropria bens do menor, nunca o contrário, com autorização legislativa, dispensada se houver acordo entre os entes.", b: "Arts. 2º, §§ 2º e 2º-A, e 3º do DL 3.365/41", p: "Município não desapropria bem de Estado nem da União." },
  { id: "est-desapropriacao-03", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Na ação de desapropriação, o que a contestação pode discutir e cabe reconvenção?", v: "Só vício do processo judicial ou impugnação do preço; por isso não cabe reconvenção. A exceção admitida é o pedido de extensão, para incluir a parte remanescente que ficaria inútil ou de difícil uso.", b: "Art. 20 do DL 3.365/41" },
  { id: "est-desapropriacao-04", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "A revelia do expropriado faz presumir que ele aceitou o valor ofertado?", v: "Não. Pela justa indenização, exige-se concordância expressa com o preço; sem ela faz-se perícia, e o juiz não fica preso ao valor da causa, podendo até fixar valor menor que o da inicial.", b: "Art. 23 do DL 3.365/41" },
  { id: "est-desapropriacao-05", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Quando há reexame necessário na sentença de desapropriação (DL 3.365/41) e com que efeitos é recebida a apelação de cada parte?", v: "Reexame quando a indenização fixada superar o dobro da oferta inicial. A apelação do expropriado tem só efeito devolutivo; a do ente público, duplo efeito.", b: null },
  { id: "est-desapropriacao-06", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Se o Poder Público estiver atrasado com precatórios, como se paga a complementação da indenização ao fim do processo?", v: "Por depósito judicial direto, como medida excepcional fixada pelo STF; a regra continua sendo o precatório.", b: "STF, RE 922.144 (Tema 865)" },
  { id: "est-desapropriacao-07", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Até quando o poder público pode desistir da ação de desapropriação?", v: "Para o STJ, a qualquer tempo, desde que a indenização ainda não tenha sido paga integralmente, com a revogação do decreto e devolução do bem no estado em que recebido.", b: null },
  { id: "est-desapropriacao-08", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Desapropriação indireta: o que o particular pode fazer se o bem ainda não foi afetado e se já foi?", v: "Sem afetação a fim público, pode usar ação possessória. Se já afetado, há fato consumado e resta a ação de desapropriação indireta para receber indenização, de natureza real, no prazo da usucapião extraordinária.", b: null },
  { id: "est-desapropriacao-09", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Tredestinação lícita e ilícita: em qual cabe retrocessão?", v: "Só na ilícita, quando o bem recebe destino sem interesse público (ex.: repasse a terceiro). Na lícita o fim muda, mas continua público (escola virou hospital), e não há retrocessão.", b: null },
  { id: "est-desapropriacao-10", d: "Direito Administrativo", r: "E", t: "Desapropriação", f: "Na desapropriação para reforma agrária, quem é competente e como se paga a indenização?", v: "Só a União, por meio do INCRA, na Justiça Federal. A terra nua é paga em Títulos da Dívida Agrária e as benfeitorias úteis e necessárias, em dinheiro.", b: "Art. 184, CF; art. 2º da LC 76/93", p: "Interesse social e imóvel rural, isoladamente, não são exclusivos da União; só a finalidade de reforma agrária é." },
  // Direito Constitucional · Remédios constitucionais
  { id: "est-remedios-constitucionais-01", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quem pode impetrar habeas corpus e em favor de quem?", v: "Qualquer pessoa, física ou jurídica, nacional ou estrangeira, sem precisar de advogado. Mas o paciente (beneficiário) é sempre pessoa natural, pois o remédio tutela a liberdade de locomoção.", b: "Art. 5º, LXVIII, CF", p: "O habeas corpus pode ser impetrado contra ato de particular, não só de autoridade pública." },
  { id: "est-remedios-constitucionais-02", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Cabe habeas corpus contra punição disciplinar militar?", v: "A Constituição veda o habeas corpus quanto às punições disciplinares militares, mas o STF admite o remédio para discutir a legalidade da punição (competência da autoridade, contraditório e ampla defesa), não o seu mérito.", b: "Art. 142, § 2º, CF" },
  { id: "est-remedios-constitucionais-03", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quais os requisitos do mandado de segurança?", v: "Direito líquido e certo, não amparado por habeas corpus ou habeas data, violado por ilegalidade ou abuso de poder de autoridade pública ou de agente de pessoa jurídica no exercício de atribuição pública. A prova deve ser pré-constituída, sem dilação probatória.", b: "Art. 5º, LXIX, CF", p: "Controvérsia sobre matéria de direito não impede a concessão da segurança (Súmula 625 do STF)." },
  { id: "est-remedios-constitucionais-04", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "No mandado de segurança há condenação em honorários advocatícios e custas?", v: "Não há condenação em honorários de sucumbência, mas as custas processuais são devidas.", b: null },
  { id: "est-remedios-constitucionais-05", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quem pode impetrar mandado de segurança coletivo?", v: "Partido político com representação no Congresso Nacional e organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa de seus membros ou associados.", b: "Art. 5º, LXX, CF", p: "A entidade de classe não precisa de autorização dos associados (Súmula 629 do STF) e pode impetrar mesmo que a pretensão interesse só a parte da categoria (Súmula 630 do STF)." },
  { id: "est-remedios-constitucionais-06", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quando cabe mandado de injunção e quais seus pressupostos?", v: "Quando a falta de norma regulamentadora tornar inviável o exercício de direitos e liberdades constitucionais e de prerrogativas ligadas à nacionalidade, soberania e cidadania. Exige omissão normativa, nexo entre ela e a impossibilidade de exercer o direito e decurso de prazo razoável.", b: "Art. 5º, LXXI, CF" },
  { id: "est-remedios-constitucionais-07", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quem tem legitimidade para o mandado de injunção coletivo?", v: "Ministério Público, Defensoria Pública, partido político com representação no Congresso Nacional e organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano.", b: "Lei 13.300/2016" },
  { id: "est-remedios-constitucionais-08", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Qual teoria a Lei 13.300/2016 adotou quanto aos efeitos da decisão no mandado de injunção?", v: "Reconhecida a mora, fixa-se prazo razoável para o impetrado editar a norma e, não suprida, o Judiciário estabelece as condições de exercício do direito (concretista intermediária). Em regra, a eficácia é limitada às partes e dura até a norma regulamentadora surgir.", b: "Arts. 8º e 9º da Lei 13.300/2016", p: "A eficácia pode ser ampliada para ultra partes ou erga omnes quando isso for inerente ou indispensável ao exercício do direito (art. 9º, § 1º)." },
  { id: "est-remedios-constitucionais-09", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quais as hipóteses de cabimento do habeas data?", v: "Conhecer informações relativas ao próprio impetrante em bancos de dados governamentais ou de caráter público e retificar esses dados. A Lei 9.507/97 acrescenta a anotação de contestação ou explicação sobre dado verdadeiro, mas justificável, sob pendência judicial ou amigável.", b: "Lei 9.507/97", p: "É exceção à inafastabilidade: exige prévia recusa ou omissão administrativa em fornecer as informações." },
  { id: "est-remedios-constitucionais-10", d: "Direito Constitucional", r: "E", t: "Remédios constitucionais", f: "Quem pode propor ação popular e qual seu objeto?", v: "Qualquer cidadão, para anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural. O autor é isento de custas e sucumbência, salvo comprovada má-fé.", b: "Art. 5º, LXXIII, CF" },
  // Direito Civil · Teoria geral: fato jurídico
  { id: "est-teoria-geral-fato-juridico-01", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Quais as características da nulidade quanto a prazo, suprimento e quem pode alegá-la?", v: "Não convalesce com o tempo (a ação declaratória é imprescritível), não pode ser suprida pelo juiz nem pelas partes, deve ser pronunciada de ofício e pode ser alegada por qualquer interessado e pelo MP.", b: "Arts. 166 e 167 do CC" },
  { id: "est-teoria-geral-fato-juridico-02", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "O que acontece com o negócio dissimulado quando se reconhece a simulação?", v: "O negócio simulado é nulo, mas o que se dissimulou subsiste se for válido na substância e na forma.", b: null },
  { id: "est-teoria-geral-fato-juridico-03", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Qual o prazo para anular negócio por vício e de quando ele é contado?", v: "Decadencial de 4 anos: na coação, do dia em que ela cessar; no erro, dolo, fraude contra credores, estado de perigo e lesão, do dia do negócio; nos atos de incapazes, do dia em que cessar a incapacidade.", b: null, p: "Se a lei diz que o ato é anulável sem fixar prazo, ele é de 2 anos a contar da conclusão do ato." },
  { id: "est-teoria-geral-fato-juridico-04", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "A anulabilidade pode ser reconhecida de ofício?", v: "Não. Ela convalesce com o tempo, pode ser suprida e só pode ser alegada pelos interessados, não sendo pronunciada de ofício pelo juiz.", b: null },
  { id: "est-teoria-geral-fato-juridico-05", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "A reserva mental invalida a declaração de vontade?", v: "Não. Se a vontade contrária ficou só no íntimo do declarante, a manifestação subsiste, ainda que ele tenha feito reserva mental de não querer o que declarou.", b: "Art. 110 do CC" },
  { id: "est-teoria-geral-fato-juridico-06", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Erro de cálculo ou erro na indicação da pessoa ou coisa anulam o negócio?", v: "Não. O erro de cálculo só autoriza a correção do valor, e o erro de indicação não anula se o contexto permite identificar a pessoa ou coisa certa. A anulação também é afastada se a outra parte se oferece para cumprir conforme a vontade real.", b: null },
  { id: "est-teoria-geral-fato-juridico-07", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Dolo de terceiro anula o negócio? E o dolo acidental?", v: "O dolo de terceiro anula se a parte beneficiada sabia ou devia saber; se não sabia, o negócio vale e o terceiro responde por perdas e danos. O dolo acidental só gera perdas e danos, e o dolo recíproco não anula.", b: null },
  { id: "est-teoria-geral-fato-juridico-08", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Ameaça de exercer regularmente um direito ou temor reverencial configuram coação?", v: "Não. Nenhum dos dois é coação. Se a ameaça for contra pessoa de fora da família, o juiz decide, pelas circunstâncias, se houve coação.", b: null },
  { id: "est-teoria-geral-fato-juridico-09", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Qual a diferença essencial entre estado de perigo e lesão?", v: "No estado de perigo a pessoa assume obrigação excessiva para salvar a si ou alguém da família de grave dano conhecido pela outra parte, que precisa saber dele. Na lesão, a desproporção decorre de premente necessidade ou inexperiência, e não é preciso provar que a outra parte sabia; o negócio se mantém se houver suplemento ou redução do proveito.", b: null },
  { id: "est-teoria-geral-fato-juridico-10", d: "Direito Civil", r: "E", t: "Teoria geral: fato jurídico", f: "Em que casos a fraude contra credores é presumida e quem fica protegido?", v: "Presume-se nos atos gratuitos (doação, remissão de dívida), nas garantias dadas pelo devedor insolvente e nos atos onerosos com insolvência notória. A ação pauliana devolve o bem ao patrimônio do devedor, mas protege o terceiro adquirente de boa-fé.", b: null },
  // Direito Processual Penal · Teoria geral das provas
  { id: "est-teoria-geral-das-provas-01", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "O que é prova anômala e o que é prova irritual?", v: "Anômala é a prova típica usada para finalidade diversa daquela para a qual foi prevista. Irritual é a prova com procedimento previsto em lei que não foi respeitado na sua colheita.", b: null },
  { id: "est-teoria-geral-das-provas-02", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Qual o requisito para usar prova emprestada no processo penal?", v: "A prova vinda de outro processo só é admitida se respeitado o contraditório na sua inclusão; sem isso, não vale como prova.", b: null },
  { id: "est-teoria-geral-das-provas-03", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Qual o sistema de valoração da prova adotado como regra no processo penal e quais as exceções?", v: "Regra: livre convencimento motivado (persuasão racional). Exceções: prova tarifada, como a certidão de óbito para extinguir a punibilidade pela morte do acusado, e íntima convicção dos jurados no Tribunal do Júri.", b: null },
  { id: "est-teoria-geral-das-provas-04", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "O que diz o princípio da comunhão (ou aquisição) da prova?", v: "Depois de juntada aos autos, a prova deixa de pertencer a quem a produziu e passa a integrar o processo, podendo beneficiar qualquer das partes.", b: null },
  { id: "est-teoria-geral-das-provas-05", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Quais são as fases da produção da prova?", v: "Proposição (requerimento), admissão (o juiz defere ou não), produção (a prova ingressa no processo) e valoração (o juiz atribui valor a cada prova).", b: null },
  { id: "est-teoria-geral-das-provas-06", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "A defesa tem ônus da prova no processo penal?", v: "Sim. O ônus recai sobre quem alega o fato; a defesa também deve provar a tese que sustenta.", b: null },
  { id: "est-teoria-geral-das-provas-07", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Em que momentos o juiz pode determinar de ofício a produção de provas?", v: "Na produção antecipada de provas urgentes e relevantes, observadas necessidade, adequação e proporcionalidade; e, no curso da instrução, para dirimir dúvida sobre ponto relevante.", b: null },
  { id: "est-teoria-geral-das-provas-08", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Diferencie prova ilícita, ilícita por derivação e ilegítima.", v: "Ilícita viola norma de direito material (constitucional ou legal), como a tortura. Ilícita por derivação é a prova em si lícita, mas obtida a partir de uma ilícita. Ilegítima viola norma de natureza processual.", b: null },
  { id: "est-teoria-geral-das-provas-09", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "Quando a prova derivada de prova ilícita pode ser aproveitada?", v: "Quando não há nexo de causalidade com a prova ilícita, ou quando, mesmo havendo nexo, ela poderia ser obtida por fonte independente ou seria inevitavelmente descoberta.", b: null, p: "A regra é a contaminação (frutos da árvore envenenada); as exceções são a ausência de nexo, a fonte independente e a descoberta inevitável." },
  { id: "est-teoria-geral-das-provas-10", d: "Direito Processual Penal", r: "E", t: "Teoria geral das provas", f: "O que acontece com a prova declarada ilícita? Ela pode ser usada a favor do réu?", v: "Deve ser desentranhada e, preclusa a decisão, inutilizada pelo juiz. Há forte entendimento de que pode ser usada se for a única capaz de absolver o réu ou provar fato importante da defesa (proporcionalidade).", b: null },
  // Direito Tributário · Obrigação tributária
  { id: "est-obrigacao-tributaria-01", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Qual o objeto da obrigação tributária principal e quando ela nasce e se extingue?", v: "Nasce com o fato gerador, tem por objeto o pagamento de tributo ou de penalidade pecuniária e se extingue junto com o crédito dela decorrente. É obrigação patrimonial (dar dinheiro).", b: "Art. 113, § 1º, CTN", p: "A multa tributária integra a obrigação principal, não a acessória." },
  { id: "est-obrigacao-tributaria-02", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "A obrigação principal pode ser criada por decreto?", v: "Não. Tanto o dever de pagar tributo quanto o de pagar multa só podem ser criados por lei em sentido estrito, pela estrita legalidade tributária.", b: "Art. 150, I, CF; art. 97, V, CTN" },
  { id: "est-obrigacao-tributaria-03", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Qual o objeto da obrigação acessória e que norma pode criá-la?", v: "Prestações positivas ou negativas (fazer, não fazer, tolerar) no interesse da arrecadação ou fiscalização. Decorre da legislação tributária em sentido amplo, que inclui decretos, portarias e demais atos infralegais.", b: "Art. 113, § 2º, CTN" },
  { id: "est-obrigacao-tributaria-04", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "O que acontece quando a obrigação acessória é descumprida?", v: "Pelo simples descumprimento, ela se converte em obrigação principal quanto à penalidade pecuniária, já que pagar a multa é dar dinheiro ao Fisco.", b: "Art. 113, § 3º, CTN" },
  { id: "est-obrigacao-tributaria-05", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Quais os limites máximos das multas tributárias previstos no art. 113-A do CTN?", v: "Calculados sobre o tributo lançado ou o crédito afetado: 75% como regra; 100% havendo dolo, fraude, sonegação ou conluio; 150% em caso de reincidência.", b: "Art. 113-A, § 1º, CTN", p: "Ficam fora desses limites as multas isoladas de valor fixo, desvinculadas do valor do tributo." },
  { id: "est-obrigacao-tributaria-06", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Quem é imune ou isento fica dispensado das obrigações acessórias?", v: "Não. Imunidade e isenção só dispensam o pagamento do tributo; as obrigações acessórias continuam exigíveis e seu descumprimento gera multa. As duas obrigações são autônomas.", b: "Art. 175, parágrafo único, CTN" },
  { id: "est-obrigacao-tributaria-07", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Quando se considera ocorrido o fato gerador de situação de fato e de situação jurídica?", v: "Na situação de fato (ex.: prestar serviço, auferir renda), quando ela ocorre. Na situação jurídica (ex.: transmissão de imóvel no ITBI), quando o ato ou negócio estiver definitivamente constituído.", b: "Art. 116, I e II, CTN" },
  { id: "est-obrigacao-tributaria-08", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "Em negócio jurídico condicional, quando ocorre o fato gerador?", v: "Com condição suspensiva, só quando a condição se implementa. Com condição resolutória, desde a prática do ato ou celebração do negócio.", b: "Art. 117 do CTN" },
  { id: "est-obrigacao-tributaria-09", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "O que prevê a norma geral antielisiva do CTN?", v: "Permite à autoridade administrativa desconsiderar atos ou negócios praticados para dissimular o fato gerador ou os elementos da obrigação, observado procedimento previsto em lei ordinária. O STF declarou a regra constitucional na ADI 2446 (2022).", b: "Art. 116, parágrafo único, CTN" },
  { id: "est-obrigacao-tributaria-10", d: "Direito Tributário", r: "E", t: "Obrigação tributária", f: "O tributo é devido se o fato gerador decorrer de atividade ilícita ou de agente incapaz?", v: "Sim. Pelo pecunia non olet, a validade jurídica dos atos, a natureza do objeto e a capacidade do agente são irrelevantes para a incidência do tributo.", b: "Art. 118 do CTN" },
  // Direito Processual do Trabalho · Defesa
  { id: "est-defesa-01", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Como e quando o reclamado apresenta a contestação no processo do trabalho?", v: "Em audiência, depois de frustrada a conciliação: oralmente, em 20 minutos, ou por escrito pelo PJe até a audiência. Não há o prazo de 15 dias do CPC.", b: "Art. 847, caput e parágrafo único, da CLT" },
  { id: "est-defesa-02", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Qual o prazo mínimo entre a notificação e a audiência, para particular e para ente público?", v: "5 dias para o reclamado em geral; 20 dias (prazo em quádruplo) para União, Estados, DF, Municípios e suas autarquias e fundações de direito público que não explorem atividade econômica.", b: "Art. 841 da CLT; art. 1º do DL 779/1969" },
  { id: "est-defesa-03", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Depois de oferecida a contestação, o reclamante pode desistir da ação livremente?", v: "Não. Oferecida a contestação, ainda que eletronicamente, a desistência depende do consentimento do reclamado.", b: "Art. 841, § 3º, da CLT", p: "Vale mesmo se a contestação foi só protocolada no PJe, antes da audiência." },
  { id: "est-defesa-04", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Até quando a compensação e a retenção podem ser alegadas e quais os limites da compensação na Justiça do Trabalho?", v: "Só como matéria de defesa, na contestação, sob pena de preclusão. A compensação fica restrita a dívidas de natureza trabalhista e, no pagamento das verbas rescisórias, não pode passar de um mês de remuneração do empregado.", b: "Art. 767 e art. 477, § 5º, da CLT; Súmulas 18 e 48 do TST", p: "A dedução de valores já pagos não precisa ser alegada na contestação." },
  { id: "est-defesa-05", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Cabe contestação por negativa geral no processo do trabalho?", v: "Não. O réu deve impugnar especificamente os fatos da inicial, sob pena de serem presumidos verdadeiros. Só o defensor público, o advogado dativo e o curador especial ficam dispensados desse ônus.", b: "Art. 341 do CPC" },
  { id: "est-defesa-06", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Como se alega a incompetência no processo do trabalho?", v: "A absoluta (material, pessoal, funcional) vai na contestação e pode ser reconhecida de ofício. A relativa (territorial) exige exceção de incompetência própria.", b: "Art. 800 da CLT" },
  { id: "est-defesa-07", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Quais os requisitos da cláusula compromissória de arbitragem em contrato individual de trabalho?", v: "Remuneração superior a duas vezes o teto dos benefícios do RGPS e pactuação por iniciativa do empregado ou com sua concordância expressa.", b: "Art. 507-A da CLT" },
  { id: "est-defesa-08", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "O juiz do trabalho pode pronunciar a prescrição de ofício? Até quando ela pode ser arguida?", v: "Para o TST, não cabe pronúncia de ofício na Justiça do Trabalho. Deve ser arguida na instância ordinária: contestação, recurso ordinário ou contrarrazões; não pode aparecer pela primeira vez em recurso de revista.", b: "Súmula 153 do TST", p: "Diferente do CPC, que admite o reconhecimento de ofício." },
  { id: "est-defesa-09", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Em que casos não corre prescrição trabalhista e o que a interrompe?", v: "Ações meramente declaratórias (ex.: reconhecimento de vínculo, entrega do PPP) são imprescritíveis e contra menores de 18 anos não corre prescrição. O ajuizamento da reclamação interrompe a prescrição, ainda que em juízo incompetente.", b: "Art. 11, §§ 1º e 3º, e art. 440 da CLT" },
  { id: "est-defesa-10", d: "Direito Processual do Trabalho", r: "E", t: "Defesa", f: "Qual o prazo para o inquérito para apuração de falta grave e qual sua natureza?", v: "30 dias contados da suspensão do empregado estável, prazo decadencial. No abandono de emprego, conta-se do momento em que o empregado pretendeu voltar ao serviço.", b: "Súmula 403 do STF; Súmula 62 do TST" },
  // Ética Profissional · Sociedade de advogados e honorários advocatícios
  { id: "est-sociedade-de-advogados-e-honorarios-advo-01", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Onde a sociedade de advogados adquire personalidade jurídica?", v: "Com o registro dos atos constitutivos no Conselho Seccional da OAB, seja unipessoal ou pluripessoal. Não se registra em Junta Comercial nem em cartório.", b: null, p: "É sociedade simples, sem forma ou características de sociedade empresária." },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-02", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Quais sociedades de advogados não são admitidas a registro na OAB?", v: "As que adotam nome de fantasia, exercem atividades estranhas à advocacia ou têm como sócio ou titular pessoa não inscrita como advogado ou totalmente proibida de advogar.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-03", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Como deve ser formada a razão social da sociedade unipessoal e da pluripessoal?", v: "Unipessoal: nome do titular, completo ou parcial, mais a expressão Sociedade Individual de Advocacia. Pluripessoal: nome de pelo menos um advogado responsável; o nome de sócio falecido pode permanecer se o ato constitutivo previr.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-04", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "O advogado pode integrar mais de uma sociedade de advogados?", v: "Não na área do mesmo Conselho Seccional: lá não pode integrar duas sociedades, ter duas unipessoais ou acumular uma de cada. Em Seccionais diferentes, sem sede ou filial na mesma área, pode.", b: null, p: "Sócios da mesma sociedade também não podem representar em juízo clientes com interesses opostos." },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-05", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Como responde o sócio e como responde o advogado associado pelos danos causados aos clientes?", v: "O sócio e o titular respondem de forma subsidiária e ilimitada, por atos culposos ou dolosos. O advogado associado responde só nas causas em que efetivamente atuou pela sociedade.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-06", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Sem estipulação em contrário, quando são devidos os honorários convencionados?", v: "Um terço no início do serviço, um terço até a decisão de primeira instância e o restante ao final. Sem acordo sobre o valor, os honorários são arbitrados judicialmente conforme o trabalho e o valor econômico da questão.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-07", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "O advogado pode receber os honorários contratuais direto dos valores do cliente no processo?", v: "Sim: juntando o contrato antes da expedição do mandado de levantamento ou do precatório, o juiz manda pagar diretamente ao advogado, deduzindo do que o cliente vai receber, salvo se o cliente provar que já pagou.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-08", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "No substabelecimento com reserva, o substabelecido pode cobrar honorários direto do cliente?", v: "Não sem a intervenção do substabelecente, com quem deve ajustar previamente os honorários. A exceção é ter contrato de honorários celebrado diretamente com o cliente.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-09", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "Quais os percentuais dos honorários sucumbenciais na Justiça Comum e na do Trabalho, e podem ser compensados na sucumbência recíproca?", v: "Justiça Comum: 10% a 20%; Justiça do Trabalho: 5% a 15%, sobre a condenação ou liquidação, o proveito econômico ou, não sendo mensurável, o valor atualizado da causa. Na sucumbência recíproca, é vedada a compensação.", b: null },
  { id: "est-sociedade-de-advogados-e-honorarios-advo-10", d: "Ética Profissional", r: "E", t: "Sociedade de advogados e honorários advocatícios", f: "O advogado pode cobrar abaixo da tabela da Seccional ou reduzir os honorários se o caso for resolvido fora do Judiciário?", v: "Não. Fixar abaixo do mínimo da tabela do Conselho Seccional caracteriza aviltamento, e é vedado diminuir os honorários contratados por solução extrajudicial do litígio.", b: null },
  // Direito Tributário · Imunidades
  { id: "est-imunidades-01", d: "Direito Tributário", r: "E", t: "Imunidades", f: "As imunidades do art. 150, VI, da CF alcançam taxas e contribuições?", v: "Não. Essas imunidades (recíproca, religiosa, de partidos etc.) alcançam exclusivamente impostos; taxas, contribuições, empréstimos compulsórios e contribuição de melhoria continuam devidos.", b: "art. 150, VI, da CF/88" },
  { id: "est-imunidades-02", d: "Direito Tributário", r: "E", t: "Imunidades", f: "A imunidade recíproca se estende às autarquias e fundações públicas? Com qual limite?", v: "Sim, quanto ao patrimônio, à renda e aos serviços ligados às finalidades essenciais. Não vale para atividade econômica regida pelas normas privadas ou em que haja cobrança de preço ou tarifa do usuário.", b: "art. 150, §§ 2º e 3º, da CF/88" },
  { id: "est-imunidades-03", d: "Direito Tributário", r: "E", t: "Imunidades", f: "Empresas públicas e sociedades de economia mista têm imunidade recíproca?", v: "Segundo o STF, só as prestadoras de serviço público em sentido estrito, que não concorrem com a iniciativa privada. As que exploram atividade econômica em concorrência não têm.", b: null, p: "Cartórios extrajudiciais não têm imunidade recíproca, pois exercem a atividade com intuito lucrativo (ADI 3089)." },
  { id: "est-imunidades-04", d: "Direito Tributário", r: "E", t: "Imunidades", f: "Qual a situação dos Correios (ECT) quanto à imunidade recíproca após a Reforma Tributária?", v: "A EC 132/2023 passou a prever expressamente no texto constitucional a imunidade de impostos da empresa pública prestadora de serviço postal, quanto ao patrimônio, à renda e aos serviços ligados a suas finalidades essenciais.", b: "EC 132/2023; art. 150, § 2º, da CF/88" },
  { id: "est-imunidades-05", d: "Direito Tributário", r: "E", t: "Imunidades", f: "O promitente comprador de imóvel de ente imune paga IPTU?", v: "Sim. A imunidade recíproca é da pessoa (subjetiva), não do bem; o promitente comprador não a herda. O STF também decidiu que incide IPTU sobre imóvel público cedido a pessoa jurídica de direito privado.", b: "art. 150, § 3º, da CF/88; Tema 437 do STF" },
  { id: "est-imunidades-06", d: "Direito Tributário", r: "E", t: "Imunidades", f: "A imunidade religiosa protege só o templo? E o imóvel alugado a terceiro?", v: "Não só o templo: abrange patrimônio, renda e serviços da entidade religiosa ligados às suas finalidades essenciais, de forma direta ou indireta. Imóvel alugado continua imune ao IPTU se o aluguel for revertido para essas finalidades.", b: "art. 150, VI, b, e § 4º, da CF/88; RE 325.822", p: "A maçonaria não tem imunidade religiosa, por não ser religião (RE 562.351). Cemitério privado empresarial também não, mesmo com capela." },
  { id: "est-imunidades-07", d: "Direito Tributário", r: "E", t: "Imunidades", f: "Quem tem a imunidade do art. 150, VI, c, da CF?", v: "Partidos políticos e suas fundações, entidades sindicais dos trabalhadores e instituições de educação e de assistência social sem fins lucrativos, quanto ao patrimônio, renda e serviços ligados às finalidades essenciais.", b: "art. 150, VI, c, da CF/88", p: "Só os sindicatos de trabalhadores; sindicatos patronais ficam de fora." },
  { id: "est-imunidades-08", d: "Direito Tributário", r: "E", t: "Imunidades", f: "Imóvel de entidade do art. 150, VI, c, alugado a terceiros ou vago é imune ao IPTU?", v: "Alugado, continua imune se os aluguéis forem aplicados nas atividades da entidade (SV 52). Lotes vagos temporariamente ociosos de instituições de educação e assistência sem fins lucrativos também são imunes (Tema 693).", b: "Súmula Vinculante 52; Tema 693 do STF" },
  { id: "est-imunidades-09", d: "Direito Tributário", r: "E", t: "Imunidades", f: "Quais requisitos do art. 14 do CTN condicionam a imunidade das entidades sem fins lucrativos?", v: "Não distribuir parcela do patrimônio ou das rendas, aplicar integralmente no País os recursos nos objetivos institucionais e manter escrituração regular de receitas e despesas. O descumprimento suspende a imunidade, que volta se os requisitos forem novamente cumpridos.", b: "art. 14 do CTN" },
  { id: "est-imunidades-10", d: "Direito Tributário", r: "E", t: "Imunidades", f: "A imunidade do livro alcança insumos, e-books e e-readers?", v: "Não alcança máquinas e insumos em geral, mas inclui filmes e papéis fotográficos para impressão (Súmula 657) e o livro eletrônico com os suportes exclusivamente usados para fixá-lo, como e-readers, ainda que tenham funções acessórias (SV 57).", b: "art. 150, VI, d, da CF/88; Súmula 657 do STF; Súmula Vinculante 57" },
  // Direito Processual Civil · Procedimento comum
  { id: "est-procedimento-comum-01", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Qual a diferença entre pedido sucessivo, alternativo e subsidiário?", v: "Sucessivo: o acolhimento de um pressupõe o do anterior. Alternativo: a obrigação pode ser cumprida de mais de um modo. Subsidiário: pedidos em ordem de preferência; rejeitado o primeiro, o juiz examina o seguinte.", b: null },
  { id: "est-procedimento-comum-02", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Até quando o autor pode alterar o pedido ou a causa de pedir?", v: "Antes da citação, livremente; depois da citação e até o saneamento, só com consentimento do réu; após o saneamento, não é mais possível.", b: null },
  { id: "est-procedimento-comum-03", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Indeferida a petição inicial, qual o recurso e o juiz pode voltar atrás?", v: "Cabe apelação em 15 dias e o juiz pode se retratar em 5 dias. A sentença faz só coisa julgada formal: a ação pode ser reproposta corrigindo o vício e pagando as custas, com distribuição por dependência.", b: null },
  { id: "est-procedimento-comum-04", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Quando o juiz julga liminarmente improcedente o pedido, sem citar o réu?", v: "Nas causas que dispensam instrução, quando o pedido contraria súmula do STF ou STJ, acórdão em recursos repetitivos, tese de IRDR ou de assunção de competência, ou súmula de TJ sobre direito local; e também quando reconhece prescrição ou decadência.", b: null },
  { id: "est-procedimento-comum-05", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Quais os prazos da audiência de conciliação e mediação no procedimento comum?", v: "Designada com antecedência mínima de 30 dias, com citação do réu pelo menos 20 dias antes. Pode ter mais de uma sessão, mas não pode passar de 2 meses contados da primeira.", b: null },
  { id: "est-procedimento-comum-06", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Quando a audiência de conciliação ou mediação não é realizada?", v: "Quando o direito não admite autocomposição ou quando ambas as partes manifestam expressamente desinteresse: o autor na inicial e o réu por petição com 10 dias de antecedência. Havendo litisconsórcio, todos devem manifestar o desinteresse.", b: "Art. 319, VII, e art. 334, § 5º, do CPC", p: "O desinteresse de só uma das partes não cancela a audiência; a falta injustificada gera multa revertida a fundos do Judiciário, não à parte contrária." },
  { id: "est-procedimento-comum-07", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Quais preliminares de contestação o juiz não pode conhecer de ofício?", v: "A incompetência relativa e a convenção de arbitragem, que dependem de alegação do réu na contestação.", b: null },
  { id: "est-procedimento-comum-08", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Alegada a ilegitimidade passiva na contestação, que opções tem o autor?", v: "Em 15 dias, pode emendar a inicial para trocar o réu, reembolsando despesas e pagando honorários do advogado do excluído, ou manter o réu e incluir o indicado como litisconsorte passivo.", b: null },
  { id: "est-procedimento-comum-09", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Em que casos a revelia não gera presunção de veracidade dos fatos?", v: "Quando outro réu contesta, quando o direito é indisponível, quando falta à inicial documento indispensável à prova do ato, e quando as alegações são inverossímeis ou contrariam as provas dos autos.", b: null, p: "A presunção da revelia é relativa e admite prova em contrário." },
  { id: "est-procedimento-comum-10", d: "Direito Processual Civil", r: "E", t: "Procedimento comum", f: "Qual o recurso contra o julgamento antecipado total e contra o parcial de mérito?", v: "O total é sentença e desafia apelação. O parcial, sobre pedido incontroverso ou pronto para julgamento, é decisão interlocutória de mérito, impugnável por agravo de instrumento, e admite cumprimento provisório.", b: null },
  // Direito Empresarial · Títulos de crédito (letra de câmbio e cheque)
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-01", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "O que é o cheque e quem são as figuras envolvidas?", v: "É ordem de pagamento à vista emitida por correntista (emitente/sacador) contra banco ou instituição equiparada (sacado), em favor do beneficiário (tomador). O emitente precisa ter provisão de fundos.", b: "Art. 32, Lei nº 7.357/85" },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-02", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "Depositar cheque pré-datado antes da data combinada gera alguma consequência?", v: "Sim. Embora o cheque seja legalmente ordem à vista, a apresentação antecipada do cheque pré-datado gera dano moral ao emitente.", b: "Súmula 370, STJ", p: "O banco continua obrigado a pagar o cheque quando apresentado, pois é ordem à vista; o dano moral é cobrado do beneficiário." },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-03", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "A emissão de cheque sem fundos é sempre crime?", v: "Não. Se ficar provado que não houve fraude, não há crime; exige-se conduta dolosa no caso concreto.", b: "Súmula 246, STF" },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-04", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "A partir de que valor o cheque deve ser nominal?", v: "Cheques acima de R$ 100,00 precisam indicar o beneficiário (nominais); até esse valor podem ser ao portador.", b: null },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-05", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "Qual o prazo de apresentação do cheque?", v: "30 dias da emissão, se emitido no mesmo lugar onde deve ser pago; 60 dias, se emitido em outro lugar do país ou no exterior.", b: "Art. 33, Lei nº 7.357/85" },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-06", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "Qual o prazo prescricional da execução do cheque e quando começa?", v: "6 meses, contados do fim do prazo de apresentação (30 ou 60 dias a partir da emissão).", b: "Art. 59, Lei nº 7.357/85", p: "Os 6 meses não correm da emissão: primeiro se soma o prazo de apresentação." },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-07", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "Qual o termo inicial do prazo da monitória de cheque sem força executiva, em comparação com a nota promissória?", v: "O prazo é de 5 anos; no cheque conta-se do dia seguinte à emissão (título à vista), e na nota promissória, do dia seguinte ao vencimento.", b: "Súmulas 503 e 504, STJ" },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-08", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "Quais são as figuras da letra de câmbio e o que significa sacar o título?", v: "Sacador (emitente, quem dá a ordem), sacado (contra quem a ordem é dirigida) e tomador (beneficiário). Sacar é emitir, criar o título.", b: null },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-09", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "O que é o aceite na letra de câmbio e qual o seu efeito?", v: "É a assinatura do sacado no título, que o torna devedor principal da letra. A letra pode ser apresentada ao aceite até o vencimento, pelo portador ou por simples detentor.", b: "Art. 21, LUG (Decreto nº 57.663/66)" },
  { id: "est-titulos-de-credito-letra-de-cambio-e-che-10", d: "Direito Empresarial", r: "E", t: "Títulos de crédito (letra de câmbio e cheque)", f: "O sacado da letra de câmbio é obrigado a aceitar? O que acontece se recusar?", v: "Não é obrigado e não há meio de compeli-lo. Com a recusa, a letra vence antecipadamente contra o sacador.", b: null, p: "Na duplicata é o contrário: o aceite é, em regra, obrigatório, só podendo ser recusado nas hipóteses do art. 8º da Lei nº 5.474/68." },
  // Direito Processual Penal · Procedimento ordinário
  { id: "est-procedimento-ordinario-01", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Quando se aplica o procedimento comum ordinário no processo penal?", v: "Aos crimes com pena máxima cominada igual ou superior a 4 anos de prisão, salvo procedimento especial. Abaixo de 4 anos, o rito é sumário; infrações de menor potencial ofensivo seguem o sumaríssimo da Lei nº 9.099/95.", b: "Art. 394, CPP", p: "O critério é a pena máxima cominada, e não mais se o crime é punido com reclusão ou detenção." },
  { id: "est-procedimento-ordinario-02", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "A falta de citação do acusado gera que vício? O comparecimento espontâneo resolve?", v: "A falta de citação é nulidade absoluta, ainda que o réu saiba do processo por outro meio. O comparecimento do interessado antes de o ato se consumar sana o vício, desde que lhe sejam garantidos o conhecimento da acusação e a entrevista prévia com o advogado.", b: "Arts. 564, III, e, e 570, CPP" },
  { id: "est-procedimento-ordinario-03", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Para que o acusado é citado no rito ordinário?", v: "Para apresentar resposta escrita à acusação em 10 dias, e não para ser interrogado. O interrogatório é o último ato da instrução, em qualquer rito.", b: "Arts. 396 e 406, CPP" },
  { id: "est-procedimento-ordinario-04", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Como se faz a citação do réu que se oculta e a do réu preso?", v: "Se o réu se oculta, o oficial certifica e faz a citação por hora certa (regras do CPC); se ele não comparecer, recebe defensor dativo e o processo segue. O réu preso é sempre citado pessoalmente.", b: "Arts. 360 e 362, CPP" },
  { id: "est-procedimento-ordinario-05", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "O que acontece se o réu citado por edital não comparece nem constitui advogado?", v: "Ficam suspensos o processo e o prazo prescricional; o juiz pode determinar provas urgentes e, se presentes os requisitos, decretar a preventiva. Da decisão de suspensão cabe recurso em sentido estrito.", b: "Art. 366, CPP; art. 581, XVI, CPP", p: "Na Lei de Lavagem de Dinheiro não se aplica o art. 366: o processo segue à revelia, com defensor nomeado (art. 2º, § 2º, Lei nº 9.613/98)." },
  { id: "est-procedimento-ordinario-06", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Por quanto tempo a prescrição pode ficar suspensa na hipótese do art. 366 do CPP?", v: "Não indefinidamente: o limite é o prazo prescricional calculado pela pena máxima em abstrato do crime. Depois disso a prescrição volta a correr, embora o processo continue suspenso.", b: "Art. 109, CP", p: "Só a Constituição cria crimes imprescritíveis (racismo e ação de grupos armados contra a ordem constitucional)." },
  { id: "est-procedimento-ordinario-07", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "O edital de citação precisa transcrever a denúncia?", v: "Não. Basta indicar o dispositivo da lei penal em que o réu está incurso; o prazo do edital é de 15 dias.", b: "Súmula 366, STF; art. 361, CPP" },
  { id: "est-procedimento-ordinario-08", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "A resposta à acusação é obrigatória? E o que deve ser alegado nela sob pena de preclusão?", v: "Sim: se não apresentada, o juiz nomeia defensor para oferecê-la, sob pena de nulidade absoluta. Nela deve ser arguida a incompetência relativa, que preclui; a absoluta pode ser alegada a qualquer tempo.", b: "Art. 396-A, § 2º, CPP" },
  { id: "est-procedimento-ordinario-09", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Quais são as hipóteses de absolvição sumária no rito ordinário?", v: "Excludente manifesta da ilicitude; excludente manifesta da culpabilidade, salvo inimputabilidade; fato evidentemente atípico; e extinção da punibilidade. A decisão faz coisa julgada material.", b: "Art. 397, CPP", p: "Contra o indeferimento da absolvição sumária não há recurso: cabe habeas corpus para trancar a ação." },
  { id: "est-procedimento-ordinario-10", d: "Direito Processual Penal", r: "E", t: "Procedimento ordinário", f: "Como se desenvolve a audiência de instrução e julgamento no rito ordinário?", v: "É única e deve ocorrer em até 60 dias: ofendido, até 8 testemunhas de acusação, depois até 8 de defesa, peritos, acareações, reconhecimento e, por último, interrogatório. Sem diligências, há alegações orais de 20 minutos, prorrogáveis por mais 10, e sentença.", b: "Arts. 400 e 401, CPP", p: "Inverter a ordem (defesa antes da acusação) gera nulidade, salvo testemunha ouvida por precatória. No sumário são até 5 testemunhas e a audiência ocorre em até 30 dias." },
  // Direito Processual do Trabalho · Honorários
  { id: "est-honorarios-01", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "O que mudou com a Reforma Trabalhista em relação aos honorários de sucumbência na Justiça do Trabalho?", v: "Antes eram devidos só em hipóteses restritas (como o empregado com gratuidade assistido pelo sindicato). Depois da Lei nº 13.467/2017, a condenação da parte vencida em honorários virou regra, inclusive quando o advogado atua em causa própria.", b: "Art. 791-A, CLT" },
  { id: "est-honorarios-02", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Quais são os percentuais e a base de cálculo dos honorários de sucumbência no processo do trabalho?", v: "Entre 5% e 15% sobre o valor da liquidação da sentença, sobre o proveito econômico obtido ou, se este não puder ser medido, sobre o valor atualizado da causa.", b: "Art. 791-A, caput, CLT", p: "Os percentuais são diferentes dos do processo civil comum: na CLT o teto é 15%." },
  { id: "est-honorarios-03", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Que critérios o juiz trabalhista observa para fixar os honorários entre o mínimo e o máximo?", v: "O grau de zelo do profissional, o lugar da prestação do serviço, a natureza e a importância da causa e o trabalho realizado pelo advogado com o tempo exigido.", b: "Art. 791-A, § 2º, CLT" },
  { id: "est-honorarios-04", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "São devidos honorários nas ações contra a Fazenda Pública, com assistência sindical e na reconvenção?", v: "Sim. A CLT prevê honorários nas ações contra a Fazenda Pública, naquelas em que a parte é assistida ou substituída pelo sindicato e também na reconvenção.", b: "Art. 791-A, §§ 1º e 5º, CLT" },
  { id: "est-honorarios-05", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Como ficam os honorários na procedência parcial do pedido?", v: "O juiz fixa honorários de sucumbência recíproca, cada advogado recebendo pela parte em que seu cliente venceu, sendo proibida a compensação entre eles.", b: "Art. 791-A, § 3º, CLT", p: "Não se compensam porque os honorários pertencem aos advogados, não às partes." },
  { id: "est-honorarios-06", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Como fica a condenação em honorários do beneficiário da justiça gratuita, após a ADI 5766?", v: "O valor fica sob condição suspensiva de exigibilidade: só pode ser cobrado se, nos 2 anos seguintes ao trânsito em julgado, o credor provar que acabou a insuficiência de recursos; passado o prazo, a obrigação se extingue.", b: "Art. 791-A, § 4º, CLT; ADI 5766", p: "O STF declarou inconstitucional presumir o fim da hipossuficiência só porque o trabalhador obteve créditos em outro processo: cabe ao credor provar a mudança." },
  { id: "est-honorarios-07", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Quem paga os honorários periciais no processo do trabalho?", v: "A parte sucumbente na pretensão objeto da perícia, isto é, quem teve resultado negativo na perícia, ainda que vença o restante do processo.", b: "Art. 790-B, CLT", p: "Honorários periciais seguem a sucumbência na perícia; os advocatícios, a sucumbência no processo." },
  { id: "est-honorarios-08", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "Se o sucumbente na perícia for beneficiário da justiça gratuita, quem paga o perito?", v: "A União, pois o STF declarou inconstitucional cobrar a perícia do beneficiário da gratuidade.", b: "Súmula 457, TST; ADI 5766" },
  { id: "est-honorarios-09", d: "Direito Processual do Trabalho", r: "E", t: "Honorários", f: "O juiz do trabalho pode exigir adiantamento dos honorários periciais? E parcelá-los?", v: "Não pode exigir adiantamento; se exigir, cabe mandado de segurança para realizar a perícia sem o depósito. O parcelamento, porém, é permitido.", b: "Art. 790-B, §§ 2º e 3º, CLT; OJ 98 da SDI-2, TST" },
  // Ética Profissional · Incompatibilidades e impedimentos
  { id: "est-incompatibilidades-e-impedimentos-01", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Qual a diferença entre incompatibilidade e impedimento para advogar?", v: "Incompatibilidade é a proibição total de advogar, até em causa própria. Impedimento é proibição parcial: o advogado atua normalmente, salvo nas hipóteses específicas vedadas pelo EAOAB.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-02", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "O que o advogado deve fazer diante de incompatibilidade temporária e de incompatibilidade definitiva?", v: "Na temporária, deve licenciar-se. Na definitiva, deve requerer o cancelamento da inscrição na OAB.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-03", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Chefes do Executivo e membros da Mesa do Legislativo podem advogar em causa própria?", v: "Não. Ambos são casos de incompatibilidade, que alcança inclusive a advocacia em causa própria (o mesmo vale para os substitutos dos membros da Mesa).", b: null },
  { id: "est-incompatibilidades-e-impedimentos-04", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Membros do Judiciário, do MP e dos tribunais de contas podem advogar? E os juízes eleitorais?", v: "Esses membros, assim como quem exerce função de julgamento em órgão de deliberação coletiva, são incompatíveis. Os juízes eleitorais e seus suplentes não estão incluídos.", b: null, p: "Juízes eleitorais e suplentes ficam fora da incompatibilidade." },
  { id: "est-incompatibilidades-e-impedimentos-05", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Ocupar cargo de direção na Administração Pública sempre gera incompatibilidade?", v: "Não. Ficam de fora quem não tem poder de decisão relevante sobre interesses de terceiros, a juízo do conselho da OAB, e a administração acadêmica ligada ao magistério jurídico.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-06", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Quais outras funções geram incompatibilidade com a advocacia?", v: "Cargos vinculados ao Judiciário e serviços notariais e de registro; cargos policiais de qualquer natureza; militares na ativa; cargos com competência de lançar, arrecadar ou fiscalizar tributos; e direção ou gerência em instituições financeiras, inclusive privadas.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-07", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "O que acontece com a incompatibilidade quando o advogado deixa o cargo?", v: "Se deixa o cargo em definitivo (aposentadoria, renúncia, exoneração), a proibição acaba. Se o afastamento é temporário, como licença, a proibição continua.", b: null, p: "Licença do cargo não afasta a incompatibilidade." },
  { id: "est-incompatibilidades-e-impedimentos-08", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Servidor público pode advogar?", v: "Sim, mas é impedido de advogar contra a Fazenda Pública que o remunera ou à qual esteja vinculada a entidade. Docentes de cursos jurídicos não são impedidos.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-09", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Qual a restrição dos parlamentares que não integram a Mesa?", v: "São impedidos de advogar contra ou a favor de pessoas jurídicas de direito público, empresas públicas, sociedades de economia mista, fundações públicas, paraestatais e concessionárias ou permissionárias de serviço público.", b: null },
  { id: "est-incompatibilidades-e-impedimentos-10", d: "Ética Profissional", r: "E", t: "Incompatibilidades e impedimentos", f: "Procuradores-Gerais, Advogados-Gerais e Defensores-Gerais podem advogar fora da função?", v: "Não. Durante a investidura, são legitimados exclusivamente para a advocacia vinculada à função que exercem.", b: null },
  // Direito Processual Civil · Tutela provisória
  { id: "est-tutela-provisoria-01", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quais as características da tutela provisória em comparação com a definitiva?", v: "A tutela provisória tem cognição sumária, é precária (pode ser revogada ou modificada a qualquer tempo) e não faz coisa julgada. A definitiva tem cognição aprofundada e transita em julgado.", b: null },
  { id: "est-tutela-provisoria-02", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Diferencie tutela antecipada, tutela cautelar e tutela de evidência.", v: "Antecipada: urgente e satisfativa (entrega já o bem da vida). Cautelar: urgente e conservativa (assegura o direito para depois). Evidência: satisfativa, mas sem urgência, baseada na evidência do direito.", b: null },
  { id: "est-tutela-provisoria-03", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quais tutelas provisórias podem ser antecedentes e quais só incidentais?", v: "As tutelas de urgência (antecipada e cautelar) podem ser antecedentes ou incidentais. A tutela de evidência só pode ser requerida de forma incidental.", b: null, p: "Não existe tutela de evidência antecedente." },
  { id: "est-tutela-provisoria-04", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quais os requisitos da tutela de urgência e o juiz pode exigir caução?", v: "Probabilidade do direito e perigo de dano ou risco ao resultado útil do processo. O juiz pode exigir caução, que é dispensada para a parte hipossuficiente.", b: null },
  { id: "est-tutela-provisoria-05", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quais medidas podem efetivar a tutela cautelar?", v: "Arresto (garantir execução de quantia), sequestro (garantir entrega de coisa), arrolamento de bens (garantir partilha), registro de protesto contra alienação de bem e qualquer outra medida idônea para assegurar o direito.", b: null },
  { id: "est-tutela-provisoria-06", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Em que casos o requerente responde objetivamente pelo prejuízo causado pela tutela de urgência?", v: "Se a sentença lhe for desfavorável; se não fornecer meios para citar o requerido em 5 dias; se a medida perder a eficácia; ou se o juiz acolher prescrição ou decadência.", b: null },
  { id: "est-tutela-provisoria-07", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Na tutela antecipada antecedente, o que acontece se for concedida e se for negada?", v: "Concedida, o autor deve aditar a inicial em 15 dias (complementar argumentos, juntar documentos e confirmar o pedido final) e o réu é citado para a audiência de conciliação. Negada, o autor deve emendar a inicial em 5 dias, sob pena de extinção sem mérito.", b: null },
  { id: "est-tutela-provisoria-08", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quando ocorre a estabilização da tutela antecipada e como revê-la?", v: "Quando a tutela antecipada antecedente é concedida e o réu não a impugna. A revisão exige ação própria em até 2 anos; depois disso, não pode mais ser alterada, embora não haja coisa julgada.", b: null, p: "Só estabiliza a antecipada antecedente: não há estabilização de cautelar, de evidência nem de antecipada incidental. Qualquer forma de impugnação, não só o agravo, impede a estabilização." },
  { id: "est-tutela-provisoria-09", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Concedida a tutela cautelar antecedente, qual o prazo para formular o pedido principal e quando cessa a eficácia?", v: "O pedido principal deve ser feito em 30 dias, sem novo adiantamento de custas. A eficácia cessa se ele não for apresentado nesse prazo, se a medida não for efetivada em 30 dias, se o pedido principal for julgado improcedente ou se o processo for extinto sem mérito.", b: null },
  { id: "est-tutela-provisoria-10", d: "Direito Processual Civil", r: "E", t: "Tutela provisória", f: "Quais são as hipóteses de tutela de evidência?", v: "Abuso do direito de defesa ou propósito protelatório do réu; fatos provados só por documentos com tese firmada em casos repetitivos ou súmula vinculante; pedido reipersecutório fundado em contrato de depósito; e inicial com prova documental suficiente sem oposição razoável do réu.", b: null },
  // Direito Constitucional · Repartição de competências
  { id: "est-reparticao-de-competencias-01", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Quais princípios orientam a repartição de competências na CF/88?", v: "A predominância do interesse (nacional para a União, regional para os Estados, local para os Municípios) e a subsidiariedade, pela qual decide o ente mais próximo da questão.", b: null },
  { id: "est-reparticao-de-competencias-02", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Quais são as características da competência exclusiva da União?", v: "É administrativa (material) e indelegável, ligada à execução de atividades e serviços, como emitir moeda, manter o serviço postal, explorar telecomunicações, radiodifusão e energia elétrica, decretar estado de sítio e intervenção federal.", b: "Art. 21, CF", p: "Estado que pretende prestar radiodifusão ou energia elétrica invade competência exclusiva da União: inconstitucionalidade formal." },
  { id: "est-reparticao-de-competencias-03", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Quais são as características da competência privativa da União e quais matérias ela abrange?", v: "É legislativa e delegável. Inclui direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho (mnemônico CAPACETE PM), além de águas, energia, telecomunicações, trânsito, nacionalidade e proteção de dados.", b: "Art. 22, CF", p: "Energia, telecomunicações e radiodifusão aparecem tanto no art. 21 (prestar o serviço) quanto no art. 22 (legislar sobre o tema)." },
  { id: "est-reparticao-de-competencias-04", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Lei estadual pode tratar de bingos e loterias ou definir crimes de responsabilidade?", v: "Não. Sistemas de consórcios e sorteios, inclusive bingos e loterias, e a definição dos crimes de responsabilidade com seu processo são de competência legislativa privativa da União.", b: "Súmula Vinculante 2 e Súmula Vinculante 46, STF" },
  { id: "est-reparticao-de-competencias-05", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Como se dá a delegação da competência privativa da União?", v: "Por lei complementar, apenas sobre questões específicas e somente aos Estados e ao DF, contemplando todos eles. A simples omissão da União não autoriza os Estados a legislar, e a delegação não é renúncia: a União pode retomar a matéria.", b: "Art. 22, parágrafo único, CF", p: "Não há delegação da competência privativa a Municípios." },
  { id: "est-reparticao-de-competencias-06", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "O que caracteriza a competência comum do art. 23 da CF?", v: "É material, exercida por todos os entes em conjunto, sem hierarquia, em temas de interesse difuso, como saúde, proteção do meio ambiente e do patrimônio histórico. Lei complementar fixa normas de cooperação entre os entes.", b: "Art. 23, CF", p: "Proteger o meio ambiente é competência comum (art. 23); legislar sobre meio ambiente é competência concorrente (art. 24)." },
  { id: "est-reparticao-de-competencias-07", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Quais ramos do direito são de competência legislativa concorrente nos incisos I e II do art. 24 da CF?", v: "Penitenciário, urbanístico, financeiro, econômico, tributário e orçamento (mnemônico PUFETO).", b: "Art. 24, I e II, CF" },
  { id: "est-reparticao-de-competencias-08", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Na competência concorrente, qual o papel da União e dos Estados, e o que ocorre se a União não editar norma geral?", v: "A União edita normas gerais e os Estados/DF as suplementam com normas específicas. Inexistindo lei federal, os Estados exercem competência legislativa plena; sobrevindo a norma geral federal, a lei estadual tem a eficácia suspensa no que lhe for contrário.", b: "Art. 24, §§ 1º a 4º, CF", p: "A lei federal superveniente suspende a eficácia da estadual; não a revoga." },
  { id: "est-reparticao-de-competencias-09", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "Que competências a CF atribui expressamente aos Estados?", v: "Os Estados têm competência remanescente; cabe-lhes explorar os serviços locais de gás canalizado (vedada medida provisória na regulamentação) e instituir, por lei complementar, regiões metropolitanas, aglomerações urbanas e microrregiões.", b: "Art. 25, §§ 2º e 3º, CF" },
  { id: "est-reparticao-de-competencias-10", d: "Direito Constitucional", r: "E", t: "Repartição de competências", f: "O Município pode fixar horário de bancos, de lojas e impedir comércio do mesmo ramo em certa área?", v: "Cabe ao Município fixar o horário do comércio em geral, mas não o das agências bancárias, que é da União. Lei municipal que impede estabelecimentos do mesmo ramo em determinada área ofende a livre concorrência.", b: "Súmula Vinculante 38 e Súmula Vinculante 49, STF; Súmula 19, STJ", p: "Distância mínima entre postos de combustíveis por segurança é válida; entre farmácias, não." },
  // Direito do Trabalho · Contrato de trabalho
  { id: "est-contrato-de-trabalho-01", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Como a CLT define o contrato individual de trabalho e qual sua forma?", v: "É o acordo tácito ou expresso correspondente à relação de emprego. É contrato não solene: nasce da própria situação de fato quando presentes pessoalidade, onerosidade, subordinação e habitualidade, mesmo sem documento.", b: "Art. 442, CLT" },
  { id: "est-contrato-de-trabalho-02", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Quais são os elementos essenciais de validade do contrato de trabalho?", v: "Agente capaz; objeto lícito, possível, determinado ou determinável; e forma prescrita ou não proibida em lei.", b: null, p: "Em regra não há forma especial, mas na Administração Pública a validade exige concurso público (art. 37, II, CF)." },
  { id: "est-contrato-de-trabalho-03", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Como funciona a capacidade do menor no contrato de trabalho?", v: "Para a CLT, menor é o trabalhador de 14 a 18 anos. Ele pode firmar contrato e dar recibo de salário, mas na rescisão não pode dar quitação da indenização sem assistência dos responsáveis legais.", b: "Arts. 402 e 439, CLT; art. 7º, XXXIII, CF", p: "Entre 14 e 16 anos, só como aprendiz; até 18, vedados trabalho noturno, perigoso ou insalubre." },
  { id: "est-contrato-de-trabalho-04", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Qual a diferença entre trabalho ilícito e trabalho proibido?", v: "No trabalho ilícito o próprio objeto é criminoso (ex.: jogo do bicho), o contrato é nulo e não gera efeitos trabalhistas. No proibido o objeto é lícito, há só uma irregularidade, e o vínculo se forma normalmente.", b: "OJ 199 da SDI-1, TST" },
  { id: "est-contrato-de-trabalho-05", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Policial militar que trabalha como segurança em empresa privada pode ter vínculo de emprego reconhecido?", v: "Sim. Presentes os requisitos do art. 3º da CLT, reconhece-se o vínculo com a empresa, independentemente de eventual punição disciplinar pela corporação.", b: "Súmula 386, TST" },
  { id: "est-contrato-de-trabalho-06", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "O que são elementos acidentais e naturais do contrato de trabalho?", v: "Acidentais podem ou não aparecer, mas alteram os efeitos se incluídos: o termo (evento futuro e certo) e a condição (evento futuro e incerto). Naturais decorrem da essência do contrato e valem sem menção, como o dever de pagar salário.", b: "Art. 121, CC" },
  { id: "est-contrato-de-trabalho-07", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Em que hipóteses a CLT admite contrato por prazo determinado e qual o prazo máximo?", v: "Serviço cuja natureza ou transitoriedade justifique o prazo, atividade empresarial transitória e contrato de experiência. O prazo máximo é de 2 anos, com uma única prorrogação dentro desse limite.", b: "Arts. 443, § 2º, e 445, CLT", p: "A regra é o prazo indeterminado, pelo princípio da continuidade." },
  { id: "est-contrato-de-trabalho-08", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Qual o prazo do contrato de experiência e quantas prorrogações admite?", v: "Máximo de 90 dias, com uma única prorrogação dentro desse limite. Prorrogado mais de uma vez, passa a vigorar sem prazo.", b: "Art. 445, parágrafo único, e art. 451, CLT; Súmula 188, TST" },
  { id: "est-contrato-de-trabalho-09", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Qual intervalo deve haver entre dois contratos por prazo determinado sucessivos?", v: "6 meses. Se não respeitado, o segundo vira contrato por prazo indeterminado, salvo se o primeiro terminou pela execução de serviço especializado ou por certo acontecimento.", b: "Art. 452, CLT" },
  { id: "est-contrato-de-trabalho-10", d: "Direito do Trabalho", r: "E", t: "Contrato de trabalho", f: "Quais as principais regras do contrato de trabalho intermitente?", v: "Deve ser escrito, com valor-hora não inferior ao do salário mínimo nem ao de colegas da mesma função. A convocação se faz com 3 dias corridos de antecedência e o empregado tem 1 dia útil para responder (silêncio = recusa); a inatividade não é tempo à disposição.", b: "Arts. 443, § 3º, e 452-A, CLT", p: "Aceita a convocação, quem descumprir sem justo motivo paga multa de 50% da remuneração que seria devida, em 30 dias." },
  // Direito Administrativo · Serviços públicos
  { id: "est-servicos-publicos-01", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Em que situações a interrupção do serviço público não viola o princípio da continuidade?", v: "Em emergência e, com aviso prévio, por razões técnicas ou de segurança das instalações ou por inadimplemento do usuário, considerado o interesse da coletividade.", b: null, p: "O corte por falta de pagamento depende de aviso prévio." },
  { id: "est-servicos-publicos-02", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Qual a diferença entre serviços uti universi e uti singuli?", v: "Uti universi atendem a grupo indeterminado e não geram direito subjetivo individual. Uti singuli têm usuários determinados e uso mensurável (ex.: energia elétrica), podem ser exigidos individualmente e remunerados por taxa ou tarifa.", b: null },
  { id: "est-servicos-publicos-03", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Na delegação de serviço público, o Estado transfere a titularidade?", v: "Não. O Estado delega apenas a execução; a titularidade e o controle continuam com o Poder Público.", b: null },
  { id: "est-servicos-publicos-04", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Qual a exigência constitucional para delegar serviço público por concessão ou permissão?", v: "Prévia licitação, na forma da lei. Para a concessão, a modalidade é concorrência ou diálogo competitivo.", b: "art. 175 da CF/88", p: "A outorga não tem exclusividade, salvo inviabilidade técnica ou econômica justificada antes do edital." },
  { id: "est-servicos-publicos-05", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "O que é a concessão comum precedida de obra pública?", v: "Contrato em que o particular executa a obra por sua conta e risco e, concluída, explora o serviço dela decorrente por prazo determinado, recuperando o investimento e o lucro com as tarifas (ex.: pedágio).", b: "art. 2º, III, da Lei 8.987/95" },
  { id: "est-servicos-publicos-06", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Quais as características da permissão de serviço público?", v: "Contrato de adesão, precário e revogável unilateralmente pelo poder concedente, sempre precedido de licitação; o permissionário executa o serviço em seu nome, por sua conta e risco.", b: "art. 40 da Lei 8.987/95" },
  { id: "est-servicos-publicos-07", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Qual a diferença entre rescisão, caducidade e encampação da concessão?", v: "Rescisão: extinção por culpa do poder concedente, a pedido do concessionário. Caducidade: por inadimplemento do concessionário. Encampação: retomada por interesse público, sem culpa de ninguém.", b: "art. 35 da Lei 8.987/95", p: "Mesmo com culpa da Administração, o concessionário não pode interromper o serviço." },
  { id: "est-servicos-publicos-08", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Como é declarada a caducidade e há indenização prévia?", v: "Após dar ao concessionário chance de corrigir as falhas e em processo administrativo com defesa, a caducidade é declarada por decreto, sem indenização prévia; eventual indenização desconta as multas devidas.", b: "art. 38, §§ 4º e 5º, da Lei 8.987/95" },
  { id: "est-servicos-publicos-09", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Quais os requisitos da encampação?", v: "Retomada do serviço durante o prazo da concessão, por interesse público, mediante lei autorizativa específica e após prévio pagamento de indenização.", b: "art. 37 da Lei 8.987/95", p: "Na encampação a indenização é prévia; na caducidade, não." },
  { id: "est-servicos-publicos-10", d: "Direito Administrativo", r: "E", t: "Serviços públicos", f: "Como é remunerado o parceiro privado em cada modalidade de PPP e quais as vedações?", v: "Concessão administrativa: só pelo Poder Público; patrocinada: parte pelo Poder Público e parte pelos usuários. É vedada PPP abaixo de R$ 10 milhões, com prazo inferior a 5 anos ou com objeto único de mão de obra, fornecimento de equipamentos ou execução de obra.", b: null },
  // Direito Civil · Contratos: espécies comuns
  { id: "est-contratos-especies-comuns-01", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Na compra e venda, quem arca com as despesas de escritura e registro e com as da tradição, e até quando os riscos da coisa são do vendedor?", v: "Salvo ajuste, escritura e registro ficam com o comprador e a tradição com o vendedor. Até a tradição, os riscos da coisa correm pelo vendedor e os do preço pelo comprador.", b: null, p: "Os riscos passam ao comprador se ele estiver em mora de receber a coisa posta à sua disposição." },
  { id: "est-contratos-especies-comuns-02", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "O descendente pode comprar bem do ascendente livremente?", v: "Não. A venda de ascendente a descendente exige consentimento expresso dos demais descendentes e do cônjuge do alienante, dispensado o do cônjuge casado no regime da separação obrigatória.", b: null },
  { id: "est-contratos-especies-comuns-03", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Na venda ad mensuram, o que o comprador pode exigir se faltar área?", v: "Pode exigir o complemento da área e, se isso for impossível, pedir a resolução do contrato ou o abatimento proporcional do preço. Na venda ad corpus, a referência à medida é só enunciativa.", b: null },
  { id: "est-contratos-especies-comuns-04", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Quais as características da retrovenda?", v: "Cláusula pela qual o vendedor pode recomprar o bem; só vale para imóveis e tem prazo decadencial máximo de 3 anos. O vendedor restitui o preço recebido e as despesas do comprador.", b: null },
  { id: "est-contratos-especies-comuns-05", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Quais as características da venda com reserva de domínio e o que o vendedor pode fazer se o comprador atrasar?", v: "O vendedor mantém a propriedade até o pagamento integral; só vale para bens móveis e exige forma escrita. Em mora o comprador, o vendedor pode cobrar as prestações vencidas e vincendas ou recuperar a posse da coisa.", b: null },
  { id: "est-contratos-especies-comuns-06", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Quando a doação é nula e quando é anulável?", v: "É nula a doação de todos os bens sem reserva e a da parte que invade a legítima (aferida no momento da doação). É anulável a doação do cônjuge adúltero ao cúmplice e a feita em fraude contra credores.", b: null, p: "A legítima é calculada no momento da liberalidade, não na morte do doador." },
  { id: "est-contratos-especies-comuns-07", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Em que casos a doação pode ser revogada e qual o prazo?", v: "Por descumprimento do encargo ou por ingratidão do donatário (atentado contra a vida, homicídio doloso, ofensa física, injúria ou calúnia grave, recusa de alimentos). O prazo é de 1 ano a contar do fato ou de quando o doador dele soube.", b: null, p: "São irrevogáveis por ingratidão as doações puramente remuneratórias, as com encargo já cumprido, as em cumprimento de obrigação natural e as feitas para determinado casamento." },
  { id: "est-contratos-especies-comuns-08", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Na locação, quais garantias o locador pode exigir e quanto pode ser a caução em dinheiro?", v: "Caução, fiança, seguro de fiança locatícia ou cessão fiduciária de quotas de fundo de investimento, mas só uma por vez (salvo built-to-suit). A caução em dinheiro não pode passar de 3 aluguéis.", b: null, p: "O fiador de locação não pode opor o bem de família à execução." },
  { id: "est-contratos-especies-comuns-09", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Como funciona o direito de preferência do locatário na venda do imóvel?", v: "Ele pode comprar em igualdade com o terceiro, em 30 dias contados do conhecimento da proposta; desrespeitado, cabe perdas e danos. Para haver o imóvel, precisa de contrato registrado pelo menos 30 dias antes da venda e agir em 6 meses do registro.", b: null, p: "A preferência do condômino prevalece sobre a do locatário." },
  { id: "est-contratos-especies-comuns-10", d: "Direito Civil", r: "E", t: "Contratos: espécies comuns", f: "Qual a diferença entre comodato e mútuo?", v: "Comodato é empréstimo gratuito de coisa infungível; mútuo é empréstimo de coisa fungível, gratuito ou oneroso. Ambos são contratos reais, que se aperfeiçoam com a entrega.", b: null },
  // Direito Tributário · Tributos
  { id: "est-tributos-01", d: "Direito Tributário", r: "E", t: "Tributos", f: "Quais as características de tributo extraídas da definição legal?", v: "Prestação pecuniária (em dinheiro, nunca em bens), compulsória, instituída em lei, que não constitui sanção de ato ilícito e cobrada por atividade administrativa plenamente vinculada.", b: "Art. 3º do CTN", p: "Multa não é tributo: ato ilícito gera punição, nunca tributo." },
  { id: "est-tributos-02", d: "Direito Tributário", r: "E", t: "Tributos", f: "Qual a diferença entre tributo fiscal, extrafiscal e parafiscal?", v: "Fiscal: só arrecadar. Extrafiscal: além de arrecadar, induzir comportamentos e intervir na economia. Parafiscal: arrecadar para entidades que desempenham atividade de interesse público, como autarquias, conselhos profissionais e o Sistema S.", b: null },
  { id: "est-tributos-03", d: "Direito Tributário", r: "E", t: "Tributos", f: "Quais os requisitos do Imposto Extraordinário de Guerra?", v: "Competência exclusiva da União, só na iminência ou ocorrência de guerra externa; pode usar fato gerador já atribuído à União ou a outro ente; pode ser criado por lei ordinária ou medida provisória e deve ser suprimido gradualmente em até 5 anos após cessadas as causas.", b: "Art. 154, II, CF" },
  { id: "est-tributos-04", d: "Direito Tributário", r: "E", t: "Tributos", f: "Quais os requisitos do imposto residual da União?", v: "Exige lei complementar, deve ser não cumulativo e não pode ter fato gerador ou base de cálculo próprios dos impostos já discriminados na Constituição.", b: "Art. 154, I, CF", p: "Não pode ser criado por lei ordinária nem por medida provisória." },
  { id: "est-tributos-05", d: "Direito Tributário", r: "E", t: "Tributos", f: "Que serviço público pode ser remunerado por taxa?", v: "Serviço público específico e divisível, efetivamente utilizado ou posto à disposição do contribuinte. Por isso a iluminação pública não pode ser cobrada por taxa (SV 41), mas a coleta de lixo domiciliar pode (SV 19).", b: "Art. 145, II, CF; Súmulas Vinculantes 19 e 41", p: "A taxa de polícia exige exercício efetivo do poder de polícia; não cabe pelo exercício apenas potencial." },
  { id: "est-tributos-06", d: "Direito Tributário", r: "E", t: "Tributos", f: "A taxa pode usar elementos da base de cálculo de um imposto?", v: "A taxa não pode ter base de cálculo ou fato gerador idênticos aos de imposto, mas o STF admite usar um ou mais elementos da base de um imposto, desde que não haja identidade integral.", b: "Art. 145, § 2º, CF; art. 77, parágrafo único, CTN; Súmula Vinculante 29" },
  { id: "est-tributos-07", d: "Direito Tributário", r: "E", t: "Tributos", f: "Qual a diferença entre taxa e preço público? O pedágio é taxa?", v: "Taxa é tributo: compulsória, criada por lei e sujeita ao regime tributário. Preço público é obrigação voluntária e contratual. O STF considera o pedágio preço público, não sujeito à legalidade tributária estrita.", b: "Súmula 545 do STF" },
  { id: "est-tributos-08", d: "Direito Tributário", r: "E", t: "Tributos", f: "Quais os limites de cobrança da contribuição de melhoria?", v: "O fato gerador é a valorização imobiliária decorrente de obra pública. Limite total: custo da obra; limite individual: acréscimo de valor que a obra trouxe a cada imóvel.", b: "Art. 81 do CTN" },
  { id: "est-tributos-09", d: "Direito Tributário", r: "E", t: "Tributos", f: "Em que hipóteses a União pode instituir empréstimo compulsório e por qual lei?", v: "Calamidade pública, guerra externa ou sua iminência e investimento público urgente de relevante interesse nacional. Exige lei complementar, a arrecadação fica vinculada à causa e o valor deve ser restituído.", b: "Art. 148 da CF; art. 15 do CTN" },
  { id: "est-tributos-10", d: "Direito Tributário", r: "E", t: "Tributos", f: "Quais contribuições especiais exigem lei complementar e quem pode instituir a contribuição de iluminação pública?", v: "Em regra as contribuições são criadas por lei ordinária, mas a residual da seguridade social e a CBS exigem lei complementar. A contribuição de iluminação pública e monitoramento de logradouros é dos Municípios e do DF, por lei ordinária, podendo ser cobrada na conta de energia.", b: "Art. 149-A da CF", p: "A anuidade da OAB não tem natureza tributária, ao contrário das anuidades dos demais conselhos profissionais." },
  // Ética Profissional · Infrações e sanções disciplinares
  { id: "est-infracoes-e-sancoes-disciplinares-01", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Que sanção se aplica a infrações como captar causas, violar sigilo sem justa causa ou abandonar a causa sem justo motivo?", v: "Censura. É a pena típica das infrações de menor gravidade, como angariar clientela, usar agenciador, assinar peça que não fez, violar sigilo e abandonar a causa antes de 10 dias da comunicação da renúncia.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-02", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quais infrações levam à suspensão de 30 dias a 12 meses?", v: "Condutas desonestas ou de maior gravidade, como ajudar cliente a fraudar a lei, locupletar-se à custa do cliente, recusar prestação de contas, receber valores da parte contrária sem autorização, reter autos abusivamente, conduta incompatível e assédio moral, sexual ou discriminação.", b: null, p: "A suspensão por falta de pagamento de anuidades e contribuições à OAB foi declarada inconstitucional pelo STF como sanção política (ADI 7020)." },
  { id: "est-infracoes-e-sancoes-disciplinares-03", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Que sanção cabe ao advogado que incide em erros reiterados que evidenciem inépcia profissional?", v: "Suspensão, que perdura até que ele preste novas provas de habilitação.", b: null, p: "Aqui a suspensão não segue o prazo de 30 dias a 12 meses: dura até a nova prova de habilitação." },
  { id: "est-infracoes-e-sancoes-disciplinares-04", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quais infrações são punidas com exclusão dos quadros da OAB?", v: "Fazer falsa prova de requisito para a inscrição, tornar-se moralmente inidôneo e praticar crime infamante; também a aplicação de suspensão por três vezes.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-05", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Qual o quórum exigido para aplicar a pena de exclusão?", v: "Manifestação favorável de 2/3 dos membros do Conselho Seccional competente.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-06", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "A censura pode ser convertida em advertência? Pode ser divulgada?", v: "Havendo circunstância atenuante, a censura pode virar advertência em ofício reservado, sem registro nos assentamentos do inscrito. A censura não pode ser objeto de publicidade.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-07", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quando cabe multa disciplinar e quais são seus limites?", v: "É aplicada cumulativamente com censura ou suspensão quando houver agravantes, entre o valor de uma anuidade e o de dez anuidades.", b: null, p: "A multa nunca é aplicada isoladamente." },
  { id: "est-infracoes-e-sancoes-disciplinares-08", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quais são exemplos de circunstâncias atenuantes na aplicação de sanção disciplinar?", v: "Falta cometida na defesa de prerrogativa profissional, ausência de punição anterior, exercício assíduo de mandato ou cargo na OAB e prestação de relevantes serviços à advocacia ou à causa pública. O rol é exemplificativo.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-09", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quando o advogado punido pode pedir reabilitação?", v: "Um ano após o cumprimento de qualquer sanção, com provas efetivas de bom comportamento. Se a sanção decorreu de crime, depende também da reabilitação criminal.", b: null },
  { id: "est-infracoes-e-sancoes-disciplinares-10", d: "Ética Profissional", r: "E", t: "Infrações e sanções disciplinares", f: "Quais os prazos de prescrição da pretensão punitiva disciplinar na OAB?", v: "5 anos, contados da constatação oficial do fato. Há prescrição intercorrente se o processo ficar paralisado por mais de 3 anos aguardando despacho ou julgamento, com arquivamento de ofício ou a requerimento.", b: null, p: "O prazo de 5 anos não corre da data do fato, e sim da sua constatação oficial." },
  // Direito Constitucional · Processo legislativo
  { id: "est-processo-legislativo-01", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "A sanção do Chefe do Executivo convalida vício de iniciativa em projeto de lei?", v: "Não. Pelo princípio da não convalidação das nulidades, o vício formal de iniciativa gera nulidade e nem a sanção o corrige.", b: null, p: "Projeto parlamentar sobre matéria de iniciativa privativa do Executivo continua inconstitucional mesmo sancionado." },
  { id: "est-processo-legislativo-02", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Lei sobre regime jurídico, estabilidade ou aumento de remuneração de servidores pode nascer de iniciativa parlamentar?", v: "Não. É iniciativa privativa do Presidente da República e, por simetria, do Governador e do Prefeito nos seus âmbitos.", b: "art. 61, § 1º, II, a e c, da CF/88" },
  { id: "est-processo-legislativo-03", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Quais os limites da iniciativa popular de lei?", v: "Não pode tratar de matéria de iniciativa privativa nem propor emenda à Constituição Federal. Na esfera municipal, a Lei Orgânica deve prevê-la para projetos de interesse local subscritos por pelo menos 5% do eleitorado.", b: "art. 61, § 2º, e art. 29, XIII, da CF/88" },
  { id: "est-processo-legislativo-04", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Projeto de lei rejeitado pode ser reapresentado na mesma sessão legislativa?", v: "Em regra não, mas pode se houver proposta da maioria absoluta dos membros de qualquer das Casas.", b: "art. 67 da CF/88", p: "Para PEC e MP rejeitadas, a irrepetibilidade na mesma sessão legislativa é absoluta." },
  { id: "est-processo-legislativo-05", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Emendas parlamentares podem aumentar despesa em projeto de iniciativa privativa do Executivo?", v: "Não, salvo nas emendas aos projetos de LOA e LDO. A emenda também precisa guardar pertinência temática com o projeto.", b: "art. 63, I, da CF/88" },
  { id: "est-processo-legislativo-06", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Quais os prazos da sanção e do veto e existe veto tácito?", v: "O Presidente tem 15 dias úteis para sancionar ou vetar; vetando, comunica os motivos ao Presidente do Senado em 48 horas. Não existe veto tácito: o silêncio importa sanção.", b: "art. 66, §§ 1º e 3º, da CF/88", p: "Veto parcial não pode atingir palavra ou expressão isolada, só texto integral de artigo, parágrafo, inciso ou alínea." },
  { id: "est-processo-legislativo-07", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Como o Congresso derruba o veto?", v: "Em sessão conjunta, em 30 dias do recebimento, por votação aberta e maioria absoluta de deputados e senadores. Derrubado o veto, o Presidente promulga em 48 horas; se não o fizer, promulga o Presidente do Senado.", b: null },
  { id: "est-processo-legislativo-08", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Quais os requisitos de aprovação e de promulgação de uma emenda constitucional?", v: "Dois turnos de votação em cada Casa, com 3/5 dos votos dos membros em ambos. A promulgação é das Mesas da Câmara e do Senado, sem sanção ou veto do Presidente.", b: "art. 60, §§ 2º e 3º, da CF/88", p: "Não cabe emenda na vigência de intervenção federal, estado de defesa ou estado de sítio, e não há iniciativa popular de PEC." },
  { id: "est-processo-legislativo-09", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Lei complementar e lei ordinária têm hierarquia entre si?", v: "Não. A diferença é a matéria reservada e o quórum (maioria absoluta para a complementar). Lei complementar que trata de tema de lei ordinária é materialmente ordinária e pode ser alterada por lei ordinária; o inverso gera inconstitucionalidade formal.", b: "art. 69 da CF/88" },
  { id: "est-processo-legislativo-10", d: "Direito Constitucional", r: "E", t: "Processo legislativo", f: "Quais matérias não podem ser tratadas por medida provisória e qual seu prazo?", v: "Entre outras: nacionalidade, direitos políticos e eleitoral, direito penal, processual penal e processual civil, organização do Judiciário e do MP, orçamento (salvo crédito extraordinário) e matéria de lei complementar. Vale por 60 dias, prorrogáveis automaticamente uma vez por igual período.", b: "art. 62, §§ 1º e 7º, da CF/88" },
  // Direito Processual Penal · Recursos
  { id: "est-recursos-01", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "O Ministério Público pode desistir de recurso que interpôs?", v: "Não. O MP não é obrigado a recorrer, mas, uma vez interposto o recurso, não pode desistir dele. Como fiscal da lei, pode opinar pelo não provimento em parecer.", b: "Art. 576 do CPP" },
  { id: "est-recursos-02", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "No processo penal, o prazo recursal conta da intimação ou da juntada do mandado? E se réu e defensor forem intimados em datas diferentes?", v: "Conta da data da intimação, não da juntada do mandado ou da carta. Intimados réu e defensor constituído, o prazo começa da última intimação (STJ).", b: "Súmula 710 do STF" },
  { id: "est-recursos-03", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Quando a fungibilidade recursal não se aplica no processo penal?", v: "Quando há má-fé. Pela teoria do prazo menor, há má-fé se o recurso errado foi interposto fora do prazo do recurso correto, aproveitando prazo maior.", b: "Art. 579 do CPP" },
  { id: "est-recursos-04", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "O que é a reformatio in pejus indireta?", v: "Anulada a sentença em recurso exclusivo da defesa, a nova sentença não pode ser mais gravosa ao réu do que a anulada. Também é nula a decisão do tribunal que acolhe contra o réu nulidade não arguida no recurso da acusação, salvo recurso de ofício.", b: "Súmula 160 do STF" },
  { id: "est-recursos-05", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Quais os prazos do recurso em sentido estrito e o juiz pode se retratar?", v: "Interposição em 5 dias (20 dias no caso do inciso XIV do art. 581) e razões em 2 dias. O juiz pode reformar a decisão em 2 dias (efeito regressivo). Decisões do juiz da execução são atacadas por agravo em execução, não por RESE.", b: "Arts. 581, 586, 588 e 589 do CPP; art. 197 da LEP" },
  { id: "est-recursos-06", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Recurso contra a rejeição da denúncia: o acusado precisa ser intimado para contrarrazões?", v: "Sim. Ainda que não citado, o acusado deve ser intimado para contrarrazoar o recurso contra a rejeição da denúncia ou queixa; a falta gera nulidade.", b: "Súmula 707 do STF" },
  { id: "est-recursos-07", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Quais os prazos da apelação para as partes e para o ofendido não habilitado como assistente?", v: "Interposição em 5 dias e razões em 8. No JECrim, 10 dias, com razões junto. O ofendido não habilitado tem 15 dias, contados do fim do prazo do MP; o já habilitado, 5 dias.", b: "Arts. 593, 598, parágrafo único, e 600 do CPP; Súmula 448 do STF" },
  { id: "est-recursos-08", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Na apelação contra decisão do Júri, o tribunal pode julgar fora dos fundamentos indicados na interposição?", v: "Não. A apelação do Júri é de fundamentação vinculada às alíneas do art. 593, III, indicadas na interposição.", b: "Art. 593, III, do CPP; Súmula 713 do STF" },
  { id: "est-recursos-09", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Apelação do Júri por decisão dos jurados manifestamente contrária à prova dos autos: qual o efeito do provimento e quantas vezes cabe?", v: "O réu é submetido a novo julgamento pelo Júri, e não se admite segunda apelação pelo mesmo motivo, qualquer que seja a parte. Já nos erros do juiz presidente (alíneas b e c), o próprio tribunal corrige a sentença ou a pena.", b: "Art. 593, III, d, e §§ 1º e 3º, do CPP", p: "Afastar qualificadora reconhecida pelos jurados se pede pela alínea d e leva a novo júri." },
  { id: "est-recursos-10", d: "Direito Processual Penal", r: "E", t: "Recursos", f: "Quando cabem embargos infringentes e de nulidade, em que prazo e com qual limite?", v: "Contra decisão colegiada de segunda instância não unânime e desfavorável ao réu, em apelação ou RESE, no prazo de 10 dias, limitados ao conteúdo do voto vencido.", b: null },
  // Direito Penal · Crimes contra o patrimônio
  { id: "est-crimes-contra-o-patrimonio-01", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Quando se consuma o furto, segundo a teoria adotada pelo STF?", v: "Pela teoria da amotio, com a simples inversão da posse do bem, ainda que por pouco tempo e sem posse mansa e tranquila. A tentativa é possível, pois a subtração pode ser fracionada.", b: "Art. 155 do CP", p: "O furto de uso é fato atípico, por faltar o fim de assenhoreamento definitivo (\"para si ou para outrem\")." },
  { id: "est-crimes-contra-o-patrimonio-02", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "O privilégio do furto pode ser aplicado ao furto qualificado?", v: "Sim, desde que a qualificadora seja de natureza objetiva. O privilégio exige réu primário e coisa de pequeno valor e permite trocar reclusão por detenção, reduzir a pena ou aplicar só multa.", b: "Art. 155, § 2º, CP; Súmula 511 do STJ" },
  { id: "est-crimes-contra-o-patrimonio-03", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Qual a diferença entre furto mediante fraude e estelionato?", v: "No furto mediante fraude, o engano serve para distrair a vítima e permitir a subtração. No estelionato, o engano leva a própria vítima a entregar o bem ao agente.", b: "Art. 155, § 4º, II, e art. 171 do CP", p: "Na qualificadora da destreza, se a vítima percebe a subtração, ela não se configura." },
  { id: "est-crimes-contra-o-patrimonio-04", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Qual a diferença entre roubo próprio e impróprio quanto à tentativa?", v: "No próprio, a violência ou grave ameaça vem antes ou durante a subtração, e a tentativa é admitida. No impróprio, ela vem logo depois da subtração, para garantir a coisa ou a impunidade, e a posição majoritária não admite tentativa.", b: "Art. 157, caput e § 1º, CP" },
  { id: "est-crimes-contra-o-patrimonio-05", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Arma de brinquedo ou desmuniciada aumenta a pena do roubo?", v: "Não. Para STF e STJ falta potencial lesivo; responde-se por roubo simples, pela grave ameaça. A perícia da arma é dispensável se outras provas demonstrarem sua potencialidade lesiva.", b: "Art. 157, § 2º, VII, CP", p: "O princípio da insignificância não se aplica ao roubo, por haver violência ou grave ameaça." },
  { id: "est-crimes-contra-o-patrimonio-06", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Há latrocínio consumado se a morte ocorre mas a subtração não se realiza?", v: "Sim. O latrocínio se consuma com a morte, mesmo sem a subtração. Se a subtração se consuma e a morte fica tentada, há latrocínio tentado. É crime hediondo.", b: "Art. 157, § 3º, CP; Súmula 610 do STF; art. 1º, II, Lei 8.072/90" },
  { id: "est-crimes-contra-o-patrimonio-07", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "O que distingue o roubo da extorsão e quando a extorsão se consuma?", v: "No roubo o agente subtrai diretamente o bem; na extorsão o comportamento da vítima é indispensável para obter a vantagem. A extorsão é crime formal e se consuma quando a vítima faz, tolera ou deixa de fazer o exigido, ainda sem a vantagem.", b: "Art. 158 do CP; Súmula 96 do STJ", p: "O \"sequestro relâmpago\" (levar a vítima ao caixa eletrônico) é extorsão com restrição da liberdade (art. 158, § 3º), não roubo." },
  { id: "est-crimes-contra-o-patrimonio-08", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Quando se consuma a extorsão mediante sequestro e em que ela difere do sequestro relâmpago?", v: "É crime formal e permanente: consuma-se com a privação da liberdade, ainda que o resgate não seja pago. Nela, a libertação é condicionada a resgate pago por terceiro; no sequestro relâmpago, a própria vítima é obrigada a proporcionar a vantagem.", b: "Art. 159 do CP", p: "É hedionda já na forma simples; durar mais de 24 horas é qualificadora." },
  { id: "est-crimes-contra-o-patrimonio-09", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Qual a diferença entre receptação e favorecimento real?", v: "Na receptação o agente age em proveito próprio ou de terceiro diverso do autor do crime anterior. No favorecimento real ele visa só tornar seguro o proveito do crime para o próprio autor.", b: "Art. 180 e art. 349 do CP", p: "A receptação existe mesmo que o autor do crime anterior seja desconhecido, inimputável ou isento de pena (art. 180, § 4º)." },
  { id: "est-crimes-contra-o-patrimonio-10", d: "Direito Penal", r: "E", t: "Crimes contra o patrimônio", f: "Quando não se aplicam as imunidades dos arts. 181 e 182 do CP?", v: "Se o crime for roubo, extorsão ou houver violência ou grave ameaça à pessoa; ao estranho que participa do crime; e se a vítima tiver 60 anos ou mais.", b: "Art. 183 do CP", p: "Contra cônjuge na constância da sociedade conjugal e ascendente ou descendente há isenção de pena (art. 181); contra irmão ou tio/sobrinho que coabita, a ação depende de representação (art. 182)." },
  // Direito Administrativo · Agentes públicos
  { id: "est-agentes-publicos-01", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Qual a diferença entre cargo em comissão e função de confiança?", v: "Ambos são de chefia, direção e assessoramento. O cargo em comissão pode ser ocupado por qualquer pessoa, sem concurso, com livre nomeação e exoneração; a função de confiança só é exercida por servidor ocupante de cargo efetivo.", b: null },
  { id: "est-agentes-publicos-02", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "A vedação ao nepotismo alcança cargos efetivos e cargos políticos?", v: "A Súmula Vinculante 13 veda o nepotismo direto e cruzado nos cargos em comissão de todos os Poderes, mas não se aplica a cargos efetivos providos por concurso. Cargos políticos, em regra, ficam fora, salvo nomeação manifestamente desarrazoada por falta de qualificação técnica ou inidoneidade moral.", b: "Súmula Vinculante 13, STF" },
  { id: "est-agentes-publicos-03", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "O que diz a Súmula Vinculante 43 sobre provimento derivado?", v: "É inconstitucional qualquer forma de provimento que permita ao servidor ingressar, sem concurso próprio, em cargo que não integra a carreira em que estava investido, como a antiga ascensão ou transposição.", b: "Súmula Vinculante 43, STF", p: "A promoção dentro da mesma carreira continua válida." },
  { id: "est-agentes-publicos-04", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Em que condições o edital pode fixar limite de idade, exigir psicotécnico e quando se exige o diploma?", v: "Limite de idade e exame psicotécnico só com previsão em lei e, no caso da idade, quando justificado pela natureza das atribuições. O diploma ou habilitação legal se exige na posse, e não na inscrição.", b: "Súmula 683, STF; Súmula Vinculante 44, STF; Súmula 266, STJ" },
  { id: "est-agentes-publicos-05", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Qual o prazo de validade do concurso e quando o aprovado tem direito subjetivo à nomeação?", v: "Até 2 anos, prorrogável uma vez por igual período. O aprovado fora das vagas tem mera expectativa, mas adquire direito se houver quebra da ordem de classificação ou preterição arbitrária durante a validade.", b: "Art. 37, III e IV, CF; Súmula 15, STF" },
  { id: "est-agentes-publicos-06", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Quando a Constituição permite acumular cargos públicos e como se aplica o teto nesse caso?", v: "Com compatibilidade de horários: dois cargos de professor, um de professor com outro técnico ou científico, ou dois privativos de profissionais de saúde. O teto incide sobre cada vínculo isoladamente, não sobre a soma.", b: "Art. 37, XVI e XVII, CF", p: "Nunca se admite um terceiro vínculo, ainda que todos sejam de professor." },
  { id: "est-agentes-publicos-07", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Quais os prazos de posse, exercício e estágio probatório do servidor federal?", v: "Posse em até 30 dias da nomeação (admitida por procuração); exercício em até 15 dias da posse; estágio probatório de 3 anos.", b: "Art. 41, CF; Lei nº 8.112/90" },
  { id: "est-agentes-publicos-08", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Como fica o direito de greve do servidor público segundo o STF?", v: "Aplica-se a lei de greve do setor privado enquanto não houver lei específica; o servidor em estágio probatório pode aderir. Os dias parados são descontados, salvo se a greve foi causada por conduta ilícita do poder público, como atraso de salários.", b: "Art. 37, VII, CF", p: "Policiais civis e servidores que atuam diretamente na segurança pública não podem fazer greve." },
  { id: "est-agentes-publicos-09", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Quando a absolvição penal afasta a responsabilidade administrativa do servidor?", v: "Só quando nega a existência do fato ou a autoria. Absolvição por falta de provas ou prescrição penal não impede a punição administrativa, pela independência das instâncias.", b: "Art. 126, Lei nº 8.112/90" },
  { id: "est-agentes-publicos-10", d: "Direito Administrativo", r: "E", t: "Agentes públicos", f: "Quais são os prazos e a composição do PAD sumário e do ordinário?", v: "Sumário (acumulação ilegal, abandono de cargo e inassiduidade habitual): comissão de 2 servidores estáveis, 30 dias prorrogáveis por 15. Ordinário: comissão de 3 servidores estáveis, 60 dias prorrogáveis por 60. O excesso de prazo só anula se houver prejuízo à defesa.", b: "Arts. 133 e 149, Lei nº 8.112/90; Súmula 592, STJ", p: "A falta de advogado no PAD não ofende a Constituição (Súmula Vinculante 5)." },
  // Ética Profissional · Processo disciplinar
  { id: "est-processo-disciplinar-01", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Qual órgão da OAB tem competência para punir disciplinarmente o advogado?", v: "Em regra, o Conselho Seccional da base territorial onde ocorreu a infração, cabendo ao seu Tribunal de Ética e Disciplina o julgamento. A exceção é a falta cometida perante o Conselho Federal.", b: null, p: "A jurisdição disciplinar não exclui a comum, e o processo disciplinar tramita em sigilo." },
  { id: "est-processo-disciplinar-02", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Como pode ser instaurado o processo disciplinar?", v: "De ofício, quando o fato chega por fonte idônea ou comunicação de autoridade, ou por representação de qualquer autoridade ou interessado, dirigida ao Presidente do Conselho Seccional ou da Subseção, por escrito ou verbalmente (reduzida a termo).", b: null },
  { id: "est-processo-disciplinar-03", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Qual o prazo do relator para o parecer inicial e o que ocorre se ele não cumprir?", v: "O relator, sorteado, tem 30 dias para propor a instauração ou o arquivamento liminar da representação. Se perder o prazo, o processo é redistribuído, com o mesmo prazo.", b: null },
  { id: "est-processo-disciplinar-04", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Qual o prazo da defesa prévia e o que acontece se o representado não for encontrado ou for revel?", v: "A defesa prévia é apresentada em 15 dias da notificação, prorrogáveis por motivo relevante, com documentos e até 5 testemunhas. Não encontrado ou revel, o representado recebe defensor dativo.", b: null },
  { id: "est-processo-disciplinar-05", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Como funcionam as razões finais e a sustentação oral no processo disciplinar?", v: "Encerrada a instrução, há prazo sucessivo de 15 dias para razões finais, primeiro do representante e depois do representado. No julgamento, cada um tem 15 minutos de sustentação oral, na mesma ordem.", b: null, p: "O relator do voto no julgamento é outro, sorteado pelo Presidente do TED, diferente do relator da instrução." },
  { id: "est-processo-disciplinar-06", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Qual o prazo e o efeito dos recursos nos processos da OAB?", v: "Todos os recursos têm prazo de 15 dias, contados do primeiro dia útil após a publicação ou o recebimento da notificação, e efeito suspensivo, salvo em eleições, suspensão preventiva decidida pelo TED e cancelamento de inscrição obtida com prova falsa.", b: null },
  { id: "est-processo-disciplinar-07", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Para onde se recorre das decisões do TED e das decisões definitivas do Conselho Seccional?", v: "Das decisões do TED, ao Conselho Seccional. Das decisões definitivas do Conselho Seccional, ao Conselho Federal, quando não unânimes ou, sendo unânimes, quando contrariarem o Estatuto, o Regulamento Geral, o CED, os Provimentos ou decisão do CFOAB ou de outro Seccional.", b: null },
  { id: "est-processo-disciplinar-08", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Quais os requisitos da suspensão preventiva do advogado?", v: "Medida cautelar decretada pelo TED do Conselho da inscrição principal, em caso de repercussão prejudicial à dignidade da advocacia, após ouvir o acusado em sessão especial. O processo deve terminar em no máximo 90 dias, e o recurso contra a decisão não tem efeito suspensivo.", b: null, p: "Não se confunde com a sanção disciplinar de suspensão, aplicada só após o julgamento da infração." },
  { id: "est-processo-disciplinar-09", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Em que hipóteses cabe revisão do processo disciplinar e ela suspende a execução da pena?", v: "Só por erro de julgamento ou condenação baseada em prova falsa, a pedido do advogado punido, perante o órgão que proferiu a condenação final. Em regra não tem efeito suspensivo, salvo tutela cautelar concedida pelo relator.", b: null },
  { id: "est-processo-disciplinar-10", d: "Ética Profissional", r: "E", t: "Processo disciplinar", f: "Quando o advogado punido pode pedir reabilitação?", v: "Um ano após cumprir a sanção disciplinar, com provas efetivas de bom comportamento, perante o Conselho Seccional que aplicou a pena. Se a sanção decorreu de crime, exige-se também a reabilitação criminal.", b: null },
  // Direito Constitucional · Controle concentrado
  { id: "est-controle-concentrado-01", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "O que pode ser objeto de ADI e lei de efeitos concretos pode ser impugnada?", v: "Lei ou ato normativo federal ou estadual editado depois da CF/88, dotado de generalidade e abstração. Atos de efeitos concretos em regra não, mas o STF admite ADI contra lei em sentido estrito de efeitos concretos, aprovada pelo Legislativo e sancionada pelo Executivo.", b: "Art. 102, I, a, CF" },
  { id: "est-controle-concentrado-02", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Quem são os legitimados à ADI e à ADC e quais precisam demonstrar pertinência temática?", v: "Os do art. 103 da CF. O STF os divide em universais, que podem impugnar qualquer matéria, e especiais, que só podem propor a ação quando houver pertinência temática entre o ato impugnado e suas funções.", b: "Art. 103, CF", p: "Rol taxativo: Vice-Presidente e Vice-Governador só se estiverem no exercício do cargo de titular. Partido precisa de ao menos um parlamentar no Congresso." },
  { id: "est-controle-concentrado-03", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Cabe intervenção de terceiros ou desistência em ADI e ADC?", v: "Não. São processos objetivos, sem partes: não se admite intervenção de terceiros nem desistência, mas é admitida a manifestação de amicus curiae.", b: "Art. 7º, § 2º, e art. 16 da Lei 9.868/99" },
  { id: "est-controle-concentrado-04", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Qual o quórum e os efeitos da medida cautelar em ADI?", v: "Maioria absoluta (6 votos), com pelo menos 8 ministros presentes. Em regra tem efeitos ex nunc (ex tunc só se o STF disser expressamente), eficácia erga omnes, efeito vinculante e torna aplicável a legislação anterior (efeito repristinatório).", b: null },
  { id: "est-controle-concentrado-05", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "O efeito vinculante da decisão em ADI alcança o próprio STF e o Poder Legislativo?", v: "Não. Vincula os demais órgãos do Judiciário e a Administração direta e indireta de todas as esferas, mas o STF pode rever seu entendimento e o Legislativo pode editar nova lei de igual conteúdo.", b: null },
  { id: "est-controle-concentrado-06", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Na ADO, o STF pode editar a norma que falta? Quais as consequências da decisão?", v: "Não, pela separação de poderes. Se a omissão é de um Poder, dá ciência para que adote as providências; se é de órgão administrativo, fixa 30 dias ou outro prazo razoável para que ele as adote.", b: null },
  { id: "est-controle-concentrado-07", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Qual o objeto da ADC e qual requisito específico ela exige?", v: "Só lei ou ato normativo federal. Exige controvérsia judicial relevante que ponha em risco a presunção de constitucionalidade; divergência apenas doutrinária não basta.", b: null },
  { id: "est-controle-concentrado-08", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Em que hipóteses cabe ADPF e qual sua característica principal?", v: "É subsidiária: só cabe se não houver outro meio eficaz. Serve, por exemplo, para direito pré-constitucional, lei municipal em face da CF, interpretações judiciais que violem preceito fundamental e norma pós-constitucional já revogada ou de efeitos exauridos.", b: "Art. 102, § 1º, CF" },
  { id: "est-controle-concentrado-09", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "ADI proposta contra lei anterior à CF/88 pode ser conhecida como ADPF pela fungibilidade?", v: "Não. O STF considera erro grosseiro usar ADI contra direito pré-constitucional, o que impede a conversão. Fora do erro grosseiro, ADI e ADPF são fungíveis.", b: null },
  { id: "est-controle-concentrado-10", d: "Direito Constitucional", r: "E", t: "Controle concentrado", f: "Tribunal de Justiça pode julgar ADI estadual tendo como parâmetro a Constituição Federal?", v: "Em regra o parâmetro é a Constituição Estadual, mas o STF admite o uso da CF quando se tratar de norma de reprodução obrigatória pelos Estados. Nesse caso cabe recurso extraordinário ao STF.", b: "Art. 125, § 2º, CF; STF, ADI 5647", p: "A Constituição Estadual não pode atribuir a legitimidade para a ação a um único órgão." },
  // Direito Processual do Trabalho · Recursos trabalhistas
  { id: "est-recursos-trabalhistas-01", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "As decisões interlocutórias são recorríveis de imediato na Justiça do Trabalho?", v: "Em regra não. As exceções são a decisão de TRT contrária a súmula ou OJ do TST, a decisão impugnável por recurso para o mesmo tribunal e a que acolhe incompetência territorial remetendo os autos a TRT distinto.", b: "Art. 893, § 1º, CLT; Súmula 214 do TST" },
  { id: "est-recursos-trabalhistas-02", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quais os efeitos dos recursos trabalhistas em regra e como obter efeito suspensivo?", v: "Têm efeito meramente devolutivo, permitindo a execução provisória até a penhora. O efeito suspensivo ao recurso ordinário pode ser pedido por simples requerimento ao tribunal, ao relator ou ao presidente ou vice do tribunal recorrido.", b: "Art. 899 da CLT; Súmula 414, I, do TST" },
  { id: "est-recursos-trabalhistas-03", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quais os prazos recursais no processo do trabalho?", v: "Regra: 8 dias para recorrer e para contrarrazoar. Embargos de declaração: 5 dias. Recurso extraordinário: 15 dias. Entes públicos, Ministério Público e Defensoria têm prazo em dobro para recorrer.", b: "Art. 6º da Lei 5.584/70; art. 897-A da CLT" },
  { id: "est-recursos-trabalhistas-04", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quem deve fazer o depósito recursal e quando?", v: "Só o reclamado, nunca o empregado, e apenas quando houver condenação em pecúnia. Deve ser feito e comprovado dentro do prazo do recurso, ainda que o recurso seja interposto antes do fim do prazo.", b: "Súmula 245 do TST", p: "No agravo de instrumento, o depósito é de 50% do valor do depósito do recurso que se quer destrancar." },
  { id: "est-recursos-trabalhistas-05", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "O que acontece se as custas ou o depósito recursal forem recolhidos a menor?", v: "Só haverá deserção se, intimado a complementar no prazo de 5 dias, o recorrente não comprovar o valor devido. Atingido o valor da condenação, nenhum novo depósito é exigido.", b: "OJ 140 da SDI-1 do TST; Súmula 128, I, do TST" },
  { id: "est-recursos-trabalhistas-06", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quando cabe recurso ordinário e quem o julga?", v: "Das decisões definitivas ou terminativas das Varas (julgado pelo TRT) e dos TRTs em processos de competência originária (julgado pelo TST), no prazo de 8 dias.", b: "Art. 895 da CLT", p: "No sumaríssimo o recurso ordinário não tem revisor e o relator deve liberá-lo em até 10 dias." },
  { id: "est-recursos-trabalhistas-07", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quais as hipóteses de cabimento do recurso de revista?", v: "Contra acórdão de TRT em recurso ordinário em dissídio individual, por divergência jurisprudencial (outro TRT, SDI do TST, súmula do TST ou súmula vinculante) ou por violação literal de lei federal ou afronta direta e literal à Constituição. Exige prequestionamento e transcendência.", b: "Art. 896 da CLT", p: "Na execução, só por ofensa direta e literal à Constituição; no sumaríssimo, só por violação direta da CF ou contrariedade a súmula do TST, nunca a OJ (Súmula 442 do TST)." },
  { id: "est-recursos-trabalhistas-08", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Quais os indicadores de transcendência do recurso de revista?", v: "Econômica (elevado valor da causa), política (desrespeito à jurisprudência sumulada do TST ou do STF), social (reclamante postulando direito social constitucional) e jurídica (questão nova sobre interpretação da legislação trabalhista).", b: null, p: "A transcendência é examinada só pelo TST, não pela Presidência do TRT no juízo de admissibilidade." },
  { id: "est-recursos-trabalhistas-09", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Os embargos de declaração trabalhistas podem ter efeito modificativo e qual seu efeito sobre o prazo de outros recursos?", v: "Podem, nos casos de omissão, contradição e manifesto equívoco no exame dos pressupostos extrínsecos, desde que a parte contrária seja ouvida em 5 dias. Interrompem o prazo dos demais recursos, salvo se intempestivos, com representação irregular ou sem assinatura.", b: "Art. 897-A, caput e § 2º, CLT; OJ 142 da SDI-1 do TST" },
  { id: "est-recursos-trabalhistas-10", d: "Direito Processual do Trabalho", r: "E", t: "Recursos trabalhistas", f: "Qual a função do agravo de instrumento e do agravo de petição no processo do trabalho?", v: "Agravo de instrumento: destrancar recurso cuja admissão foi negada. Agravo de petição: impugnar decisões proferidas na execução, sem preparo. Ambos em 8 dias.", b: "Art. 897, a e b, CLT", p: "Diferente do processo civil, o agravo de instrumento trabalhista não serve para atacar decisões interlocutórias." },
  // Direito do Trabalho · Sistema remuneratório
  { id: "est-sistema-remuneratorio-01", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Qual a diferença entre remuneração e salário, e onde entra a gorjeta?", v: "Salário é o que o empregador paga pelo contrato; remuneração é o salário somado às gorjetas, que vêm de terceiros. Gorjeta inclui tanto a dada espontaneamente pelo cliente quanto a taxa de serviço cobrada pela empresa e distribuída aos empregados.", b: "Art. 457, caput e § 3º, CLT" },
  { id: "est-sistema-remuneratorio-02", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Em quais verbas as gorjetas refletem e em quais não?", v: "Refletem em férias + 1/3, 13º salário e FGTS. Não refletem em aviso-prévio, adicional noturno, horas extras e descanso semanal remunerado, que são calculados sobre o salário.", b: "Súmula 354, TST" },
  { id: "est-sistema-remuneratorio-03", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "O que é salário complessivo e ele é permitido?", v: "É o pagamento de um valor único que mistura várias parcelas sem discriminá-las (ex.: horas extras, adicional noturno e anuênio juntos). É proibido, pois cada verba deve ser paga de forma especificada.", b: null },
  { id: "est-sistema-remuneratorio-04", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Quais parcelas não têm natureza salarial após a Reforma Trabalhista?", v: "Ajuda de custo, diárias para viagem (sem o antigo limite de 50%), prêmios, abonos e auxílio-alimentação não pago em dinheiro, ainda que habituais. Prêmios são liberalidades por desempenho superior ao esperado.", b: "Art. 457, §§ 2º e 4º, CLT", p: "Auxílio-alimentação pago em dinheiro tem natureza salarial." },
  { id: "est-sistema-remuneratorio-05", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "O salário mínimo pode ser pago proporcionalmente à jornada reduzida?", v: "Sim, na iniciativa privada é lícito pagar o mínimo proporcional às horas trabalhadas. Já o empregado público da Administração direta, autárquica e fundacional não pode receber menos que o mínimo, mesmo em jornada reduzida.", b: "OJ 358 da SDI-1, TST; Tema 900, STF" },
  { id: "est-sistema-remuneratorio-06", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Quando uma utilidade fornecida pelo empregador é salário in natura?", v: "Quando é habitual e tem função retributiva, ou seja, é dada pelo trabalho, e não para o trabalho. Pelo menos 30% do salário deve ser pago em dinheiro. Não são salário, por exemplo, uniformes e equipamentos, educação, transporte ao trabalho, plano de saúde, seguro de vida, previdência privada e vale-cultura.", b: "Art. 458, § 2º, CLT" },
  { id: "est-sistema-remuneratorio-07", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Qual a periodicidade máxima e o prazo de pagamento do salário mensal?", v: "O salário não pode ser estipulado por período superior a 1 mês (exceto comissões, percentagens e gratificações) e, se mensal, deve ser pago até o 5º dia útil do mês seguinte. Alterar a data dentro desse limite não é alteração lesiva.", b: "Art. 459, caput e § 1º, CLT; OJ 159 da SDI-1, TST" },
  { id: "est-sistema-remuneratorio-08", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Quando o empregador pode descontar do salário o dano causado pelo empregado e os planos de saúde?", v: "Dano doloso pode ser descontado sem previsão contratual; dano culposo só com previsão em lei ou no contrato. Descontos para planos de saúde, seguro ou previdência privada exigem autorização prévia e escrita, sem vício de consentimento.", b: "Art. 462, § 1º, CLT; Súmula 342, TST" },
  { id: "est-sistema-remuneratorio-09", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "O que acontece se o empregador não paga as verbas rescisórias incontroversas na primeira audiência?", v: "Deve pagar a parte não controvertida na data em que comparecer à Justiça do Trabalho; se não pagar, esse valor é acrescido de 50%.", b: "Art. 467, CLT" },
  { id: "est-sistema-remuneratorio-10", d: "Direito do Trabalho", r: "E", t: "Sistema remuneratório", f: "Quais os requisitos da equiparação salarial?", v: "Mesmo empregador, mesmo estabelecimento, função idêntica, trabalho de igual valor, diferença de tempo de serviço não superior a 4 anos e de tempo na função não superior a 2 anos, e inexistência de quadro de carreira ou plano de cargos e salários.", b: "Art. 461, CLT", p: "Não se admite equiparação com paradigma remoto (em cadeia) (art. 461, § 5º)." },
  // Direito Processual Civil · Cumprimento de sentença
  { id: "est-cumprimento-de-sentenca-01", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Como o devedor é intimado para o cumprimento de sentença se o requerimento vier mais de 1 ano após o trânsito em julgado?", v: "A intimação deixa de ser feita na pessoa do advogado e passa a ser enviada ao próprio devedor, por carta com aviso de recebimento.", b: null, p: "Regra geral: intimação pelo Diário da Justiça na pessoa do advogado; por carta quando assistido pela Defensoria ou sem procurador nos autos." },
  { id: "est-cumprimento-de-sentenca-02", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Quais títulos judiciais exigem citação do devedor, e não simples intimação, para cumprimento?", v: "Sentença penal condenatória, sentença arbitral e decisão estrangeira homologada pelo STJ (ou interlocutória estrangeira com exequatur): o devedor é citado para cumprimento ou liquidação em 15 dias.", b: null },
  { id: "est-cumprimento-de-sentenca-03", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Quando o credor pode levar a sentença a protesto?", v: "Após o trânsito em julgado e o decurso do prazo de 15 dias para pagamento voluntário sem que o devedor pague. O credor obtém certidão do teor da decisão, fornecida em 3 dias.", b: null },
  { id: "est-cumprimento-de-sentenca-04", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Quem responde pelos danos se a sentença executada provisoriamente for reformada?", v: "O exequente, de forma objetiva. O levantamento de dinheiro ou a alienação de bens no cumprimento provisório exigem caução idônea.", b: null, p: "A reforma não desfaz a alienação de propriedade já realizada; resolve-se em reparação dos prejuízos ao executado." },
  { id: "est-cumprimento-de-sentenca-05", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Em que hipóteses se dispensa a caução no cumprimento provisório?", v: "Crédito de natureza alimentar, credor em situação de necessidade, pendência de agravo contra a inadmissão de RE ou REsp e sentença conforme súmula do STF ou STJ ou acórdão em casos repetitivos.", b: null, p: "A caução é mantida se a dispensa puder causar risco manifesto de dano grave de difícil ou incerta reparação." },
  { id: "est-cumprimento-de-sentenca-06", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Qual a consequência de o executado não pagar a quantia certa em 15 dias?", v: "Incidem multa de 10% e honorários advocatícios de 10%, e expede-se mandado de penhora e avaliação. A mesma regra vale para o cumprimento provisório.", b: null },
  { id: "est-cumprimento-de-sentenca-07", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Quando começa o prazo da impugnação ao cumprimento de sentença e ela suspende a execução?", v: "Começa automaticamente ao fim dos 15 dias para pagamento, sem penhora nem nova intimação. Em regra não tem efeito suspensivo, que depende de requerimento, garantia do juízo e risco de dano grave de difícil ou incerta reparação.", b: null },
  { id: "est-cumprimento-de-sentenca-08", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "O que pode fazer o devedor de alimentos intimado a pagar e qual o débito que autoriza a prisão civil?", v: "Em 3 dias, pagar, provar que pagou ou justificar a impossibilidade. A prisão, de 1 a 3 meses em regime fechado, abrange as 3 prestações anteriores ao ajuizamento e as que vencerem no curso do processo.", b: null, p: "Cumprir a prisão não exime do pagamento das prestações; e, aqui, o juiz manda protestar a decisão de ofício." },
  { id: "est-cumprimento-de-sentenca-09", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Como funciona o cumprimento de sentença contra a Fazenda Pública?", v: "A Fazenda é intimada para impugnar em 30 dias, nos próprios autos. Não incide a multa de 10% por falta de pagamento voluntário. Sem impugnação ou rejeitada, expede-se precatório ou requisição de pequeno valor.", b: null },
  { id: "est-cumprimento-de-sentenca-10", d: "Direito Processual Civil", r: "E", t: "Cumprimento de sentença", f: "Quando a obrigação de fazer ou não fazer pode ser convertida em perdas e danos?", v: "Só se o autor requerer ou se forem impossíveis a tutela específica e o resultado prático equivalente. Nos vícios redibitórios, empreitada, seguro e responsabilidade solidária ou subsidiária, o juiz dá antes ao devedor a chance de cumprir a tutela específica.", b: "Art. 499 do CPC", p: "Descumprir injustificadamente a ordem sujeita o executado às penas de litigância de má-fé, sem prejuízo do crime de desobediência." },
  // Direito Processual Civil · Recursos
  { id: "est-recursos-11", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Qual o prazo dos recursos no CPC e qual a exceção?", v: "15 dias úteis para interpor e para responder a todos os recursos, salvo os embargos de declaração, cujo prazo é de 5 dias.", b: "Art. 1.003, § 5º, CPC", p: "No recurso enviado pelo correio, vale a data da postagem para aferir a tempestividade (art. 1.003, § 4º)." },
  { id: "est-recursos-12", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Qual a diferença entre não comprovar o preparo e recolhê-lo a menor?", v: "Sem comprovação do preparo na interposição, o recorrente é intimado a recolhê-lo em dobro, sob pena de deserção. Se recolhido a menor, é intimado a complementar em 5 dias.", b: "Art. 1.007, §§ 2º e 4º, CPC", p: "No recolhimento em dobro, se houver nova insuficiência, é vedada a complementação (art. 1.007, § 5º)." },
  { id: "est-recursos-13", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Quem é dispensado de preparo e quais recursos independem dele?", v: "Dispensados: Ministério Público, União, Estados, DF, Municípios, suas autarquias e quem goza de isenção legal. Independem de preparo os embargos de declaração, o agravo em REsp e RE, os embargos infringentes da LEF e os recursos do ECA.", b: "Art. 1.007, § 1º, CPC", p: "Em autos eletrônicos não há porte de remessa e retorno." },
  { id: "est-recursos-14", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Em quais recursos cabe a forma adesiva no CPC e quando ela não é conhecida?", v: "Na apelação, no recurso especial e no recurso extraordinário, no prazo das contrarrazões. Não é conhecido se houver desistência do recurso principal ou se este for inadmissível.", b: null },
  { id: "est-recursos-15", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "A apelação tem efeito suspensivo? Cite exceções.", v: "Em regra sim. Não tem quando a sentença homologa divisão ou demarcação, condena a alimentos, extingue ou rejeita embargos do executado, julga procedente a instituição de arbitragem, confirma, concede ou revoga tutela provisória ou decreta a interdição.", b: null, p: "Nessas exceções, o apelante pode pedir efeito suspensivo, mostrando probabilidade de provimento ou fundamentação relevante com risco de dano grave." },
  { id: "est-recursos-16", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Quando o tribunal pode julgar o mérito diretamente na apelação (causa madura)?", v: "Estando o processo pronto para julgamento, ao reformar sentença sem resolução do mérito, anular sentença incongruente com o pedido ou a causa de pedir, suprir omissão sobre um pedido, anular sentença sem fundamentação ou reformar sentença que reconheceu prescrição ou decadência.", b: null },
  { id: "est-recursos-17", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "O rol de cabimento do agravo de instrumento é taxativo? Cite hipóteses.", v: "Sim. Cabe contra interlocutórias sobre tutela provisória, mérito, rejeição da convenção de arbitragem, desconsideração da personalidade jurídica, gratuidade negada ou revogada, exclusão de litisconsorte, intervenção de terceiros, efeito suspensivo dos embargos à execução e redistribuição do ônus da prova, entre outras previstas em lei.", b: null, p: "Também cabe contra qualquer interlocutória na liquidação, no cumprimento de sentença, na execução e no inventário." },
  { id: "est-recursos-18", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Qual a multa do agravo interno manifestamente inadmissível e quando não cabe agravo em REsp ou RE?", v: "Agravo interno declarado manifestamente inadmissível ou improcedente por unanimidade gera multa de 1% a 5% do valor atualizado da causa. O agravo em REsp ou RE não cabe se a inadmissão se fundar em repercussão geral ou recursos repetitivos.", b: null },
  { id: "est-recursos-19", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Quais as multas por embargos de declaração protelatórios?", v: "Até 2% do valor atualizado da causa; na reiteração, até 10%, e qualquer recurso passa a depender do depósito da multa (Fazenda Pública e beneficiário da gratuidade pagam ao final). Após dois embargos protelatórios, novos não são admitidos.", b: null, p: "Os embargos interrompem o prazo dos demais recursos, mas os intempestivos não." },
  { id: "est-recursos-20", d: "Direito Processual Civil", r: "E", t: "Recursos", f: "Interpostos RE e REsp contra a mesma decisão, qual é julgado primeiro?", v: "Em regra o REsp, no STJ; depois, se não prejudicado, o RE vai ao STF. O relator no STJ pode remeter antes ao STF se considerar a questão constitucional prejudicial. A repercussão geral é exigida só no RE.", b: null, p: "Há repercussão geral presumida quando o acórdão contraria súmula do STF ou reconhece a inconstitucionalidade de tratado ou lei federal." },
  // Direito Processual Civil · Execução
  { id: "est-execucao-01", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Quais são os atos atentatórios à dignidade da justiça na execução e a quem vai a multa?", v: "Fraude à execução, oposição maliciosa com ardis, embaraço à penhora, resistência injustificada a ordens judiciais e não indicar bens penhoráveis quando intimado. A multa, de até 20% do débito atualizado, reverte ao credor e é cobrada no próprio processo.", b: null, p: "Diferente do ato atentatório do art. 77 (fase de conhecimento), aqui a multa vai para o exequente." },
  { id: "est-execucao-02", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Onde pode ser proposta a execução de título extrajudicial?", v: "À escolha do exequente: no domicílio do executado, no foro de eleição do título ou onde estiverem os bens. Também no lugar do ato ou fato que originou o título; com domicílio incerto, onde o executado for encontrado ou no domicílio do exequente.", b: null },
  { id: "est-execucao-03", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Documento particular serve como título executivo extrajudicial?", v: "Sim, se assinado pelo devedor e por duas testemunhas. Escritura ou documento público assinado pelo devedor também é título, assim como a transação referendada por MP, Defensoria, Advocacia Pública, advogados dos transatores ou conciliador/mediador credenciado.", b: null },
  { id: "est-execucao-04", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Título executivo extrajudicial estrangeiro precisa de homologação?", v: "Não. Basta que cumpra os requisitos de formação da lei do lugar onde foi celebrado e indique o Brasil como lugar de cumprimento da obrigação.", b: null, p: "A sentença estrangeira depende de homologação; o título extrajudicial estrangeiro, não." },
  { id: "est-execucao-05", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Quando a alienação de bem configura fraude à execução e o que o juiz deve fazer antes de declará-la?", v: "Por exemplo, com ação real ou reipersecutória averbada no registro, execução ou constrição averbada, ou ação capaz de levar o devedor à insolvência em curso ao tempo da alienação; não se exige prova da intenção de fraudar. Antes de declarar, o juiz intima o terceiro adquirente, que pode opor embargos de terceiro em 15 dias.", b: null },
  { id: "est-execucao-06", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Em que casos a execução é nula e como o executado pode alegar isso?", v: "Se o título não corresponder a obrigação certa, líquida e exigível, se o executado não for regularmente citado ou se a execução começar antes da condição ou do termo. O juiz pronuncia a nulidade de ofício ou a pedido, sem necessidade de embargos.", b: "art. 803 do CPC" },
  { id: "est-execucao-07", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Quais os requisitos da exceção de pré-executividade segundo o STJ?", v: "Matéria que o juiz pode conhecer de ofício e que não exija dilação probatória, com prova pré-constituída quando a questão for de fato.", b: "Súmula 393 do STJ", p: "Rejeitada a exceção, não cabem honorários; acolhida com extinção da execução, cabem honorários ao executado e o recurso é apelação." },
  { id: "est-execucao-08", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Como funciona a execução de título extrajudicial contra a Fazenda Pública?", v: "É cabível (Súmula 279 do STJ). A Fazenda é citada para opor embargos em 30 dias; rejeitados ou não opostos, expede-se precatório ou RPV.", b: "Súmula 279 do STJ", p: "Empresas públicas e sociedades de economia mista não entram no conceito de Fazenda Pública." },
  { id: "est-execucao-09", d: "Direito Processual Civil", r: "E", t: "Execução", f: "Na execução de alimentos, qual débito autoriza a prisão do devedor?", v: "O débito atual: as três prestações vencidas antes do ajuizamento e as que vencerem no curso do processo. Citado, o devedor tem 3 dias para pagar, provar o pagamento ou justificar a impossibilidade; débito antigo segue o rito da quantia certa.", b: null },
  { id: "est-execucao-10", d: "Direito Processual Civil", r: "E", t: "Execução", f: "O que acontece quando o executado não é encontrado ou não tem bens penhoráveis?", v: "A execução é suspensa por 1 ano, período em que a prescrição também fica suspensa; depois ela volta a correr (prescrição intercorrente). Antes de reconhecê-la, o juiz ouve as partes em 15 dias e extingue a execução sem ônus.", b: null },
  // Direito Civil · Família: direito conjugal patrimonial
  { id: "est-familia-direito-conjugal-patrimonial-01", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Que atos qualquer cônjuge pode praticar livremente, seja qual for o regime de bens?", v: "Entre outros: atos de disposição e administração necessários à profissão, administração dos bens próprios e compra, mesmo a crédito, do necessário à economia doméstica, além dos empréstimos para adquiri-lo.", b: null, p: "As dívidas com a economia doméstica obrigam solidariamente ambos os cônjuges." },
  { id: "est-familia-direito-conjugal-patrimonial-02", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Quando o pacto antenupcial é obrigatório e quando é nulo ou ineficaz?", v: "É exigido para qualquer regime diferente da comunhão parcial. É nulo se não for feito por escritura pública ou se contrariar disposição absoluta de lei, e ineficaz se o casamento não se realizar.", b: null },
  { id: "est-familia-direito-conjugal-patrimonial-03", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Os cônjuges podem mudar o regime de bens durante o casamento? E se nada convencionarem antes?", v: "Podem alterá-lo mediante autorização judicial. Sem convenção, vale a comunhão parcial, regime supletivo que também se aplica à união estável sem contrato escrito.", b: null },
  { id: "est-familia-direito-conjugal-patrimonial-04", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Na comunhão parcial, quais bens formam o patrimônio comum?", v: "Em regra, os adquiridos a título oneroso na constância do casamento; os anteriores à união ficam particulares de cada cônjuge.", b: "Art. 1.660 do CC", p: "Bens móveis presumem-se adquiridos na constância do casamento, salvo prova de aquisição anterior." },
  { id: "est-familia-direito-conjugal-patrimonial-05", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Na comunhão parcial, quem administra os bens particulares e o que exige anuência de ambos?", v: "Os bens particulares são administrados e dispostos pelo cônjuge proprietário, salvo pacto em contrário. Atos gratuitos que cedam o uso ou gozo de bens comuns exigem anuência dos dois.", b: null },
  { id: "est-familia-direito-conjugal-patrimonial-06", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Quais bens ficam fora da comunhão universal?", v: "Bens doados ou herdados com cláusula de incomunicabilidade e os sub-rogados, bens gravados de fideicomisso antes da condição, dívidas anteriores ao casamento (salvo aprestos ou proveito comum), doações antenupciais com incomunicabilidade, bens de uso pessoal, livros e instrumentos de profissão, proventos do trabalho pessoal e pensões.", b: null },
  { id: "est-familia-direito-conjugal-patrimonial-07", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Em que casos o regime da separação de bens é obrigatório?", v: "Para quem casa sem observar as causas suspensivas (ex.: viúvo com filho do falecido antes do inventário e partilha, divorciado antes da partilha), para todos que dependem de suprimento judicial para casar e para as demais hipóteses previstas em lei.", b: null },
  { id: "est-familia-direito-conjugal-patrimonial-08", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Na separação legal (obrigatória) de bens, os bens adquiridos durante o casamento se comunicam?", v: "Comunicam-se os adquiridos na constância do casamento por esforço comum.", b: "Súmula 377 do STF" },
  { id: "est-familia-direito-conjugal-patrimonial-09", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Como funciona o regime de participação final nos aquestos?", v: "Durante o casamento funciona como separação: cada um tem patrimônio próprio. Na dissolução, cada cônjuge tem direito à metade dos bens adquiridos pelo casal a título oneroso na constância do casamento.", b: null, p: "O pacto pode prever a livre disposição dos imóveis, desde que particulares." },
  { id: "est-familia-direito-conjugal-patrimonial-10", d: "Direito Civil", r: "E", t: "Família: direito conjugal patrimonial", f: "Na participação final nos aquestos, qual data define o montante dos aquestos em caso de separação ou divórcio?", v: "A data em que cessou a convivência, e não a da separação ou do divórcio. Doações feitas sem autorização do outro cônjuge entram no cálculo, e a dívida de um paga com bens do outro é imputada atualizada à meação do devedor.", b: null },
  // Direito Civil · Direito das sucessões
  { id: "est-direito-das-sucessoes-01", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Quem são os herdeiros necessários e quanto da herança o testador pode dispor havendo algum deles?", v: "Descendentes, ascendentes e cônjuge. Havendo herdeiro necessário, o testador só dispõe da metade; a outra metade é a legítima.", b: null, p: "Colaterais, inclusive irmãos, não são herdeiros necessários: basta testar sem contemplá-los para excluí-los." },
  { id: "est-direito-das-sucessoes-02", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Qual o alcance da cláusula de inalienabilidade imposta em testamento?", v: "Depende de justa causa declarada no testamento. A inalienabilidade implica automaticamente impenhorabilidade e incomunicabilidade, mas a simples incomunicabilidade não torna o bem inalienável nem impenhorável.", b: null },
  { id: "est-direito-das-sucessoes-03", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Qual a forma exigida para a renúncia à herança e ela pode ser parcial?", v: "A renúncia deve ser expressa, por instrumento público ou termo judicial; é irrevogável e não pode ser parcial, sob condição ou a termo. É possível, porém, aceitar o legado e renunciar à herança, ou o contrário.", b: null, p: "Renúncia que prejudica credores do herdeiro é ineficaz: com autorização do juiz, eles podem aceitar em nome do renunciante." },
  { id: "est-direito-das-sucessoes-04", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Para onde vai a parte do herdeiro que renuncia?", v: "Acresce à dos outros herdeiros da mesma classe; se ele era o único da classe, passa à classe seguinte. Os filhos do renunciante só herdam, por direito próprio e por cabeça, se ele for o único da classe ou se todos da classe renunciarem.", b: null, p: "Não há representação de herdeiro renunciante." },
  { id: "est-direito-das-sucessoes-05", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Quais os prazos e os efeitos da exclusão por indignidade?", v: "Depende de sentença, em ação proposta em 4 anos da abertura da sucessão. Os efeitos são pessoais: os descendentes do excluído herdam como se ele tivesse morrido antes do autor da herança.", b: null },
  { id: "est-direito-das-sucessoes-06", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "O cônjuge herda em concorrência com descendentes em quais regimes de bens?", v: "Herda na separação convencional e na comunhão parcial quando o falecido deixou bens particulares (herda só sobre eles). Não herda na comunhão universal, na separação obrigatória e na comunhão parcial sem bens particulares.", b: null, p: "Após o STF declarar inconstitucional o art. 1.790 do CC, companheiro e cônjuge seguem as mesmas regras sucessórias." },
  { id: "est-direito-das-sucessoes-07", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Qual a quota do cônjuge em concorrência com descendentes e com ascendentes?", v: "Com descendentes, quinhão igual ao de cada um, nunca menos de 1/4 se for ascendente deles. Com ascendentes, 1/3 se concorrer com pai e mãe do falecido, ou 1/2 se houver só um deles ou ascendentes de grau maior.", b: null },
  { id: "est-direito-das-sucessoes-08", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Como funcionam a representação e a sucessão de irmãos bilaterais e unilaterais?", v: "Representação só existe na linha reta descendente e, na colateral, a favor de filhos de irmãos pré-mortos. Concorrendo irmãos bilaterais e unilaterais, cada unilateral recebe metade do que couber a cada bilateral.", b: null, p: "Sobrinhos e tios são colaterais de 3º grau, mas os sobrinhos têm preferência." },
  { id: "est-direito-das-sucessoes-09", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "A partir de que idade se pode testar e quais os prazos para impugnar o testamento?", v: "A partir dos 16 anos. O direito de impugnar a validade do testamento extingue-se em 5 anos do registro; a anulação por erro, dolo ou coação, em 4 anos da ciência do vício.", b: null, p: "É proibido o testamento conjuntivo (simultâneo, recíproco ou correspectivo)." },
  { id: "est-direito-das-sucessoes-10", d: "Direito Civil", r: "E", t: "Direito das sucessões", f: "Quem pode usar o testamento cerrado e quem só pode fazer testamento público?", v: "Não faz testamento cerrado quem não sabe ou não pode ler; o surdo-mudo pode, se o escrever todo e o assinar. Ao cego só se permite o testamento público, lido duas vezes em voz alta.", b: null },
  // Direito Processual do Trabalho · Execução no processo do trabalho
  { id: "est-execucao-no-processo-do-trabalho-01", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Quais são as formas de liquidação de sentença no processo do trabalho e quando se usa cada uma?", v: "Por cálculo, quando bastam operações aritméticas; por artigos, quando é preciso alegar e provar fato novo relativo ao valor; por arbitramento, quando é necessária prova pericial. Na liquidação não se pode modificar a sentença nem rediscutir a causa principal.", b: "Art. 879, caput e § 1º, CLT; arts. 509, II, e 510, CPC" },
  { id: "est-execucao-no-processo-do-trabalho-02", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Qual o prazo para impugnar a conta de liquidação e quando se pode atacar a sentença de liquidação?", v: "O juiz abre prazo comum de 8 dias para impugnação fundamentada, com indicação de itens e valores, sob pena de preclusão. A sentença de liquidação não é recorrível de imediato: só pode ser impugnada nos embargos à penhora, em 5 dias.", b: "Art. 879, CLT; art. 884, § 3º, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-03", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Quais títulos executivos extrajudiciais podem ser executados na Justiça do Trabalho?", v: "Termos de ajuste de conduta firmados perante o MPT e termos de conciliação firmados perante as Comissões de Conciliação Prévia, além de cheques e notas promissórias de conteúdo trabalhista. A execução cabe ao juiz que seria competente para o processo de conhecimento.", b: "Arts. 876 e 877-A, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-04", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Até onde vai a execução provisória no processo do trabalho?", v: "Até a penhora. Feita a penhora, a execução fica suspensa até o trânsito em julgado, sem expropriação dos bens.", b: "Art. 899, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-05", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "O juiz do trabalho pode iniciar a execução de ofício?", v: "Só quando as partes não estiverem representadas por advogado; caso contrário, a execução depende de iniciativa da parte.", b: "Art. 878, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-06", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "A execução pode ser direcionada a empresa do grupo econômico que não participou da fase de conhecimento?", v: "Não. O reclamante deve indicar já na inicial os corresponsáveis solidários. O redirecionamento a terceiro só é admitido, excepcionalmente, em sucessão empresarial e abuso da personalidade jurídica, pelo incidente de desconsideração.", b: "Tema 1232, STF; art. 855-A, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-07", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Como funciona o incidente de desconsideração da personalidade jurídica no processo do trabalho?", v: "Aplica-se o incidente do CPC, que suspende o processo, sem prejuízo de tutela cautelar. Da decisão, na fase de conhecimento não cabe recurso imediato; na execução cabe agravo de petição, independentemente de garantia do juízo. A Justiça do Trabalho adota a teoria menor: basta a insolvência da empresa.", b: "Art. 855-A, CLT; art. 28, § 5º, CDC" },
  { id: "est-execucao-no-processo-do-trabalho-08", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Quais os prazos do executado após a citação e para os embargos à execução?", v: "Citado, o executado tem 48 horas para pagar ou garantir a execução, sob pena de penhora. Garantido o juízo, tem 5 dias para embargos; a Fazenda Pública tem 30 dias e não precisa garantir.", b: "Arts. 880 e 884, CLT; Tema 137, STF", p: "Entidades filantrópicas e seus diretores também ficam dispensados da garantia do juízo para embargar." },
  { id: "est-execucao-no-processo-do-trabalho-09", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Quando a sentença trabalhista pode ser protestada ou gerar inscrição em cadastros de devedores?", v: "Só depois de transitada em julgado, passados 45 dias da citação do executado sem garantia do juízo.", b: "Art. 883-A, CLT" },
  { id: "est-execucao-no-processo-do-trabalho-10", d: "Direito Processual do Trabalho", r: "E", t: "Execução no processo do trabalho", f: "Qual o recurso cabível contra decisões na execução e qual o seu requisito específico?", v: "Agravo de petição, em 8 dias, sem preparo. O agravante deve delimitar justificadamente as matérias e os valores impugnados, sob pena de não conhecimento; a parte incontroversa pode ser executada de imediato.", b: "Art. 897, a, CLT", p: "Garantido o juízo, não se exige depósito para recorrer, salvo complementação se o débito aumentar (Súmula 128, II, TST)." },
  // Direito do Trabalho · Estabilidades
  { id: "est-estabilidades-01", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Como funcionava a estabilidade decenal e qual sua situação hoje?", v: "Após 10 anos na mesma empresa, o empregado só podia ser dispensado por falta grave ou força maior, apurada em inquérito judicial. A CF/88 tornou o FGTS obrigatório e extinguiu o regime, ressalvado o direito adquirido; hoje as estabilidades são provisórias.", b: "Arts. 492 a 500 da CLT" },
  { id: "est-estabilidades-02", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Qual o período de estabilidade do dirigente sindical e como ele pode ser dispensado?", v: "Desde o registro da candidatura até um ano após o fim do mandato. A dispensa só cabe por falta grave apurada em inquérito judicial.", b: "Art. 8º, VIII, CF; Súmula 379 do TST", p: "O dirigente perde o mandato se pedir ou aceitar voluntariamente transferência que dificulte suas funções (art. 543, § 1º, CLT)." },
  { id: "est-estabilidades-03", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Quais os limites da estabilidade sindical segundo a Súmula 369 do TST?", v: "Limita-se a 7 dirigentes e igual número de suplentes; a comunicação fora das 24 horas não afasta a estabilidade se o empregador souber durante o contrato; acaba com a extinção da atividade na base territorial; e não há estabilidade se a candidatura for registrada no aviso prévio, ainda que indenizado.", b: "Súmula 369 do TST; art. 522 da CLT", p: "Membros do conselho fiscal e delegados sindicais não têm estabilidade." },
  { id: "est-estabilidades-04", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Qual o período de estabilidade da gestante e ela depende de comunicação ao empregador?", v: "Da confirmação da gravidez até cinco meses após o parto, inclusive se confirmada no aviso prévio. Basta estar grávida na dispensa: o desconhecimento do empregador não afasta o direito.", b: "Art. 10, II, b, ADCT; art. 391-A da CLT; Súmula 244, I, TST", p: "Vale também no contrato por prazo determinado e de experiência (Súmula 244, III, TST)." },
  { id: "est-estabilidades-05", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "O que a gestante dispensada recebe se a estabilidade já tiver terminado e ajuizar a ação depois desse período é abuso?", v: "Se o período já se esgotou, não há reintegração, mas indenização dos salários da dispensa até o fim da estabilidade. Ajuizar a ação após o fim do período não é abuso de direito; o limite é a prescrição.", b: "Súmula 396, I, TST; OJ 399 da SDI-1 do TST", p: "Recusar a oferta de retorno ao trabalho não é renúncia: mantém o direito à indenização substitutiva." },
  { id: "est-estabilidades-06", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Quando é válido o pedido de demissão da gestante e quem mais tem a estabilidade?", v: "Só com assistência do sindicato ou da autoridade local competente. A estabilidade alcança quem obtém guarda provisória para adoção, a doméstica e, se a mãe morrer, quem ficar com a guarda do filho.", b: "Art. 500 da CLT; art. 391-A, parágrafo único, CLT; LC 146/2014; LC 150/2015" },
  { id: "est-estabilidades-07", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Quem tem estabilidade na CIPA e qual o período?", v: "Os representantes dos empregados eleitos para a CIPA, titulares e suplentes, desde o registro da candidatura até um ano após o fim do mandato. Os designados pelo empregador não têm.", b: "Art. 10, II, a, ADCT; Súmula 676 do STF" },
  { id: "est-estabilidades-08", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Como pode ser dispensado o cipeiro e o que ocorre se o estabelecimento fechar?", v: "Não exige inquérito, mas a dispensa precisa de motivo disciplinar, técnico, econômico ou financeiro. Extinto o estabelecimento, a estabilidade perde o sentido, sem reintegração nem indenização.", b: "Art. 165 da CLT; Súmula 339 do TST" },
  { id: "est-estabilidades-09", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Quais os requisitos e o prazo da estabilidade do acidentado?", v: "12 meses após o fim do auxílio-doença acidentário, exigindo afastamento superior a 15 dias e recebimento do benefício. Aplica-se também ao contrato por prazo determinado.", b: "Art. 118 da Lei 8.213/91; Súmula 378 do TST", p: "Doença ocupacional constatada após a dispensa, com nexo com o trabalho, garante a estabilidade mesmo sem afastamento nem benefício." },
  { id: "est-estabilidades-10", d: "Direito do Trabalho", r: "E", t: "Estabilidades", f: "Quem tem estabilidade na Comissão de Conciliação Prévia e na comissão de representantes dos empregados?", v: "Na CCP, só os membros eleitos pelos empregados, titulares e suplentes, até um ano após o mandato, salvo falta grave. Na comissão de representantes (empresas com mais de 200 empregados), do registro da candidatura até um ano após o mandato, vedada só a dispensa arbitrária.", b: "Art. 625-B, § 1º, CLT; arts. 510-A a 510-D da CLT" }
]);
